import type { FieldOption, FieldSpec } from "./schema";
import {
  APPEARANCE_STATES,
  APPEARANCE_STATE_LABELS,
  LENSES,
  LENS_LABELS,
  TONES,
  TONE_LABELS,
} from "./appearance";

const STATE_OPTIONS: FieldOption[] = APPEARANCE_STATES.map((state) => ({
  value: state,
  label: APPEARANCE_STATE_LABELS[state],
  // `received` is runtime-only — stays pickable, but not worth rolling.
  ...(state === "received" ? { randomize: false } : {}),
}));

const TONE_OPTIONS: FieldOption[] = TONES.map((tone) => ({
  value: tone,
  label: TONE_LABELS[tone],
}));

const LENS_OPTIONS: FieldOption[] = LENSES.map((lens) => ({
  value: lens,
  label: LENS_LABELS[lens],
}));

/**
 * WHY the whole bundle declares `section: "appearance"`: it is shared by
 * Port, Pill, Glyph, TextBox, Bar and Block, so declaring the section HERE
 * gives every one of them a correctly-headed Appearance run for free — the
 * same argument `APPEARANCE_FIELDS` already won for the fields themselves.
 * Figma's panel has an Appearance section for the same reason: it is the
 * one group that means the same thing on every kind of object.
 */
export const APPEARANCE_SECTION = "appearance";

export const STATE_FIELD: FieldSpec = {
  id: "state",
  label: "State",
  kind: "segments",
  defaultValue: "empty",
  options: STATE_OPTIONS,
  section: APPEARANCE_SECTION,
  hint: "`received` is runtime-only — never persisted (PERSISTABLE_APPEARANCE_STATES).",
};

export const TONE_FIELD: FieldSpec = {
  id: "tone",
  label: "Tone",
  kind: "segments",
  defaultValue: "neutral",
  options: TONE_OPTIONS,
  section: APPEARANCE_SECTION,
  hint: "Escape hatch for a component not colouring by state. Writes an override, not a preset — see appearance.ts's toneOverride.",
};

export const LENS_FIELD: FieldSpec = {
  id: "lens",
  label: "Lens",
  kind: "segments",
  defaultValue: "normal",
  options: LENS_OPTIONS,
  section: APPEARANCE_SECTION,
};

/**
 * NOT in APPEARANCE_FIELDS, deliberately.
 *
 * `lensBefore` is a real prop — Pill and Port both accept it — but neither
 * renders it, and Block forwards it to a chip that drops it. Declaring it
 * put a live control into 27 story panels that moved nothing at all, which
 * is precisely the "a control that does nothing reads as broken" complaint
 * this library exists to answer. A field array is a promise that changing a
 * row changes the component; a field with no visual consequence breaks that
 * promise wholesale.
 *
 * It stays exported so the declaration is ready the day a lens actually
 * paints a before-value, and so removing it is one line to undo.
 */
export const LENS_BEFORE_FIELD: FieldSpec = {
  id: "lensBefore",
  label: "Lens: Before Value",
  kind: "text",
  defaultValue: "",
  hint: "The pre-change value a diff lens compares against. Empty when `lens === \"normal\"`.",
};

/**
 * The shared bundle. Spread into a component's own field array —
 * `[...APPEARANCE_FIELDS, ...OWN_FIELDS]` — never nested under an
 * `appearance` object. See docs/T1-SPEC.md §2 for which components
 * include it and which deliberately don't.
 */
export const APPEARANCE_FIELDS: FieldSpec[] = [
  STATE_FIELD,
  TONE_FIELD,
  LENS_FIELD,
];

/**
 * bbox-ui appearance — the shared semantic emphasis axis.
 *
 * WHY a separate file from layout.ts: layout.ts is portable GEOMETRY
 * (frozen for T1, see docs/T1-SPEC.md §0); this is portable SEMANTICS —
 * which of six emphasis states a thing is in, and the token names (not
 * hex values) that state resolves to. Both are React-free, engine-free.
 */

/* -------------------------------------------------------------- */
/* State — the six-rung emphasis ladder                            */
/* -------------------------------------------------------------- */

/**
 * Board vocabulary (Zach, 2026-09-10 ruling), NARROWED 2026-09-12 (Zach's
 * ruling on the port-props proposal — see docs/T1-SPEC.md §2.4): `empty ·
 * value set · wired · data received`. This is the VALUE axis only — "what
 * is in the port/pill" — and it is the only axis a document persists.
 *
 * `outOfFocus` and `hidden` used to be two more rungs of this same union,
 * but neither is a fact about what a thing IS: `outOfFocus` is a fact
 * about what the HOST is doing to it right now (dimmed while ineligible
 * mid-drag, or simply out of focus) and never survives a reload, while
 * `hidden` is a visibility toggle a container counts into "+N more" —
 * painting nothing is not a seventh kind of content. Splitting them out
 * stops one enum from doing three unrelated jobs: see `Port`'s own
 * `dimmed` (host-set, boolean, never persisted) and `hidden` (author-set,
 * boolean, persisted, same shape as `bar.fields.ts`'s existing `hidden`)
 * in `./port.tsx`/`./port.fields.ts`.
 */
export type AppearanceState = "empty" | "valueSet" | "wired" | "received";

export const APPEARANCE_STATES: AppearanceState[] = ["empty", "valueSet", "wired", "received"];

/** Board labels verbatim, including Zach's own spelling of "Recived". */
export const APPEARANCE_STATE_LABELS: Record<AppearanceState, string> = {
  empty: "Empty",
  valueSet: "Default Value",
  wired: "Wired",
  received: "Data Recived",
};

/**
 * States a document format may persist. `received` means "data flowed
 * through this just now" — only a live host can know that; persisting it
 * would lie after reload. Runtime-only, host-sourced, never written to a
 * document.
 */
export const PERSISTABLE_APPEARANCE_STATES = ["empty", "valueSet", "wired"] as const;

/** The three-channel reading every state resolves to: a ring/ink emphasis,
 * whether a fill is present, and whether the small inner "core" dot lights
 * up. `null` in any channel means "that layer does not paint at all" —
 * `wired` keeps a hollow ring (PORT-SPEC's disc) and lights only the core,
 * distinguishing it from `received`'s fully solid circle at a glance
 * without inventing a seventh state. Values are TOKEN NAMES (no leading
 * `--`) — resolve with `var(--${token})`, never a literal colour. See §3
 * for the actual token values and the contrast math behind them. */
export interface StateTokenPair {
  ring: string | null;
  fill: string | null;
  core: string | null;
}

export const STATE_TOKENS: Record<AppearanceState, StateTokenPair> = {
  empty: { ring: "foreground", fill: null, core: null },
  valueSet: { ring: "muted-foreground", fill: "muted", core: null },
  wired: { ring: "primary", fill: null, core: "primary" },
  received: { ring: "bbox-received", fill: "bbox-received", core: "bbox-received" },
};

/* -------------------------------------------------------------- */
/* Tone — the escape hatch for a component not colouring by state  */
/* -------------------------------------------------------------- */

export type Tone = "neutral" | "accent" | "warning" | "success" | "danger";

export const TONES: Tone[] = ["neutral", "accent", "warning", "success", "danger"];

export const TONE_LABELS: Record<Tone, string> = {
  neutral: "Neutral",
  accent: "Accent",
  warning: "Warning",
  success: "Success",
  danger: "Danger",
};

/** `null` for `neutral` — it means "let state drive," not "paint nothing." */
export const TONE_TOKENS: Record<Tone, string | null> = {
  neutral: null,
  accent: "bbox-accent",
  warning: "bbox-warning",
  success: "bbox-success",
  danger: "bbox-danger",
};

/**
 * `tone` is NOT a preset — it is sugar that WRITES the override layer.
 * WHY: `state` and `tone` would otherwise be two preset families both
 * claiming the same paint fields, which `assertDisjointPresets` (§1)
 * correctly forbids (two different selectors, one governed property).
 * Modelling `tone` as "component logic that computes an override" instead
 * keeps the trace honest: when `tone !== "neutral"` wins, the field's
 * FieldTrace reports `winner: "override"`, which is literally true — a
 * tone reaches past whatever the state preset would have supplied,
 * exactly as a hand-typed override would. See each consuming component's
 * `.tsx` (Pill §4.3, Block §4.8) for the one-line call site; the pattern
 * is always: `{ ...instanceProps, ...toneOverride(tone, governedFieldIds) }`
 * spread onto the subject BEFORE calling `resolveFields`.
 */
export function toneOverride(
  tone: Tone,
  fieldIds: readonly string[],
): Record<string, string> | undefined {
  const token = TONE_TOKENS[tone];
  if (!token) return undefined;
  return Object.fromEntries(fieldIds.map((id) => [id, token]));
}

/* -------------------------------------------------------------- */
/* Lens — the diff/lint overlay, layered over everything above     */
/* -------------------------------------------------------------- */

export type Lens = "normal" | "added" | "removed" | "changed" | "error" | "warning";

export const LENSES: Lens[] = ["normal", "added", "removed", "changed", "error", "warning"];

export const LENS_LABELS: Record<Lens, string> = {
  normal: "Normal",
  added: "Added",
  removed: "Removed",
  changed: "Changed",
  error: "Error",
  warning: "Warning",
};

/**
 * A paint token name → the CSS that paints it.
 *
 * WHY "primary" is special-cased and everything else is `var(--<token>)`:
 * "wired" paints with the design system's own accent, not with whatever the
 * HOST uses for its buttons. Inside bbox-ui.com, shadcn's neutral --primary is
 * near-black, so a wired Pill became a black capsule with dark ink on it and
 * a wired Port dot went black. --bbox-primary is ours; the fallback keeps a
 * host that defines only --primary looking exactly as before.
 *
 * Both Pill's paint map and Port's tone blend go through here — a second
 * template string building `var(--${token})` is how the Port kept the bug an
 * hour after the Pill lost it.
 */
export function paintVar(token: string): string {
  return token === "primary" ? "var(--bbox-primary, var(--primary))" : `var(--${token})`;
}

/**
 * packages/bbox-ui/src/badge.fields.ts
 *
 * `Badge`'s controllable props as data — every `id` below is a real
 * `BadgeProps` key (see `./badge.tsx`). `BADGE_SIZES` is Badge's own small
 * rung ladder (the `GLYPH_SIZES`/`PILL_SIZES` convention: each
 * schema-driven component keeps its own scale, in its own file) — `md`'s
 * numbers are `PortCountBadge`'s (port.tsx) original measured chip,
 * carried forward exactly rather than re-approximated.
 */
import type { FieldOption, FieldSpec, PresetSpec } from "./schema";

export interface BadgeSizeSpec {
  height: number;
  fontSize: number;
  radius: number;
  paddingX: number;
}

export const BADGE_SIZES: Record<"sm" | "md" | "lg", BadgeSizeSpec> = {
  sm: { height: 14, fontSize: 9, radius: 6, paddingX: 4 },
  // `md` = `PortCountBadge`'s exact original numbers: 16px tall,
  // `rounded-[7px]`, `text-[10px]`, `px-[5px]`, min-width equal to height.
  md: { height: 16, fontSize: 10, radius: 7, paddingX: 5 },
  lg: { height: 20, fontSize: 11, radius: 8, paddingX: 6 },
};
export type BadgeSize = keyof typeof BADGE_SIZES;

export const BADGE_SIZE_LABELS: Record<BadgeSize, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
};

const SIZE_OPTIONS: FieldOption[] = (Object.keys(BADGE_SIZES) as BadgeSize[]).map((size) => ({
  value: size,
  label: `${BADGE_SIZE_LABELS[size]} · ${BADGE_SIZES[size].height}px`,
}));

export const BADGE_FIELDS: FieldSpec[] = [
  {
    id: "hidden",
    label: "Hidden",
    kind: "toggle",
    defaultValue: false,
    hint: "Renders nothing — same shape as PortDot/PortLabel's own `hidden`.",
  },
  {
    id: "size",
    label: "Size",
    kind: "segments",
    defaultValue: "md",
    options: SIZE_OPTIONS,
    cascades: true,
    tier: "simple",
  },
  {
    id: "children",
    label: "Text",
    kind: "text",
    // Must equal `Badge`'s OWN real default, which is the empty string —
    // a FieldSpec default that disagrees with the component is an
    // inspector that lies about the preview beside it. It declared "4"
    // and a fresh Badge rendered blank (found by an adversarial judge,
    // 2026-09-15). "4" is not a property of every Badge; it is what
    // Port's secondary slot happens to seed, and that belongs in
    // `PORT_SLOTS`' own `fillMembers` — where it already is.
    defaultValue: "",
    tier: "simple",
    hint: "The chip's text — a plain string. Empty renders an empty chip at its minimum width.",
  },
];

/** No board or donor state axis governs anything on Badge yet — empty per
 * the every-schema-driven-component-exports-one convention (see
 * `GLYPH_PRESETS`'s own WHY). */
export const BADGE_PRESETS: PresetSpec[] = [];

"use client";

import type { ComponentProps } from "react";

import { cn } from "./lib/utils";
import { SketchOutline } from "./sketchOutline";
import { BADGE_SIZES, type BadgeSize } from "./badge.fields";

export interface BadgeProps extends Omit<ComponentProps<"span">, "children"> {
  /** The chip's text — a plain string, never rich content: this is a
   * count/tag chip (Port's secondary slot holding an "Event" text tag or
   * a "4" count side by side), not a generic slot. */
  children?: string;
  /** Size rung — `md` (the default) reproduces `PortCountBadge`'s
   * original measured look byte-for-byte; see `BADGE_SIZES`. */
  size?: BadgeSize;
  /** Author-set, persisted — same shape as `PortDot`/`PortLabel`'s own
   * `hidden`: painting nothing is a visibility fact, not a variant. */
  hidden?: boolean;
}

/**
 * Badge — a small rounded count/tag chip, pulled out of `port.tsx`'s
 * hardcoded `PortCountBadge` so Port's now-generic secondary slot can hold
 * more than one of them side by side (an "Event" text tag next to a "4"
 * count). `Badge` itself knows nothing about ports or producer counts —
 * it just renders whatever string it's given.
 *
 * DEVIATION: no `tone`/`state`. Wiring either through `./appearance`
 * properly means either `Port`'s ring/fill/core blend (`portDotStyle`,
 * `toneColor`) or `Pill`'s full preset/`resolveField` cascade
 * (`pillResolutionSubject`) — both model a shape (a ring, a line-vs-fill
 * duality) this flat, single-layer chip doesn't have. Half-wiring a `tone`
 * that only recolours text, with no preset behind it, is exactly the
 * "control that does nothing real" failure `appearance.fields.ts`'s own
 * `lensBefore` deviation warns about. Left out until a real donor shows
 * what a toned/stateful Badge looks like.
 */
export function Badge({
  // A REAL default, so the component's own output and `BADGE_FIELDS`'
  // declared default are the same fact rather than two that happen to
  // look alike. An omitted `children` used to read back `undefined`,
  // which no `FieldValue` can encode — so the field had to declare
  // something else, and did ("4"), and the inspector then disagreed with
  // the preview beside it.
  children = "",
  size = "md",
  hidden = false,
  className,
  style,
  ...props
}: BadgeProps) {
  if (hidden) return null;
  const { height, fontSize, radius, paddingX } = BADGE_SIZES[size];
  return (
    <span
      data-slot="badge"
      data-size={size}
      className={cn(
        "relative flex items-center justify-center bg-foreground/10 font-semibold text-foreground",
        className,
      )}
      style={{
        height,
        minWidth: height,
        borderRadius: radius,
        paddingLeft: paddingX,
        paddingRight: paddingX,
        fontSize,
        lineHeight: `${height}px`,
        ...style,
      }}
      {...props}
    >
      {/* A Badge has no border of its own — it is a tinted chip — so the
          sketch skin gives it one rather than replacing one. Its ink is the
          skin's, not a state's: nothing in the cascade governs a Badge's
          colour, which is exactly why it may use `--bbox-skin-ink`. */}
      <SketchOutline
        stretch
        width={40}
        height={20}
        borderWidth={1.5}
        radius={radius}
        seed={`badge:${size}`}
      />
      {children}
    </span>
  );
}

/**
 * packages/bbox-ui/src/bar.fields.ts
 *
 * `Bar`'s controllable props as data. `edge`, `left`, `center` and `right`
 * are deliberately absent: the edge follows from which slot the bar fills
 * and the three cells are slots of its own — structural, never a row.
 */
import type { FieldSpec } from "./schema";

import { APPEARANCE_FIELDS } from "./appearance.fields";
import { BAR_LINE_FIELDS } from "./bar.presets";
import { BAR_SIZE_LABELS, BAR_SIZES } from "./bar";

export const BAR_SIZE_FIELD: FieldSpec = {
  id: "size",
  label: "Size",
  kind: "segments",
  defaultValue: "md",
  options: BAR_SIZES.map((s) => ({ value: s, label: BAR_SIZE_LABELS[s] })),
  // The rung a header hands down: every slot inside inherits it, and each
  // member inside those may override it locally.
  cascades: true,
  hint: "Sets the bar's height and is the size its members inherit.",
};

export const BAR_FIELDS: FieldSpec[] = [
  { id: "hidden", label: "Hidden", kind: "toggle", defaultValue: false, hint: "The Block draws nothing for this region; its members are kept." },
  { id: "line", label: "Line", kind: "toggle", defaultValue: true, hint: "The dividing line toward the body." },
  BAR_SIZE_FIELD,
  { id: "padding", label: "Padding", kind: "number", defaultValue: 6, min: 0, max: 32, unit: "px" },
  ...APPEARANCE_FIELDS,
  ...BAR_LINE_FIELDS,
];

export { BAR_PRESETS } from "./bar.presets";

/**
 * packages/bbox-ui/src/bar.presets.ts
 *
 * The line of a Bar is painted by the same state ladder a Pill's ring is:
 * `state` selects a preset governing `lineStyle` and `lineColor`. Rather
 * than a second paint table, the presets are Pill's own, narrowed to the
 * two line fields — one ladder, two components, no drift.
 */
import type { FieldSpec, PresetSpec } from "./schema";

import { PILL_PAINT_FIELDS } from "./pill.fields";
import { PILL_PRESETS } from "./pill.presets";

const LINE_GOVERNS = ["lineStyle", "lineColor"];

export const BAR_PRESETS: PresetSpec[] = PILL_PRESETS.map((preset) => ({
  ...preset,
  governs: LINE_GOVERNS,
  values: Object.fromEntries(LINE_GOVERNS.map((id) => [id, preset.values[id]])),
}));

/** Pill's four line rows — style, colour, thickness, opacity — reused verbatim. */
export const BAR_LINE_FIELDS: FieldSpec[] = PILL_PAINT_FIELDS.filter((f) => f.id.startsWith("line"));

export const BAR_LINE_FIELD_BY_ID = Object.fromEntries(BAR_LINE_FIELDS.map((f) => [f.id, f])) as Record<
  "lineStyle" | "lineColor" | "lineThickness" | "lineOpacity",
  FieldSpec
>;

import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { resolveField } from "./schema";

import type { AppearanceState, Lens, Tone } from "./appearance";
import { paintVar, toneOverride } from "./appearance";
import { BAR_LINE_FIELD_BY_ID, BAR_PRESETS } from "./bar.presets";
import { cn } from "./lib/utils";
import { SketchLine } from "./sketchOutline";
import type { PaintToken, PillLineStyle, PillLineThickness } from "./pill.fields";

/**
 * packages/bbox-ui/src/bar.tsx
 *
 * Bar = a Block's header AND its footer. Zach, 2026-09-11: "the header and
 * the footer are basically the exact same on the block... we will fill
 * them differently but they are basically the same." One component, two
 * slots on the Block, filled differently.
 *
 * Three slots of its own (left · center · right) on a 1fr · auto · 1fr
 * grid so the centre is truly centred whatever the sides hold; a dividing
 * line toward the body that can be turned off and that takes the normal
 * appearance cascade for its paint (state · tone · lens, plus the same
 * line style / colour / thickness / opacity rows a Pill's ring has); a
 * `size` rung (sm · md · lg · xl) that sets the bar's own height and is
 * the value its slots inherit; and `hidden`, which the Block honours by
 * drawing nothing for that region.
 *
 * WHY `hidden` and `line` are two toggles and not one opacity: Zach —
 * "instead of overloading that, I do think the actual intent is probably
 * just to hide the line". An opacity slider would be a third way to say
 * off. The line's opacity still exists, as the appearance row it always
 * was, for the times it is on.
 */

export const BAR_SIZES = ["sm", "md", "lg", "xl"] as const;
export type BarSize = (typeof BAR_SIZES)[number];
export const BAR_SIZE_LABELS: Record<BarSize, string> = { sm: "Small", md: "Medium", lg: "Large", xl: "Extra Large" };
/** The bar's own minimum height per rung; its members bring their own scale. */
export const BAR_MIN_HEIGHT: Record<BarSize, number> = { sm: 28, md: 36, lg: 48, xl: 60 };

const LINE_THICKNESS_PX: Record<PillLineThickness, number> = { thin: 1, med: 2, thick: 3 };
const BORDER_STYLE_CSS: Record<PillLineStyle, NonNullable<CSSProperties["borderStyle"]>> = {
  solid: "solid",
  dashed: "dashed",
  dotted: "dotted",
  none: "none",
};

export interface BarProps extends Omit<ComponentProps<"div">, "children"> {
  /** Which way the body is: a header's line sits at its bottom, a footer's
   *  at its top. Not a field — it follows from which slot the bar fills. */
  edge?: "bottom" | "top";
  hidden?: boolean;
  line?: boolean;
  size?: BarSize;
  /** px inset of the bar. */
  padding?: number;
  state?: AppearanceState;
  tone?: Tone;
  lens?: Lens;
  lineStyle?: PillLineStyle;
  lineColor?: PaintToken;
  lineThickness?: PillLineThickness;
  lineOpacity?: number;
  left?: ReactNode;
  center?: ReactNode;
  right?: ReactNode;
}

export function Bar({
  edge = "bottom",
  hidden = false,
  line = true,
  size = "md",
  padding = 6,
  state = "empty",
  tone = "neutral",
  lens = "normal",
  lineStyle,
  lineColor,
  lineThickness = "med",
  lineOpacity = 1,
  left,
  center,
  right,
  className,
  style,
  ...props
}: BarProps) {
  // The line's paint goes through the same cascade a Pill's ring does:
  // `state` selects a preset that governs lineStyle / lineColor, `tone`
  // folds into the override layer, an explicit prop wins.
  // Tone folds into the override layer for the line colour (a Pill does the
  // same for its ring); an explicit lineColor prop still wins.
  const subject: Record<string, unknown> = { state, ...toneOverride(tone, ["lineColor"]), lineStyle, lineColor };
  for (const k of Object.keys(subject)) if (subject[k] === undefined) delete subject[k];
  void lens;
  const lineStyleResolved = resolveField(BAR_LINE_FIELD_BY_ID.lineStyle, subject, BAR_PRESETS).resolved as PillLineStyle;
  const lineColorResolved = resolveField(BAR_LINE_FIELD_BY_ID.lineColor, subject, BAR_PRESETS).resolved as PaintToken;
  const lineWidth = line && lineStyleResolved !== "none" ? LINE_THICKNESS_PX[lineThickness] : 0;
  const borderStyle = BORDER_STYLE_CSS[lineStyleResolved] as CSSProperties["borderBottomStyle"];
  const lineCss: CSSProperties =
    edge === "bottom" ? { borderBottomWidth: lineWidth, borderBottomStyle: borderStyle } : { borderTopWidth: lineWidth, borderTopStyle: borderStyle };
  if (hidden) return <div data-slot="bar" data-edge={edge} data-hidden="true" hidden />;
  return (
    <div
      data-slot="bar"
      data-edge={edge}
      data-size={size}
      data-line={line}
      data-state={state}
      data-tone={tone}
      className={cn("relative grid w-full min-w-0 items-center", className)}
      style={{
        gridTemplateColumns: "1fr auto 1fr",
        gap: 8,
        padding: `${padding}px ${padding + 4}px`,
        minHeight: BAR_MIN_HEIGHT[size],
        // Same split as Pill's ring: only the sketch skin defines
        // `--bbox-skin-line-override`, and it names no colour — the drawn
        // rule below is handed the colour this cascade resolved.
        borderColor: `var(--bbox-skin-line-override, ${paintVar(lineColorResolved)})`,
        // WHY opacity on the colour and not on the bar: the members keep
        // their own paint; only the line fades.
        ...(lineOpacity < 1 ? { borderColor: `var(--bbox-skin-line-override, color-mix(in srgb, ${paintVar(lineColorResolved)} ${Math.round(lineOpacity * 100)}%, transparent))` } : {}),
        ...lineCss,
        ...style,
      }}
      {...props}
    >
      {lineWidth > 0 && (
        // A Bar's line is a single RULE along one edge, not a closed
        // outline — the header band's separator. One stretched, jittered
        // segment is the whole shape.
        <SketchLine
          edge={edge}
          thickness={lineWidth}
          stroke={paintVar(lineColorResolved)}
          seed={`bar:${edge}:${lineColorResolved}`}
        />
      )}
      <div data-slot="bar-cell" data-cell="left" style={{ minWidth: 0, display: "flex", alignItems: "center", justifyContent: "flex-start" }}>
        {left}
      </div>
      <div data-slot="bar-cell" data-cell="center" style={{ minWidth: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
        {center}
      </div>
      <div data-slot="bar-cell" data-cell="right" style={{ minWidth: 0, display: "flex", alignItems: "center", justifyContent: "flex-end" }}>
        {right}
      </div>
    </div>
  );
}

/**
 * packages/bbox-ui/src/block.fields.ts
 *
 * `Block`'s first `FieldSpec` array (T1-SPEC.md §4.8 — Block was never
 * given one in T0). Two of `Block`'s/`BlockHeader`'s own real props
 * (`width`/`height`, `orientation`) plus the shared `APPEARANCE_FIELDS`
 * bundle. `state`/`tone`/`lens`/`lensBefore` are NOT props of `Block`
 * itself — they route through the SAME cascade to whichever child is a
 * `<BlockChip>` (now a thin `<Pill>` wrapper, `./block.tsx`), so a story
 * or host wires them onto that child; wherever no chip is composed, they
 * are simply inert (§4.8's own "forwarded … only when a chip is present,
 * else inert").
 *
 * `VIEW_FIELD` and the six face fields below (P2 "views are presets",
 * reports/view-switching-proposals-2026-09-11.html) are new: `view`
 * selects one of `block.presets.ts`'s three `BLOCK_PRESETS`, each
 * governing a closed set over the six face fields plus width/height. The
 * face fields' own defaults equal the "simple" preset's values, so a bare
 * `BlockFace` (`./blockFace.tsx`) resolves identically through preset or
 * default — the same "bare == the obvious preset" invariant `port.fields.ts`
 * already carries for `size`.
 *
 * WHY no `bodyLayout`/paint fields here: `Block`'s body-layout integration
 * (`Stack`/`Flex` composition) and its own literal paint fields are
 * explicitly deferred, non-goals for this lane (T1-SPEC.md §4.8, §10) —
 * this array is intentionally narrow, not an oversight.
 */
import type { FieldOption, FieldSpec } from "./schema";
import { APPEARANCE_FIELDS } from "./appearance.fields";
import { SIMPLE_BLOCK } from "./layout";
import { BLOCK_RADIUS_DEFAULT } from "./block";
import { BLOCK_VIEWS, BLOCK_VIEW_LABELS } from "./block.view";

/* ------------------------------------------------------------------ */
/* view — the selector (P2 "views are presets")                        */
/* ------------------------------------------------------------------ */

const VIEW_OPTIONS: FieldOption[] = BLOCK_VIEWS.map((view) => ({
  value: view,
  label: BLOCK_VIEW_LABELS[view],
}));

export const VIEW_FIELD: FieldSpec = {
  id: "view",
  label: "View",
  kind: "segments",
  defaultValue: "simple",
  options: VIEW_OPTIONS,
  hint: "Selects the Simple / Port / Expanded preset; every governed row below traces back to it.",
};

/* ------------------------------------------------------------------ */
/* The six face fields a view preset governs                           */
/* ------------------------------------------------------------------ */

export const BLOCK_HEADER_MODES = ["centered", "band"] as const;
export type BlockHeaderMode = (typeof BLOCK_HEADER_MODES)[number];
export const BLOCK_HEADER_MODE_LABELS: Record<BlockHeaderMode, string> = {
  centered: "Centered",
  band: "Band",
};

export const BLOCK_PORTS_MODES = ["anonymous", "rows", "walls"] as const;
export type BlockPortsMode = (typeof BLOCK_PORTS_MODES)[number];
export const BLOCK_PORTS_MODE_LABELS: Record<BlockPortsMode, string> = {
  anonymous: "Anonymous",
  rows: "Rows",
  walls: "Walls",
};

export const BLOCK_MEMBERS_MODES = ["hidden", "shown"] as const;
export type BlockMembersMode = (typeof BLOCK_MEMBERS_MODES)[number];
export const BLOCK_MEMBERS_MODE_LABELS: Record<BlockMembersMode, string> = {
  hidden: "Hidden",
  shown: "Shown",
};

export const BLOCK_TYPE_PLACEMENTS = ["bottom", "header"] as const;
export type BlockTypePlacement = (typeof BLOCK_TYPE_PLACEMENTS)[number];
export const BLOCK_TYPE_PLACEMENT_LABELS: Record<BlockTypePlacement, string> = {
  bottom: "Bottom",
  header: "Header",
};

/**
 * Defaults equal the "simple" preset's own values (see `block.presets.ts`)
 * — a `BlockFace` with no `view`/override set resolves through the
 * `default` cascade layer to exactly what `view: "simple"` resolves
 * through the `preset` layer, so the two are indistinguishable to a
 * reader, exactly Pill's own paint-field default discipline.
 */
export const HEADER_FIELD: FieldSpec = {
  id: "header",
  label: "Header",
  kind: "segments",
  defaultValue: "centered",
  options: BLOCK_HEADER_MODES.map((v) => ({ value: v, label: BLOCK_HEADER_MODE_LABELS[v] })),
  hint: "Centered: Simple's hand-rolled icon+title stack. Band: an edge-to-edge Bar.",
};

export const PORTS_FIELD: FieldSpec = {
  id: "ports",
  label: "Ports",
  kind: "segments",
  defaultValue: "anonymous",
  options: BLOCK_PORTS_MODES.map((v) => ({ value: v, label: BLOCK_PORTS_MODE_LABELS[v] })),
  hint: "Anonymous: stable ids only, nothing painted. Rows: a list in the body. Walls: dots on the boundary.",
};

export const MEMBERS_FIELD: FieldSpec = {
  id: "members",
  label: "Members",
  kind: "segments",
  defaultValue: "hidden",
  options: BLOCK_MEMBERS_MODES.map((v) => ({ value: v, label: BLOCK_MEMBERS_MODE_LABELS[v] })),
  hint: "Shown mounts the body region; hidden paints nothing (the member list itself is untouched).",
};

export const DESCRIPTION_FIELD: FieldSpec = {
  id: "description",
  label: "Description",
  kind: "toggle",
  defaultValue: true,
};

export const TYPE_PLACEMENT_FIELD: FieldSpec = {
  id: "typePlacement",
  label: "Type Placement",
  kind: "segments",
  defaultValue: "bottom",
  options: BLOCK_TYPE_PLACEMENTS.map((v) => ({ value: v, label: BLOCK_TYPE_PLACEMENT_LABELS[v] })),
};

export const FOOTER_FIELD: FieldSpec = {
  id: "footer",
  label: "Footer",
  kind: "toggle",
  defaultValue: false,
};

export const WIDTH_FIELD: FieldSpec = {
  id: "width",
  label: "Width",
  kind: "number",
  defaultValue: SIMPLE_BLOCK.width,
  unit: "px",
  group: "size",
  section: "layout",
};

export const HEIGHT_FIELD: FieldSpec = {
  id: "height",
  label: "Height",
  kind: "number",
  defaultValue: SIMPLE_BLOCK.height,
  unit: "px",
  group: "size",
  section: "layout",
};

export const RADIUS_FIELD: FieldSpec = {
  id: "radius",
  label: "Radius",
  kind: "number",
  defaultValue: BLOCK_RADIUS_DEFAULT,
  min: 0,
  max: 32,
  unit: "px",
  // WHY radius and orientation join width/height under one `section` while
  // staying OUT of their `group`: `group` is "these share a line" (width
  // beside height); `section` is "these share a heading". Figma's own panel
  // draws exactly this distinction — X and Y on one line, both under
  // Position. See FieldSpec.section.
  section: "layout",
  hint: "0 is edge-to-edge. The header and footer clip to it.",
};

export const BLOCK_ORIENTATIONS = ["horizontal", "vertical"] as const;
export type BlockOrientation = (typeof BLOCK_ORIENTATIONS)[number];

export const ORIENTATION_FIELD: FieldSpec = {
  id: "orientation",
  label: "Orientation",
  kind: "segments",
  defaultValue: "horizontal",
  options: BLOCK_ORIENTATIONS.map((o) => ({
    value: o,
    label: o === "horizontal" ? "Horizontal" : "Vertical",
  })),
  section: "layout",
};

/**
 * `view` first (the selector), then the six face fields it governs, then
 * Block's own geometry fields, then the shared bundle — matching
 * T1-SPEC.md §4.8's original row order (width/height, orientation, then
 * state/tone/lens/lensBefore) for everything after the new view fields,
 * the reverse of `Pill`'s own bundle-first ordering (`pill.fields.ts`)
 * since here the bundle fields don't belong to `Block` itself.
 */
export const BLOCK_FIELDS: FieldSpec[] = [
  VIEW_FIELD,
  HEADER_FIELD,
  PORTS_FIELD,
  MEMBERS_FIELD,
  DESCRIPTION_FIELD,
  TYPE_PLACEMENT_FIELD,
  FOOTER_FIELD,
  WIDTH_FIELD,
  HEIGHT_FIELD,
  RADIUS_FIELD,
  ORIENTATION_FIELD,
  ...APPEARANCE_FIELDS,
];

/**
 * packages/bbox-ui/src/block.presets.ts
 *
 * `BLOCK_PRESETS` is Block's first real preset family (P2 "views are
 * presets", reports/view-switching-proposals-2026-09-11.html): `view`
 * (`block.fields.ts`'s `VIEW_FIELD`) selects one of three mutually
 * exclusive alternatives, each governing a CLOSED set of eight fields —
 * header/ports/members/description/typePlacement/footer, plus width and
 * height — through the SAME `resolveField` cascade Pill's `state` already
 * runs (`pill.presets.ts`). `blockFace.tsx`'s renderer resolves every
 * governed field through this cascade and is a TOTAL LOOKUP over the
 * result; it never branches on `view` directly, so a panel tracing "why
 * does this field have this value" is tracing the exact computation that
 * produced the pixels, not a second, informal description of it.
 *
 * `state`/`tone` are UNAFFECTED by any of this: `Block` still forwards
 * them to its internal `<BlockChip>` (a `<Pill>` wrapper), which resolves
 * its OWN `PILL_PRESETS` — chip paint stays there, exactly as
 * `block.fields.ts`'s own module doc already describes. `view`'s governed
 * set never touches a paint field, so the two preset families (`"view"`
 * here, `"state"` inside the chip's own `Pill`) never collide —
 * `assertDisjointPresets` only ever sees this file's own selector.
 */
import type { PresetSpec } from "./schema";
import { BLOCK_VIEWS, BLOCK_VIEW_DEFAULT_SIZES, BLOCK_VIEW_LABELS, type BlockView } from "./block.view";
import type {
  BlockHeaderMode,
  BlockMembersMode,
  BlockPortsMode,
  BlockTypePlacement,
} from "./block.fields";

export const BLOCK_PRESET_GOVERNS = [
  "header",
  "ports",
  "members",
  "description",
  "typePlacement",
  "footer",
  "width",
  "height",
];

// WHY a total Record and not a ternary/switch: same defensive shape as
// pill.presets.ts's own PRESET_PAINT and port.presets.ts's own
// PRESET_SIZE — a loose index signature would let a fourth view typecheck
// clean and throw at render time reading a governed field off `undefined`.
//
// WHY the value type is an inline object literal and not a separate named
// `interface` (as a first pass here had it): `PresetSpec.values` is typed
// `Partial<Record<string, FieldValue>>`, and TypeScript only extends the
// implicit-index-signature allowance that makes an object type assignable
// there to FRESH object-literal types — a separately named `interface`
// does not get it, and fails with "index signature is missing" even
// though every member is structurally a `FieldValue`. `pill.presets.ts`'s
// own `PRESET_PAINT` and `port.presets.ts`'s own `PRESET_SIZE` are both
// inline for the same reason.
const PRESET_FACE: Record<
  BlockView,
  {
    header: BlockHeaderMode;
    ports: BlockPortsMode;
    members: BlockMembersMode;
    description: boolean;
    typePlacement: BlockTypePlacement;
    footer: boolean;
    width: number;
    height: number;
  }
> = {
  simple: {
    header: "centered",
    ports: "anonymous",
    members: "hidden",
    description: true,
    typePlacement: "bottom",
    footer: false,
    width: BLOCK_VIEW_DEFAULT_SIZES.simple.w,
    height: BLOCK_VIEW_DEFAULT_SIZES.simple.h,
  },
  port: {
    header: "band",
    ports: "rows",
    members: "hidden",
    description: false,
    typePlacement: "header",
    footer: true,
    width: BLOCK_VIEW_DEFAULT_SIZES.port.w,
    height: BLOCK_VIEW_DEFAULT_SIZES.port.h,
  },
  expanded: {
    header: "band",
    ports: "walls",
    members: "shown",
    description: false,
    typePlacement: "header",
    footer: false,
    width: BLOCK_VIEW_DEFAULT_SIZES.expanded.w,
    height: BLOCK_VIEW_DEFAULT_SIZES.expanded.h,
  },
};

export const BLOCK_PRESETS: PresetSpec[] = BLOCK_VIEWS.map((view) => ({
  id: view,
  label: BLOCK_VIEW_LABELS[view],
  selector: "view",
  governs: BLOCK_PRESET_GOVERNS,
  values: PRESET_FACE[view],
}));

import {
  Children,
  Fragment,
  isValidElement,
  type ComponentProps,
  type ReactElement,
  type ReactNode,
} from "react";

import { cn } from "./lib/utils";
import {
  BLOCK_BORDER_PX,
  CHIP,
  CHIP_RIGHT_IN_HEADER_PX,
  HEADER_CHIP_RESERVED_PX,
  META_FONT_PX,
  SIMPLE_BLOCK,
  TEXT_SIZES,
  glyphPx,
  type TextSize,
} from "./layout";
import { Pill, type PillProps } from "./pill";
import { SKETCH_OUTLINE_BLEED_PX, SketchOutline } from "./sketchOutline";
import type { BlockOrientation } from "./block.fields";

/**
 * Block anatomy (Zach's vocabulary — the component API uses these names):
 * Container, Header band, Glyph (icon), Text slot, Chip. (Disclosure, Dot,
 * Port and Region arrive with later views.)
 */

/**
 * Corner radius in px. 0 is edge-to-edge; the bars clip to it.
 *
 * Still the DEFAULT, but no longer applied by `Block` itself: an unset
 * `radius` resolves to `--bbox-skin-radius`, whose own fallback is this
 * number (see `skin.css` and `skin.ts`'s `BBOX_SKIN_TOKENS`). Passing a
 * number still wins outright — an explicit prop outranks a skin exactly
 * as an override outranks a preset in the field cascade. `RADIUS_FIELD`
 * (block.fields.ts) keeps this as its declared default, so a
 * panel-driven Block stays pinned to 8 and ignores the skin until that
 * field can say "auto" — the proposal's open decision D2.
 */
export const BLOCK_RADIUS_DEFAULT = 8;

export interface BlockProps extends ComponentProps<"div"> {
  /** Container size. Defaults to the Simple View spec, 384 × 258. */
  width?: number;
  height?: number;
  /**
   * Corner radius, px. Zach, 2026-09-11: "sometimes we may want radius, but
   * sometimes in like edge to edge mode we may not want any radius" — a
   * number, not a rung (D3), so 0 means exactly square.
   *
   * Unset means "let the skin decide" — `var(--bbox-skin-radius, 8px)`.
   */
  radius?: number;
  /**
   * Stable string the sketch skin's hand-drawn outline is generated from.
   * Same seed, same wobble, every render — see `sketchPath.ts` on why an
   * unseeded random shimmers.
   *
   * Defaults to `id` when one is given, else the box's own size. WHY that
   * fallback and not a counter: a counter is not stable across a server
   * render and its hydration, and it would renumber when a list reorders.
   * The cost is that two same-sized Blocks with no `id` wobble identically
   * — visible as repetition in a grid, which is why a host that has real
   * ids (both adapters do) should pass one.
   */
  sketchSeed?: string;
}

/**
 * Container — Simple View. Content is horizontally centered; the header
 * band and description center vertically while `BlockType` pins to the
 * bottom edge, matching the wireframe's five variants.
 */
export function Block({
  width = SIMPLE_BLOCK.width,
  height = SIMPLE_BLOCK.height,
  radius,
  sketchSeed,
  id,
  className,
  style,
  children,
  ...props
}: BlockProps) {
  return (
    <div
      data-slot="block"
      id={id}
      data-radius={radius}
      className={cn(
        "relative flex flex-col items-center justify-center gap-1 px-4 text-center",
        // Text colour is a skin token because a skin may remove the surface
        // it was contrasting against: the sketch skin paints no fill, so
        // `text-card-foreground` would be reading against a card that is not
        // there. Fallback is the exact class this replaced.
        "text-[color:var(--bbox-skin-fg,var(--color-card-foreground))]",
        // The skin seam (skin.ts / skin.css). Each token carries today's
        // value as its own `var()` fallback, which is what lets skin.css
        // stay optional: a consumer who never imports it renders the exact
        // pixels this line replaced (`border-2 border-foreground bg-card`).
        //
        // WHY these stay Tailwind utilities rather than moving into the
        // `style` bag: `cn`'s tailwind-merge still dedupes them against a
        // caller's own `className`, so `<Block className="bg-red-500">`
        // keeps working. An inline style would silently outrank it.
        // `border-solid` is explicit because a host without Tailwind's
        // preflight defaults to `border-style: none`, where a width alone
        // paints nothing at all.
        "border-solid border-[length:var(--bbox-skin-stroke-width,2px)] border-[color:var(--bbox-skin-stroke,var(--color-foreground))]",
        "bg-[var(--bbox-skin-surface,var(--color-card))] shadow-[var(--bbox-skin-shadow,none)]",
        // Set once on the container; every text slot below inherits it, so
        // the sketch skin needs no per-slot font prop.
        //
        // One text slot is NOT uniform, and the capture is what caught it:
        // a CodeField (Port's label slot) inherits this like everything
        // else UNLESS the host also imports `codeField.css`, whose
        // `.cm-scroller` rule pins monospace and wins. Storybook imports
        // it; the demos and apps/docs do not. So the same board renders
        // sketch-font port labels in one host and monospace ones in
        // another. Whether code text should resist a skin is a real taste
        // call, not a bug to paper over — the proposal's open decision D3.
        "font-[family-name:var(--bbox-skin-font,inherit)]",
        className,
      )}
      // `overflow: clip` (not hidden) so the corners cut the bars' lines
      // without turning the Block into a scroll container.
      style={{
        width,
        height,
        borderRadius: radius ?? "var(--bbox-skin-radius, 8px)",
        overflow: "clip",
        // Lets the sketch outline paint over the border box it is drawn on,
        // plus the slack its wobble needs. `overflow: clip` otherwise clips
        // children at the PADDING box, which would shave the drawn line by
        // the border width and flatten its outward bulges — a hand-drawn
        // line with a perfectly straight segment where it was loosest. A
        // length (measured from the padding box) rather than `border-box`,
        // because `border-box` alone still trims the bulge. The bars keep
        // clipping to the corners, which is what `clip` was here for; a
        // browser without `overflow-clip-margin` trims the outline instead
        // of breaking.
        overflowClipMargin: `${BLOCK_BORDER_PX + SKETCH_OUTLINE_BLEED_PX}px`,
        ...style,
      }}
      {...props}
    >
      <SketchOutline
        width={width}
        height={height}
        borderWidth={BLOCK_BORDER_PX}
        seed={sketchSeed ?? id ?? `${width}x${height}`}
      />
      {children}
    </div>
  );
}

// WHY a total lookup rather than `orientation === "vertical" && ...`: a
// boolean branch renders every unknown member as the horizontal default, so
// widening BLOCK_ORIENTATIONS shipped a panel segment that silently did
// nothing and typecheck stayed green (a judge proved it with "diagonal").
// Record<BlockOrientation, string> is total, so adding a member is a compile
// error until someone says what it paints.
const HEADER_ORIENTATION_CLASS: Record<BlockOrientation, string> = {
  horizontal: "",
  vertical: "flex-col gap-1",
};

/**
 * Is there a BlockChip anywhere in this header's children?
 *
 * WHY it recurses: `Children.toArray` flattens arrays but does NOT descend
 * into Fragments, so a chip wrapped in one went undetected, the header
 * skipped the space it reserves for it, and the chip painted over the
 * title's last letters — exactly the collision the reservation exists to
 * prevent. No shipped caller hits it today, but this is the last site of the
 * same class that made PortEdge's cascade land on a Fragment and reach no
 * Port at all.
 */
function containsChip(children: ReactNode): boolean {
  return Children.toArray(children).some((child) => {
    if (!isValidElement(child)) return false;
    if (child.type === BlockChip) return true;
    if (child.type === Fragment) {
      return containsChip((child as ReactElement<{ children?: ReactNode }>).props.children);
    }
    return false;
  });
}

export interface BlockHeaderProps extends ComponentProps<"header"> {
  orientation?: BlockOrientation;
}

/**
 * Header band: Glyph + Title, with an optional Chip out of flow on the
 * right. `vertical` stacks the Glyph above the Title (the board's
 * icon-above-title variant).
 *
 * When a Chip is among the children, the header reserves the chip's region
 * (`HEADER_CHIP_RESERVED_PX` of right padding) and lets the title truncate
 * with a visible ellipsis inside what remains.
 * WHY: the chip used to be purely out of flow so a centred title never
 * shifted when a tag appeared — but that traded a shift for a collision
 * (the chip painted over the title's last letters), and a collision is
 * worse. The board's own geometry says the chip RESERVES its span: title
 * right edge 10px clear of the chip, chip 28px in from the container edge.
 */
export function BlockHeader({
  orientation = "horizontal",
  className,
  style,
  children,
  ...props
}: BlockHeaderProps) {
  // WHY detect the chip instead of taking a `hasChip` prop: adapters already
  // state "chip present" by rendering <BlockChip>; a flag would be the same
  // fact answered a second time in every adapter (the layout.ts rule: any
  // mapping that appears in both adapters is a bug).
  const hasChip = containsChip(children);
  return (
    <header
      data-slot="block-header"
      data-orientation={orientation}
      data-has-chip={hasChip || undefined}
      className={cn(
        "relative flex w-full items-center justify-center gap-2",
        HEADER_ORIENTATION_CLASS[orientation],
        // min-w-0 lets the flexed title actually shrink below its text;
        // truncate ellipsizes it — never a silent clip, never text under
        // the chip. Scoped to chip-bearing headers so a chipless block
        // renders exactly as before.
        hasChip &&
          "[&>[data-slot=block-title]]:min-w-0 [&>[data-slot=block-title]]:truncate",
        className,
      )}
      style={
        hasChip ? { paddingRight: HEADER_CHIP_RESERVED_PX, ...style } : style
      }
      {...props}
    >
      {children}
    </header>
  );
}

export interface BlockGlyphProps extends ComponentProps<"span"> {
  /** Title rung the glyph rides on — the glyph never sizes independently. */
  size?: TextSize;
}

/**
 * Glyph (icon). Sized at 0.9 × the title font size.
 * WHY: board rule, written by Zach — "The Icon and Title always go next to
 * each other. The icon should resize with the title text size." Sizing is
 * derived, not a free prop, so the two can never drift apart.
 */
export function BlockGlyph({
  size = "xl",
  className,
  style,
  ...props
}: BlockGlyphProps) {
  const px = glyphPx(size);
  return (
    <span
      data-slot="block-glyph"
      className={cn(
        "flex shrink-0 items-center justify-center leading-none [&>svg]:h-full [&>svg]:w-full",
        className,
      )}
      style={{ width: px, height: px, fontSize: px, ...style }}
      {...props}
    />
  );
}

export interface BlockTitleProps extends ComponentProps<"h3"> {
  size?: TextSize;
}

/** Text slot for the title. Three rungs: md 24 / lg 36 / xl 44. */
export function BlockTitle({
  size = "xl",
  className,
  style,
  title,
  children,
  ...props
}: BlockTitleProps) {
  return (
    <h3
      data-slot="block-title"
      data-size={size}
      className={cn("select-none font-medium leading-tight", className)}
      style={{ fontSize: TEXT_SIZES[size], ...style }}
      // WHY: constrained geometry (a chip-bearing header) may ellipsize the
      // rendered title; the title attribute keeps the complete authored
      // string immediately discoverable. Presentation only — the data is
      // never shortened.
      title={title ?? (typeof children === "string" ? children : undefined)}
      {...props}
    >
      {children}
    </h3>
  );
}

export interface BlockChipProps extends PillProps {}

/**
 * Chip — the oval tag ("Warning Tags go here to the right", e.g. `Draft 1`).
 * Out of flow, inset `CHIP_INSET_RIGHT` from the container's right edge.
 * Its region is reserved by `BlockHeader` (see there), so the title centres
 * in the space that remains instead of running underneath.
 *
 * T1-SPEC.md §4.8: a thin wrapper around the real `<Pill>` — the one
 * concrete reuse every per-component doc that touched `BlockChip`
 * independently recommended — so `state`/`tone` reach the chip through the
 * SAME cascade `Pill` already runs (`resolveField` against `PILL_PRESETS`)
 * rather than a second, parallel colour system living here. Geometry
 * (`CHIP`, `CHIP_RIGHT_IN_HEADER_PX`, `blockLayout.ts`'s box for it) is
 * untouched — only the painted shell changes. Defaulting to `state:
 * "empty"` reproduces the exact look this chip always had (a hollow
 * `foreground` outline, no fill), so every existing caller (the tldraw and
 * React Flow adapters, both of which render a bare `<BlockChip>{tag}</BlockChip>`
 * with no state/tone) is visually unchanged.
 */
export function BlockChip({
  state = "empty",
  tone = "neutral",
  className,
  style,
  children,
  ...props
}: BlockChipProps) {
  return (
    <Pill
      // WHY set explicitly (and BEFORE `...props`, so an explicit caller
      // override still wins): this chip is a real, external DOM contract
      // (`demos/drive.mjs` selects `[data-slot="block-chip"]`) — `Pill`'s
      // own default `data-slot="pill"` would silently break that selector.
      data-slot="block-chip"
      state={state}
      tone={tone}
      className={cn("absolute top-1/2 -translate-y-1/2", className)}
      style={{
        // The measured 28px container-edge inset, in the header's frame.
        right: CHIP_RIGHT_IN_HEADER_PX,
        minWidth: CHIP.minWidth,
        height: CHIP.height,
        fontSize: META_FONT_PX,
        ...style,
      }}
      {...props}
    >
      {children}
    </Pill>
  );
}

/** Text slot for the one-line description under the header band. */
export function BlockDescription({
  className,
  style,
  ...props
}: ComponentProps<"p">) {
  return (
    <p
      data-slot="block-description"
      className={cn("text-muted-foreground", className)}
      style={{ fontSize: META_FONT_PX, ...style }}
      {...props}
    />
  );
}

/** Text slot for the block's type, pinned to the bottom of the container. */
export function BlockType({ className, style, ...props }: ComponentProps<"span">) {
  return (
    <span
      data-slot="block-type"
      className={cn(
        "absolute bottom-3 left-1/2 -translate-x-1/2 whitespace-nowrap text-muted-foreground",
        className,
      )}
      style={{ fontSize: META_FONT_PX, ...style }}
      {...props}
    />
  );
}

/**
 * packages/bbox-ui/src/block.view.ts
 *
 * Block's three views (Simple / Port / Expanded), as pure data — no React,
 * no DOM, same discipline as `layout.ts`/`port.layout.ts`. `block.fields.ts`
 * turns `BLOCK_VIEWS` into a real `FieldSpec` (`VIEW_FIELD`) and
 * `block.presets.ts` turns it into `BLOCK_PRESETS`, Block's first real
 * `PresetSpec` family (P2 "views are presets",
 * reports/view-switching-proposals-2026-09-11.html). This file is only the
 * closed vocabulary and the per-view "remembered box" bookkeeping a host
 * needs when a person resizes one view and then switches to another.
 */
import { SIMPLE_BLOCK } from "./layout";

export const BLOCK_VIEWS = ["simple", "port", "expanded"] as const;
export type BlockView = (typeof BLOCK_VIEWS)[number];
export const BLOCK_VIEW_LABELS: Record<BlockView, string> = {
  simple: "Simple",
  port: "Port",
  expanded: "Expanded",
};

export interface ViewSize {
  w: number;
  h: number;
}

export type BlockViewSizes = Record<BlockView, ViewSize>;

/**
 * The Port/Expanded boxes are derived from the wireframe's own proportions
 * at the 384px Simple width — the 2026-09-11 report's own caveat: these
 * are a starting pin, not a measurement, and want correcting against a
 * real running board later. Simple's box comes from `SIMPLE_BLOCK`
 * (`layout.ts`) rather than a second literal, so the two can never drift.
 */
export const BLOCK_VIEW_DEFAULT_SIZES: BlockViewSizes = {
  simple: { w: SIMPLE_BLOCK.width, h: SIMPLE_BLOCK.height },
  port: { w: 384, h: 346 },
  expanded: { w: 707, h: 452 },
};

/**
 * Parks `current` (the box the view being left is at RIGHT NOW, including
 * any live resize) under `from`'s own slot — immutably — then hands back
 * the box `to` should use, from that updated bag.
 *
 * WHY parked BEFORE the target is restored: ported from SystemSketch's
 * `setBlockViewProps` (src/blocks/blockModel.ts), minus the fold logic
 * this repo has no concept of. Both host adapters must route every view
 * switch through this ONE helper — forget it in one and Expanded opens at
 * whatever Port's box happened to be, instead of its own remembered size.
 */
export function parkViewSize(
  sizes: BlockViewSizes,
  from: BlockView,
  to: BlockView,
  current: ViewSize,
): { sizes: BlockViewSizes; size: ViewSize } {
  const parked: BlockViewSizes = { ...sizes, [from]: current };
  return { sizes: parked, size: parked[to] };
}

import type { ComponentProps, ReactNode } from "react";
import { resolveField } from "./schema";

import { cn } from "./lib/utils";
import type { AppearanceState } from "./appearance";
import { META_FONT_PX, type TextSize } from "./layout";
import {
  Block,
  BlockChip,
  BlockDescription,
  BlockGlyph,
  BlockHeader,
  BlockTitle,
  BlockType,
} from "./block";
import {
  BLOCK_FIELDS,
  type BlockHeaderMode,
  type BlockMembersMode,
  type BlockOrientation,
  type BlockPortsMode,
  type BlockTypePlacement,
} from "./block.fields";
import { BLOCK_PRESETS } from "./block.presets";
import type { BlockView } from "./block.view";
import { Bar } from "./bar";
import { Glyph } from "./glyph";
import { TextBox } from "./textBox";
import { Pill } from "./pill";
import { Flex } from "./flex";
import { LabeledPort, Port, PortLabel } from "./port";
import {
  PORT_DIAMETERS,
  PORT_DOT_CENTER_TRANSFORM,
  inwardTextLayout,
  portDotPlacement,
  portLabelPlacement,
  portSideForDirection,
  type BlockSide,
  type PortDirection,
  type PortSize,
  type PortSizeRung,
} from "./port.layout";

/**
 * packages/bbox-ui/src/blockFace.tsx
 *
 * The renderer half of P2 "views are presets"
 * (reports/view-switching-proposals-2026-09-11.html): `resolveBlockFace`
 * runs `view` and the eight governed fields through the SAME
 * `resolveField` cascade `block.presets.ts`'s `BLOCK_PRESETS` describes,
 * and `BlockFace` paints the result. Every structural decision below is a
 * TOTAL LOOKUP keyed by a RESOLVED field — never a `switch (view)`, never
 * a `view === "…"` comparison (a `data-view` attribute for probing is the
 * one place `view` shows up bare). That is the whole point of P2: a panel
 * tracing why a face looks the way it does is tracing this exact
 * computation, never a second, informal description of it.
 */

/* ------------------------------------------------------------------ */
/* Data shapes                                                         */
/* ------------------------------------------------------------------ */

export interface BlockFacePort {
  id: string;
  direction: PortDirection;
  name?: string;
  typeLabel?: string;
  state?: AppearanceState;
  /** 0→1 along whichever side `direction` maps to. Omit for an even
   * spread among the ports sharing that side (`BlockPortWalls`'s own
   * default). */
  t?: number;
}

/** `name`/`typeLabel` composed into the single line `Port`/`PortLabel`
 * now render as `children` — "a port is one line of code" (`port.tsx`'s
 * own `PortLabelProps` docblock), same `name: Type` shape every other
 * real caller in this workspace already uses. */
function blockFacePortLabel(port: Pick<BlockFacePort, "name" | "typeLabel">): string {
  if (!port.name) return "";
  return port.typeLabel ? `${port.name}: ${port.typeLabel}` : port.name;
}

export interface BlockFaceData {
  title: string;
  typeLabel?: string;
  description?: string;
  icon?: ReactNode;
  tag?: string;
  titleSize?: TextSize;
  ports?: BlockFacePort[];
}

export interface BlockFaceFields {
  view: BlockView;
  header: BlockHeaderMode;
  ports: BlockPortsMode;
  members: BlockMembersMode;
  description: boolean;
  typePlacement: BlockTypePlacement;
  footer: boolean;
  width: number;
  height: number;
}

/* ------------------------------------------------------------------ */
/* resolveBlockFace — the cascade, run once, shared by panel and paint */
/* ------------------------------------------------------------------ */

const FACE_FIELD_IDS = [
  "view",
  "header",
  "ports",
  "members",
  "description",
  "typePlacement",
  "footer",
  "width",
  "height",
] as const;

// Looked up once from BLOCK_FIELDS (never re-typed) — pill.tsx's own
// PAINT_FIELD_BY_ID pattern — so `resolveField` runs the SAME computation
// a product inspector's trace panel would read.
const FACE_FIELD_BY_ID = Object.fromEntries(
  FACE_FIELD_IDS.map((id) => [id, BLOCK_FIELDS.find((f) => f.id === id)!]),
) as Record<(typeof FACE_FIELD_IDS)[number], (typeof BLOCK_FIELDS)[number]>;

/**
 * Resolves `view` and the eight governed face fields against
 * `BLOCK_FIELDS`/`BLOCK_PRESETS`.
 *
 * WHY exported: the same reason `pillResolutionSubject` (`pill.tsx`) is —
 * a story, a bench, or a product inspector's trace panel must resolve
 * against the SAME computation `BlockFace` itself paints with, or the
 * trace and the pixels drift apart (`pill.tsx`'s own WHY names the exact
 * bug this already caused once, for Pill's `tone`).
 */
export function resolveBlockFace(subject: Record<string, unknown>): BlockFaceFields {
  const clean: Record<string, unknown> = {};
  for (const key of Object.keys(subject)) {
    if (subject[key] !== undefined) clean[key] = subject[key];
  }
  const value = (id: (typeof FACE_FIELD_IDS)[number]) =>
    resolveField(FACE_FIELD_BY_ID[id], clean, BLOCK_PRESETS).resolved;
  return {
    view: value("view") as BlockView,
    header: value("header") as BlockHeaderMode,
    ports: value("ports") as BlockPortsMode,
    members: value("members") as BlockMembersMode,
    description: value("description") as boolean,
    typePlacement: value("typePlacement") as BlockTypePlacement,
    footer: value("footer") as boolean,
    width: value("width") as number,
    height: value("height") as number,
  };
}

/* ------------------------------------------------------------------ */
/* PORTS — one total lookup per ports mode                             */
/* ------------------------------------------------------------------ */

/**
 * "anonymous": ports stay in the DOM with stable ids (so edges/bindings
 * survive a view switch) at their normal boundary anchor, but paint
 * nothing — no dot, `visibility: "hidden"`. Not exported: nothing outside
 * `PORTS_RENDER` needs "an anonymous port" as its own component.
 */
function anonymousPorts(ports: BlockFacePort[], width: number, height: number): ReactNode {
  return (
    <>
      {ports.map((port) => {
        const side = portSideForDirection(port.direction);
        const placement = portDotPlacement(side, port.t ?? 0.5, width, height);
        return (
          <div
            key={port.id}
            data-port-id={port.id}
            data-slot="block-port-anonymous"
            className="absolute"
            style={{
              left: placement.left,
              top: placement.top,
              transform: PORT_DOT_CENTER_TRANSFORM,
              visibility: "hidden",
            }}
          />
        );
      })}
    </>
  );
}

export interface BlockPortRowsProps {
  ports: BlockFacePort[];
  size?: PortSizeRung;
}

/**
 * "rows": one row per port in the body area, dot at the row's direction
 * edge with the name flowing inward, inputs before outputs.
 *
 * WHY this reuses `Port` wholesale rather than reassembling `Port` +
 * `PortLabel` by hand: `Port`'s own docblock (`port.tsx`) is explicit that
 * the paired flex-row rendering is for "a standalone specimen", and a row
 * in a list is exactly that — never a wall-mounted absolute position,
 * which is the one case `Port`/`PortLabel` must be split apart for
 * (`BlockPortWalls`, below). One real `Port` per row also gets the
 * direction-mirrored name/type ordering for free instead of a second copy
 * of it here.
 */
export function BlockPortRows({ ports, size = "sm" }: BlockPortRowsProps) {
  const ordered = [
    ...ports.filter((p) => p.direction === "input"),
    ...ports.filter((p) => p.direction === "output"),
  ];
  return (
    <Flex
      data-slot="block-port-rows"
      direction="column"
      align="stretch"
      gap={4}
      // WHY the 8px horizontal padding: rows mode renders inside Block's
      // edge-to-edge (px-0) band, so a row dot at the row's very end paints
      // its ring past the padding box and Block's overflow:clip flat-cuts
      // it at the wall. 8px matches the bench body's own inset.
      style={{ width: "100%", padding: "0 8px" }}
    >
      {ordered.map((port) => (
        <div key={port.id} data-port-id={port.id} style={{ width: "100%" }}>
          <LabeledPort
            direction={port.direction}
            edge={portSideForDirection(port.direction)}
            state={port.state ?? "empty"}
            size={size}
          >
            {blockFacePortLabel(port)}
          </LabeledPort>
        </div>
      ))}
    </Flex>
  );
}

export interface BlockPortWallsProps {
  ports: BlockFacePort[];
  width: number;
  height: number;
  diameter?: PortSize;
}

/**
 * "walls": real `Port`s at their boundary anchor, label placed inward —
 * the same `portDotPlacement`/`PORT_DOT_CENTER_TRANSFORM`/
 * `portLabelPlacement` geometry `block-shape-util.tsx`'s live tldraw
 * adapter already uses for the Simple view's own ports. A port without an
 * authored `t` gets an even spread among the ports sharing its side —
 * `(index + 1) / (count + 1)` keeps every dot clear of both corners
 * whatever the count.
 */
export function BlockPortWalls({ ports, width, height, diameter = "md" }: BlockPortWallsProps) {
  const bySide = new Map<BlockSide, BlockFacePort[]>();
  for (const port of ports) {
    const side = portSideForDirection(port.direction);
    const siblings = bySide.get(side);
    if (siblings) siblings.push(port);
    else bySide.set(side, [port]);
  }
  const diameterPx = typeof diameter === "number" ? diameter : PORT_DIAMETERS[diameter];
  return (
    <>
      {ports.map((port) => {
        const side = portSideForDirection(port.direction);
        const siblings = bySide.get(side) ?? [port];
        const index = siblings.indexOf(port);
        const t = port.t ?? (index + 1) / (siblings.length + 1);
        const placement = portDotPlacement(side, t, width, height);
        const textLayout = inwardTextLayout(side);
        return (
          <div
            key={port.id}
            data-port-id={port.id}
            data-slot="block-port-wall"
            className="absolute"
            style={{ left: placement.left, top: placement.top, transform: PORT_DOT_CENTER_TRANSFORM }}
          >
            <Port state={port.state ?? "empty"} diameter={diameter} />
            {port.name && (
              <PortLabel
                className="absolute"
                style={portLabelPlacement(textLayout, { w: diameterPx, h: diameterPx })}
                direction={port.direction}
              >
                {blockFacePortLabel(port)}
              </PortLabel>
            )}
          </div>
        );
      })}
    </>
  );
}

interface FaceRenderCtx {
  data: BlockFaceData;
  resolved: BlockFaceFields;
  orientation: BlockOrientation;
  bandContent?: ReactNode;
  /** The muted type node when `typePlacement === "header"` — computed
   * once by `TYPE_RENDER` and handed to whichever `HEADER_RENDER` entry
   * needs to place it, so there is exactly one node, never two. */
  typeInline: ReactNode;
}

/**
 * Block's own `overflow: clip` (block.tsx) exists so a Bar's line clips at
 * the rounded corner rather than poking past it — but a wall-mounted port
 * dot straddles the OUTER boundary on purpose (the usual port convention:
 * half in, half out), which clip amputates clean off. Measured live:
 * demos/screenshots/block-views-hosts/tl-port.png shows the flat-cut rings.
 * Only "walls" mode ever straddles the boundary, so only it relaxes clip —
 * a total lookup (not a ternary) so a future ports mode has to say what it
 * wants here rather than silently inheriting "anonymous"/"rows"' clip.
 */
const PORTS_OVERFLOW: Record<BlockPortsMode, "visible" | undefined> = {
  anonymous: undefined,
  rows: undefined,
  walls: "visible",
};

const PORTS_RENDER: Record<BlockPortsMode, (ctx: FaceRenderCtx) => ReactNode> = {
  anonymous: (ctx) => anonymousPorts(ctx.data.ports ?? [], ctx.resolved.width, ctx.resolved.height),
  rows: (ctx) => <BlockPortRows ports={ctx.data.ports ?? []} />,
  walls: (ctx) => (
    <BlockPortWalls ports={ctx.data.ports ?? []} width={ctx.resolved.width} height={ctx.resolved.height} />
  ),
};

/* ------------------------------------------------------------------ */
/* TYPE — one total lookup over typePlacement, returning BOTH the       */
/* bottom-pinned node and the in-header node (at most one is ever real) */
/* ------------------------------------------------------------------ */

interface TypeNodes {
  /** Rendered as a direct `Block` child, always — `null` under "header". */
  bottom: ReactNode;
  /** Handed to `HEADER_RENDER` to place inside the band's right cell (or,
   * for the centered+header hybrid, inline at the header row's end) —
   * `null` under "bottom". */
  inline: ReactNode;
}

const TYPE_RENDER: Record<BlockTypePlacement, (data: BlockFaceData) => TypeNodes> = {
  bottom: (data) => ({
    bottom: data.typeLabel ? <BlockType>{data.typeLabel}</BlockType> : null,
    inline: null,
  }),
  header: (data) => ({
    bottom: null,
    inline: data.typeLabel ? (
      <TextBox key="type-inline" size="sm" lines="single" className="text-muted-foreground">
        {data.typeLabel}
      </TextBox>
    ) : null,
  }),
};

/* ------------------------------------------------------------------ */
/* HEADER — one total lookup over header mode                          */
/* ------------------------------------------------------------------ */

/**
 * The band composes Block's first surface out of the shared Bar/Glyph/
 * TextBox primitives instead of a third hand-rolled header (T1-SPEC.md
 * §10's deferred item, done here for the band only). Simple's hand-rolled
 * centered header deliberately stays untouched — its pixels are pinned by
 * `blockLayout.ts`'s `layoutSimpleBlock` mirror and the detach/compare
 * harnesses, and rebuilding it atop `Bar` would be a large blast radius
 * for zero visual change.
 */
export interface BlockBandProps {
  data: BlockFaceData;
  /** The muted in-band type node (typePlacement === "header"), if any. */
  typeInline?: ReactNode;
}

/**
 * EXPORTED (not just BlockFace's internal default) because both host
 * adapters paint this same band around their own connectable port
 * elements — a hand-copied band in each adapter is exactly the drift the
 * one-Bar-band-composition exists to prevent.
 */
export function BlockBand({ data, typeInline }: BlockBandProps) {
  return (
    <Bar
      edge="bottom"
      size="md"
      left={
        <>
          {/* `sizePreset`, not `size`: Glyph v2 split the old single `size`
              prop into a PRESET layer (this) and a numeric px OVERRIDE
              layer (`size`, written by a canvas resize handle). Passing
              "md" to `size` now means "12 pixels"-shaped nonsense, not the
              medium preset. */}
          {data.icon !== undefined && <Glyph sizePreset="md">{data.icon}</Glyph>}
          <TextBox size="md" lines="single">
            {data.title}
          </TextBox>
        </>
      }
      right={
        <>
          {typeInline}
          {data.tag ? <Pill size="sm">{data.tag}</Pill> : null}
        </>
      }
    />
  );
}

function defaultBand(ctx: FaceRenderCtx): ReactNode {
  return <BlockBand data={ctx.data} typeInline={ctx.typeInline} />;
}

const HEADER_RENDER: Record<BlockHeaderMode, (ctx: FaceRenderCtx) => ReactNode> = {
  centered: (ctx) => {
    const { data, resolved } = ctx;
    return (
      <>
        <BlockHeader orientation={ctx.orientation}>
          {data.icon !== undefined && <BlockGlyph size={data.titleSize}>{data.icon}</BlockGlyph>}
          <BlockTitle size={data.titleSize}>{data.title}</BlockTitle>
          {data.tag ? <BlockChip>{data.tag}</BlockChip> : null}
          {ctx.typeInline}
        </BlockHeader>
        {resolved.description && data.description ? (
          <BlockDescription>{data.description}</BlockDescription>
        ) : null}
      </>
    );
  },
  band: (ctx) => {
    const { data, resolved } = ctx;
    return (
      <>
        {ctx.bandContent ?? defaultBand(ctx)}
        {resolved.description && data.description ? (
          <p
            data-slot="block-face-description"
            className="text-muted-foreground"
            style={{ fontSize: META_FONT_PX, padding: "0 8px" }}
          >
            {data.description}
          </p>
        ) : null}
      </>
    );
  },
};

/**
 * Block's own default classes centre everything for the Simple face; a
 * band face is an edge-to-edge region stacked from the top instead — the
 * same override `bench.tsx`'s own slotted Block composition already uses
 * (`className="!justify-start !px-0 !text-left"`). No `!important` needed
 * here: `cn`'s `tailwind-merge` resolves the conflicting utility classes
 * on its own once these come after Block's own defaults.
 */
const CONTAINER_CLASS: Record<BlockHeaderMode, string | undefined> = {
  centered: undefined,
  band: "flex-col items-stretch justify-start px-0 text-left",
};

/* ------------------------------------------------------------------ */
/* MEMBERS — a total two-key lookup                                    */
/* ------------------------------------------------------------------ */

const MEMBERS_RENDER: Record<BlockMembersMode, (content: ReactNode) => ReactNode> = {
  hidden: () => null,
  // The record/list itself is untouched by this switch — hiding is
  // canvas-only (block.fields.ts's own MEMBERS_FIELD hint).
  shown: (content) => (
    <div data-slot="block-face-members" style={{ width: "100%" }}>
      {content}
    </div>
  ),
};

/* ------------------------------------------------------------------ */
/* BlockFace                                                           */
/* ------------------------------------------------------------------ */

export interface BlockFaceProps
  extends Partial<BlockFaceFields>,
    Omit<ComponentProps<"div">, "children"> {
  /** Ungoverned pass-through to `Block`'s own prop of the same name. */
  radius?: number;
  /** Ungoverned pass-through to `BlockHeader`'s own prop of the same name
   * — only consulted by the "centered" header mode. */
  orientation?: BlockOrientation;
  data: BlockFaceData;
  /** What the body shows when `members` resolves to "shown". */
  membersContent?: ReactNode;
  /** Overrides the whole band region when `header` resolves to "band" —
   * the `/create` bench injects its own composed `Bar` here. */
  bandContent?: ReactNode;
  footerContent?: ReactNode;
}

/**
 * `BlockFace` = Block's view-aware face: resolves `view` and its eight
 * governed fields through `resolveBlockFace`, then paints the result
 * through total lookups only (`HEADER_RENDER`/`PORTS_RENDER`/
 * `MEMBERS_RENDER`/`TYPE_RENDER`, plus the plain boolean `footer` gate —
 * see this file's own module doc for the hard rule this observes).
 *
 * WHY every resolved-field prop is destructured WITHOUT a JS default,
 * mirroring `Pill`'s own paint fields (`pill.tsx`): an explicit value is
 * exactly what makes a subject's OVERRIDE candidate present in
 * `resolveField`. A `= "simple"` default here would make every
 * `BlockFace`'s raw props carry a `view`, so the cascade would report
 * `winner: "override"` even when nobody reached past the preset.
 */
export function BlockFace({
  view,
  header,
  ports,
  members,
  description,
  typePlacement,
  footer,
  width,
  height,
  radius,
  orientation,
  data,
  membersContent,
  bandContent,
  footerContent,
  className,
  style,
  ...props
}: BlockFaceProps) {
  const resolved = resolveBlockFace({
    view,
    header,
    ports,
    members,
    description,
    typePlacement,
    footer,
    width,
    height,
  });
  const typeNodes = TYPE_RENDER[resolved.typePlacement](data);
  const ctx: FaceRenderCtx = {
    data,
    resolved,
    orientation: orientation ?? "horizontal",
    bandContent,
    typeInline: typeNodes.inline,
  };

  return (
    <Block
      data-slot="block-face"
      data-view={resolved.view}
      data-header={resolved.header}
      data-ports={resolved.ports}
      data-members={resolved.members}
      width={resolved.width}
      height={resolved.height}
      radius={radius}
      className={cn(CONTAINER_CLASS[resolved.header], className)}
      // WHY the conditional spread, not a bare `overflow: PORTS_OVERFLOW[…]`:
      // an `overflow: undefined` key would MERGE OVER Block's own
      // `overflow: "clip"` (block.tsx spreads this style last) and unset it —
      // React drops undefined-valued style keys, so the computed overflow
      // falls back to `visible` and the Bar-corner clip silently dies in
      // rows/anonymous modes. Measured live on the RF host, 2026-09-14.
      style={{ ...(PORTS_OVERFLOW[resolved.ports] ? { overflow: PORTS_OVERFLOW[resolved.ports] } : null), ...style }}
      {...props}
    >
      {HEADER_RENDER[resolved.header](ctx)}
      {MEMBERS_RENDER[resolved.members](membersContent)}
      {PORTS_RENDER[resolved.ports](ctx)}
      {typeNodes.bottom}
      {resolved.footer ? (footerContent ?? <Bar edge="top" size="md" />) : null}
    </Block>
  );
}

/**
 * Block (Simple View) box layout — the flex arrangement of `block.tsx`,
 * restated as pure geometry.
 *
 * WHY this exists: detach-to-primitives needs the position of every part of
 * a Block (header band, glyph, title, chip, description, type) as numbers,
 * and those positions must come from the same authority as the live
 * renderer — never from re-measured DOM and never from hand-typed offsets.
 * The live renderer's authority is `block.tsx`'s CSS (flex column, centered,
 * `gap-1`) plus the constants in `layout.ts`; this module is that CSS
 * written as arithmetic, importing the same constants. If `block.tsx`
 * changes a class, this file is the other place that class lives.
 *
 * Pure by the same rule as `layout.ts`: no React, no canvas engine, no DOM.
 * Text widths are the one thing only an environment can know, so they come
 * in through a `measure` function the caller supplies (a DOM measurer in a
 * browser, a deterministic approximation in tests).
 */

import {
  BLOCK_BORDER_PX,
  BLOCK_PADDING_X,
  CHIP,
  CHIP_RIGHT_IN_HEADER_PX,
  HEADER_CHIP_RESERVED_PX,
  META_FONT_PX,
  TEXT_SIZES,
  glyphPx,
  type TextSize,
} from "./layout";
// INTEGRATION (docs/T1-SPEC.md §0): `portLabelOut`/`PortTextLayout` moved
// to the rebuilt `port.layout.ts` with Lane P's Port rebuild. That rebuild
// briefly narrowed six text-layout members to four, dropping the "Offset"
// pair — the 2026-09-12 two-slot proposal put them back (they are two of
// the six positions in Zach's own label-slot diagram), and 2026-09-15
// gave them their real geometry: an Offset label is LIFTED clear of the
// dot's centre line, where a trace wire runs, rather than pushed further
// out along it. `portLabelBox` below therefore carries a distinct case per
// Offset member — same `out`, different `y` — see `SlotAlign`'s WHY.
import {
  PORT_LABEL_GAP,
  TEXT_LAYOUT_AS_PLACEMENT,
  portLabelOut,
  type PortTextLayout,
} from "./port.layout";

/** A rectangle in block-local coordinates (0,0 = container top-left). */
export interface LayoutBox {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** `leading-tight` on BlockTitle and PortLabel. */
export const LEADING_TIGHT = 1.25;
/** The inherited body line-height (Tailwind preflight) — description, type, chip text. */
export const LEADING_BASE = 1.5;
/** `gap-1` between the container's in-flow children (header, description). */
export const BLOCK_STACK_GAP = 4;
/** `gap-2` between glyph and title in a horizontal header. */
export const HEADER_ITEM_GAP = 8;
/** `gap-1` between glyph and title in a vertical header. */
export const HEADER_ITEM_GAP_VERTICAL = 4;
/** `px-3` inside the chip oval. */
export const CHIP_PADDING_X = 12;
/** `border-2` on the chip oval. */
export const CHIP_BORDER_PX = 2;
/** `bottom-3` — the type label's inset from the padding-box bottom. */
export const BLOCK_TYPE_BOTTOM = 12;

/** Measured width of `text` at `fontPx` with CSS weight `weight`. */
export type TextMeasure = (text: string, fontPx: number, weight: number) => number;

/**
 * `text` with CSS `white-space: normal` collapsing applied: runs of
 * document white space (space, tab, LF, CR, FF) become one space, and
 * leading/trailing runs vanish (the browser removes them at line edges).
 *
 * WHY not `\s` or `trim()`: JS `\s` (and `String.trim`) also match NBSP,
 * which CSS never collapses — an NBSP is glue between words, not a
 * separator, so it must survive normalisation untouched.
 *
 * WHY exported: this is the ONE normalisation shared by layout (the line
 * counting in `wrapTextLines`) and by emission (the detach builders that
 * turn a prop into a stock text primitive). A live `<p>` shows the
 * collapsed text — a raw `\n` handed to a rich-text builder becomes a
 * second paragraph the live DOM never painted — so anything standing in
 * for the live paint must run the same function, never its own copy.
 */
export function collapseWhitespace(text: string): string {
  return text.replace(/[\t\n\f\r ]+/g, " ").replace(/^ | $/g, "");
}

const SOFT_HYPHEN = "\u00ad";
const NBSP_RUN = /^\u00a0+$/;

/**
 * Characters the live renderer allows a break AFTER inside a space-free
 * run: hyphen-minus, the typographic hyphens/dashes, the horizontal
 * ellipsis (U+2026) and the question mark.
 *
 * WHY this exact set: it is MEASURED Chrome behaviour (headless Chrome,
 * `overflow-wrap: normal`, 2026-09), not UAX #14 read off the page \u2014 the
 * live `<p>` paints whatever the engine decides, so the wrap model copies
 * the engine. Chrome breaks after "\u2026" and "?" ("wait\u2026|super", "no?|break")
 * but deliberately NOT after "/", ".", ":", ";", ",", "!", ")", "#", "_",
 * "@", quotes or a "..." run of full stops \u2014 a URL, a dotted domain or a
 * snake_case identifier stays one unbreakable run, which is why long URLs
 * famously overflow their containers. Backward-gluing punctuation onto the
 * run before it must therefore also KEEP these break-after opportunities:
 * an earlier version glued "wait\u2026supercalifragilistic" into one atom and a
 * narrow detached description overflowed its card where the live one
 * wrapped.
 */
const BREAK_AFTER_CHAR = /[-\u2010\u2012\u2013\u2014\u2026?]$/;

/**
 * One character CSS treats as its own line-break unit (UAX #14 class ID
 * and Hangul): a break is allowed between any two of them, dictionary
 * words or not — which is why a CJK run wraps with no spaces at all.
 */
const CJK_BREAK_CHAR =
  /^[\p{sc=Han}\p{sc=Hiragana}\p{sc=Katakana}\p{sc=Hangul}]$/u;

/**
 * Scripts written without spaces whose line breaks come from dictionary
 * word boundaries (CSS/ICU "South East Asian" line breaking). Unlike CJK
 * there is no break between arbitrary characters — the segmenter's word
 * boundary IS the break opportunity, so a boundary touching one of these
 * characters keeps its break.
 */
const SEA_BREAK_CHAR = /^[\p{sc=Thai}\p{sc=Lao}\p{sc=Khmer}\p{sc=Myanmar}]$/u;

let wordSegmenter: Intl.Segmenter | null = null;

/** Availability is re-checked per call so tests can stub the segmenter away. */
function getWordSegmenter(): Intl.Segmenter | null {
  if (typeof Intl === "undefined" || typeof Intl.Segmenter !== "function") {
    return null;
  }
  if (!wordSegmenter) {
    wordSegmenter = new Intl.Segmenter(undefined, { granularity: "word" });
  }
  return wordSegmenter;
}

/** Per-character atoms for a CJK segment, the segment itself otherwise. */
function splitCjkCharacters(segment: string): string[] {
  const characters = [...segment];
  return characters.length > 1 && characters.every((c) => CJK_BREAK_CHAR.test(c))
    ? characters
    : [segment];
}

/**
 * Split one space-free, soft-hyphen-free piece into the atoms between
 * which CSS allows a line break.
 *
 * Segmenter path: `Intl.Segmenter` word boundaries are the candidate
 * opportunities, adjusted four ways to match line breaking rather than
 * word counting — a non-word-like segment (punctuation) glues backward so
 * "hello," never sheds its comma to the next line, an NBSP glues BOTH of
 * its neighbours (it exists to forbid the break), a CJK word is re-split
 * per character because CSS breaks between ideographs the dictionary
 * would keep together, and a word-like segment glues backward too unless
 * the run behind it actually ends at a real break opportunity (a
 * `BREAK_AFTER_CHAR` — hyphen, ellipsis, "?" — or a CJK character) or the
 * segment itself begins with one. That last rule is what keeps
 * "https://internal.example.com/pipelines" one atom: the segmenter sees
 * word boundaries at every "/" and ".", but Chrome under
 * `overflow-wrap: normal` breaks only after the `BREAK_AFTER_CHAR` set,
 * not after URL punctuation — which is exactly why long URLs overflow
 * their boxes in browsers.
 *
 * Fallback (no Segmenter — documented and tested): break around each CJK
 * character and after each `BREAK_AFTER_CHAR`, nowhere else. Spaces and
 * soft hyphens were already handled by the caller, and an NBSP simply
 * stays inside its run, so it can never break. Coarser than the segmenter
 * for long Latin words, identical for the space-separated and CJK text
 * this layout actually meets.
 */
function atomizePiece(piece: string): string[] {
  const segmenter = getWordSegmenter();
  if (!segmenter) {
    const atoms: string[] = [];
    let run = "";
    for (const character of piece) {
      if (CJK_BREAK_CHAR.test(character)) {
        if (run !== "") atoms.push(run);
        run = "";
        atoms.push(character);
      } else if (BREAK_AFTER_CHAR.test(character)) {
        // The break-after characters (hyphens, ellipsis, "?") end their
        // run and open a break opportunity, same as the segmenter path.
        atoms.push(run + character);
        run = "";
      } else {
        run += character;
      }
    }
    if (run !== "") atoms.push(run);
    return atoms;
  }
  const atoms: string[] = [];
  let glueNext = false;
  for (const part of segmenter.segment(piece)) {
    const isNbsp = NBSP_RUN.test(part.segment);
    const previous = atoms[atoms.length - 1];
    // A word boundary is only a LINE-break opportunity when the text on
    // either side of it says so: the run behind ends breakably (hyphen,
    // CJK, or a dictionary-broken SEA script) or the incoming segment
    // starts with a CJK/SEA character.
    const previousEnd = previous === undefined ? "" : ([...previous].at(-1) ?? "");
    const segmentStart = [...part.segment][0] ?? "";
    const boundaryBreaks =
      previous !== undefined &&
      (BREAK_AFTER_CHAR.test(previous) ||
        CJK_BREAK_CHAR.test(previousEnd) ||
        SEA_BREAK_CHAR.test(previousEnd) ||
        CJK_BREAK_CHAR.test(segmentStart) ||
        SEA_BREAK_CHAR.test(segmentStart));
    const glue = glueNext || isNbsp || !part.isWordLike || !boundaryBreaks;
    const units = splitCjkCharacters(part.segment);
    if (glue && atoms.length > 0) {
      atoms[atoms.length - 1] += units[0];
      atoms.push(...units.slice(1));
    } else {
      atoms.push(...units);
    }
    glueNext = isNbsp;
  }
  return atoms;
}

/** How a token may separate from the one before it on the same line. */
type WrapBreak = "space" | "opportunity" | "soft-hyphen";

interface WrapToken {
  text: string;
  breakBefore: WrapBreak;
}

/**
 * `text` broken into the lines CSS normal wrapping produces in a `maxW`
 * box: whitespace collapsed (via `collapseWhitespace`), greedy fill,
 * breaks at real line-break opportunities. Those are spaces (consumed at
 * the break), the boundaries `atomizePiece` finds — between CJK
 * characters, after hyphens/ellipses/question marks, at SEA dictionary
 * words — and soft hyphens, which are
 * invisible until used and render a "-" at the line end when the break is
 * taken. An NBSP never breaks. A single unbreakable run wider than the box
 * overflows on its own line rather than splitting, exactly as
 * `overflow-wrap: normal` behaves.
 *
 * WHY the opportunity model and not `split(/\s+/)`: the split saw a 40-
 * ideograph description as one unbreakable word and counted one 27px line
 * where the live `<p>` painted two or more — and every line miscounted
 * moves the whole centred stack. It also broke at NBSP (JS `\s` matches
 * it; CSS does not) and ignored soft hyphens entirely.
 */
export function wrapTextLines(
  text: string,
  maxW: number,
  fontPx: number,
  weight: number,
  measure: TextMeasure,
): string[] {
  const collapsed = collapseWhitespace(text);
  if (collapsed === "") return [];
  const tokens: WrapToken[] = [];
  for (const chunk of collapsed.split(" ")) {
    for (const [pieceIndex, piece] of chunk.split(SOFT_HYPHEN).entries()) {
      // The soft hyphens themselves are delimiters: invisible when the
      // line runs through them, so they never reach a token's text.
      const atoms = atomizePiece(piece);
      for (const [atomIndex, atom] of atoms.entries()) {
        tokens.push({
          text: atom,
          breakBefore:
            atomIndex > 0
              ? "opportunity"
              : pieceIndex > 0
                ? "soft-hyphen"
                : "space",
        });
      }
    }
  }
  if (tokens.length === 0) return [];
  const lines: string[] = [];
  let line = tokens[0].text;
  for (const token of tokens.slice(1)) {
    const joiner = token.breakBefore === "space" ? " " : "";
    const candidate = line + joiner + token.text;
    if (measure(candidate, fontPx, weight) <= maxW) {
      line = candidate;
    } else {
      lines.push(token.breakBefore === "soft-hyphen" ? `${line}-` : line);
      line = token.text;
    }
  }
  lines.push(line);
  return lines;
}

export interface SimpleBlockLayoutInput {
  width: number;
  height: number;
  title: string;
  titleSize: TextSize;
  /** Empty string means "no glyph", matching the adapters. */
  icon: string;
  /** Empty string means "no chip". */
  tag: string;
  description: string;
  blockType: string;
  orientation: "horizontal" | "vertical";
  measure: TextMeasure;
}

export interface SimpleBlockLayout {
  /** The header band (the flex row/column of glyph + title). */
  header: LayoutBox;
  glyph: LayoutBox | null;
  /** The title's line box; `w` is already clamped to the room the chip leaves. */
  title: LayoutBox | null;
  chip: LayoutBox | null;
  /** The chip's text line box, centered inside the oval. */
  chipText: LayoutBox | null;
  description: LayoutBox | null;
  /**
   * How many lines the description wraps onto inside `description.w` — the
   * live `<p>` has no nowrap/truncate, so a long description wraps and the
   * whole flex stack re-centres around the wrapped height. Callers emitting
   * a text primitive need the count to centre their own line grid inside
   * the box. 0 when there is no description.
   */
  descriptionLines: number;
  /**
   * The wrapped lines themselves, exactly as the live `<p>` paints them
   * (soft-hyphen breaks already rendered as "-"). Emitters that hand the
   * description to a renderer with a DIFFERENT wrapping model (tldraw's
   * rich text uses `overflow-wrap: break-word`, the live `<p>` uses
   * `normal`) must emit these lines verbatim rather than letting that
   * renderer re-wrap — re-wrapping split a long URL the live component
   * painted as one overflowing line. Empty when there is no description.
   */
  descriptionTextLines: string[];
  blockType: LayoutBox | null;
}

/**
 * The Simple View, laid out. Mirrors `block.tsx` rule for rule:
 * - container: flex column, centered both ways, `gap-1`, `border-2`, `px-4`
 * - header: flex row (or column when vertical), centered, `gap-2`
 * - chip: out of flow, right `CHIP_RIGHT_IN_HEADER_PX` in the header frame,
 *   reserving `HEADER_CHIP_RESERVED_PX` so the title's room ends before it
 * - blockType: absolute, `bottom-3`, centered on the padding box
 */
export function layoutSimpleBlock(input: SimpleBlockLayoutInput): SimpleBlockLayout {
  const { width, height, measure } = input;
  const contentX = BLOCK_BORDER_PX + BLOCK_PADDING_X;
  const contentW = width - 2 * contentX;
  const hasChip = input.tag !== "";
  const hasIcon = input.icon !== "";

  // Measure what the DOM renders: every text slot collapses white space
  // (`white-space: normal` and `nowrap` both do), so a raw `\n` or tab in a
  // prop is a single space on screen — never a measurement unit.
  const titleText = collapseWhitespace(input.title);
  const tagText = collapseWhitespace(input.tag);
  const blockTypeText = collapseWhitespace(input.blockType);

  const titleFontPx = TEXT_SIZES[input.titleSize];
  const titleLineH = titleText === "" ? 0 : Math.round(titleFontPx * LEADING_TIGHT);
  const glyphSize = hasIcon ? glyphPx(input.titleSize) : 0;

  // The room the header's in-flow content actually has (the chip reserves
  // its span as right padding — see BlockHeader).
  const headerAvailW = contentW - (hasChip ? HEADER_CHIP_RESERVED_PX : 0);

  const vertical = input.orientation === "vertical";
  const headerH = vertical
    ? glyphSize + (hasIcon && titleLineH > 0 ? HEADER_ITEM_GAP_VERTICAL : 0) + titleLineH
    : Math.max(glyphSize, titleLineH);

  // The live description is a plain wrapping <p>: a long description takes
  // several 27px lines and the flex stack re-centres around the wrapped
  // height, so the layout must count the lines, not assume one.
  const descLineH = Math.round(META_FONT_PX * LEADING_BASE);
  const descLines =
    input.description === ""
      ? []
      : wrapTextLines(input.description, contentW, META_FONT_PX, 400, measure);
  const descH = descLines.length * descLineH;

  // The container's vertical centering: in-flow children are the header and
  // the description; the type label is out of flow.
  const flowHeights = [headerH, descH].filter((h) => h > 0);
  const stackH =
    flowHeights.reduce((sum, h) => sum + h, 0) +
    BLOCK_STACK_GAP * Math.max(0, flowHeights.length - 1);
  const stackTop = (height - stackH) / 2;

  const header: LayoutBox = { x: contentX, y: stackTop, w: contentW, h: headerH };

  let glyph: LayoutBox | null = null;
  let title: LayoutBox | null = null;
  if (vertical) {
    if (hasIcon) {
      glyph = {
        x: contentX + (headerAvailW - glyphSize) / 2,
        y: header.y,
        w: glyphSize,
        h: glyphSize,
      };
    }
    if (titleLineH > 0) {
      const titleW = Math.min(measure(titleText, titleFontPx, 500), headerAvailW);
      title = {
        x: contentX + (headerAvailW - titleW) / 2,
        y: header.y + headerH - titleLineH,
        w: titleW,
        h: titleLineH,
      };
    }
  } else {
    // An empty title is still a flex item, so the glyph↔title gap applies
    // whenever the glyph exists — matching the DOM, not intuition.
    const gap = hasIcon ? HEADER_ITEM_GAP : 0;
    const titleMaxW = Math.max(0, headerAvailW - (hasIcon ? glyphSize + gap : 0));
    const titleW =
      titleLineH > 0 ? Math.min(measure(titleText, titleFontPx, 500), titleMaxW) : 0;
    const rowW = (hasIcon ? glyphSize + gap : 0) + titleW;
    const rowX = contentX + (headerAvailW - rowW) / 2;
    if (hasIcon) {
      glyph = {
        x: rowX,
        y: header.y + (headerH - glyphSize) / 2,
        w: glyphSize,
        h: glyphSize,
      };
    }
    if (titleLineH > 0) {
      title = {
        x: rowX + (hasIcon ? glyphSize + gap : 0),
        y: header.y + (headerH - titleLineH) / 2,
        w: titleW,
        h: titleLineH,
      };
    }
  }

  let chip: LayoutBox | null = null;
  let chipText: LayoutBox | null = null;
  if (hasChip) {
    const textW = measure(tagText, META_FONT_PX, 400);
    const chipW = Math.max(
      CHIP.minWidth,
      textW + 2 * CHIP_PADDING_X + 2 * CHIP_BORDER_PX,
    );
    chip = {
      x: contentX + contentW - CHIP_RIGHT_IN_HEADER_PX - chipW,
      y: header.y + headerH / 2 - CHIP.height / 2,
      w: chipW,
      h: CHIP.height,
    };
    const chipTextH = Math.round(META_FONT_PX * LEADING_BASE);
    chipText = {
      x: chip.x + (chipW - textW) / 2,
      y: chip.y + (CHIP.height - chipTextH) / 2,
      w: textW,
      h: chipTextH,
    };
  }

  let description: LayoutBox | null = null;
  if (descLines.length > 0) {
    // One line keeps its measured width (a shrink-to-fit flex item); a
    // wrapped description fills the content width — that width is what
    // decided the line breaks, so it is the box the lines centre in.
    const descW =
      descLines.length === 1
        ? Math.min(measure(descLines[0], META_FONT_PX, 400), contentW)
        : contentW;
    description = {
      x: contentX + (contentW - descW) / 2,
      y: stackTop + (headerH > 0 ? headerH + BLOCK_STACK_GAP : 0),
      w: descW,
      h: descH,
    };
  }

  let blockType: LayoutBox | null = null;
  if (input.blockType !== "") {
    const typeH = Math.round(META_FONT_PX * LEADING_BASE);
    const typeW = measure(blockTypeText, META_FONT_PX, 400);
    blockType = {
      // left-1/2 -translate-x-1/2 in the padding box lands on width/2 exactly
      // (the border insets cancel).
      x: width / 2 - typeW / 2,
      y: height - BLOCK_BORDER_PX - BLOCK_TYPE_BOTTOM - typeH,
      w: typeW,
      h: typeH,
    };
  }

  return {
    header,
    glyph,
    title,
    chip,
    chipText,
    description,
    descriptionLines: descLines.length,
    descriptionTextLines: descLines,
    blockType,
  };
}

/* ------------------------------------------------------------------ */
/* Port label box — the flex row of `port.tsx`, as arithmetic          */
/* ------------------------------------------------------------------ */

export interface PortLabelBoxInput {
  /** The dot's box: 0,0 = dot top-left, `w`/`h` its diameter. */
  dotW: number;
  dotH: number;
  label: string;
  layout: PortTextLayout;
  /** The label's font size in px (a `TextSize` rung resolved by the caller). */
  fontPx: number;
  measure: TextMeasure;
}

/**
 * Where the label's line box sits relative to the dot's box — the same
 * geometry `portLabelPlacement` produces in CSS, as a rectangle. The near
 * edge lands `PORT_LABEL_GAP` px clear of the dot; cross-axis
 * centered. The along-axis distance comes from the shared `portLabelOut`,
 * the one place that quantity is computed — see its WHY.
 */
export function portLabelBox(input: PortLabelBoxInput): LayoutBox {
  const { dotW, dotH, layout, fontPx } = input;
  const out = portLabelOut(layout, { w: dotW, h: dotH });
  const w = input.measure(input.label, fontPx, 400);
  const h = Math.round(fontPx * LEADING_TIGHT);
  // An "Offset" layout shares its plain counterpart's along-axis `out` and
  // differs ONLY in the cross axis. It reads its placement straight from
  // `TEXT_LAYOUT_AS_PLACEMENT` — the SAME table the CSS path uses — so the
  // measured rectangle and the painted box cannot drift, which they twice
  // did while each computed its own lift.
  //
  // `align: "end"` means the slot's BOTTOM edge sits on the reference
  // line, so in rectangle terms the box's bottom is `dotH / 2 + offsetY`
  // and its top is that minus `h`. No height-derived lift is involved any
  // more: the height enters once, here, as the box's own size.
  const preset = TEXT_LAYOUT_AS_PLACEMENT[layout];
  const alignedTop =
    preset.align === "end" ? dotH / 2 - h : preset.align === "start" ? dotH / 2 : dotH / 2 - h / 2;
  const liftedY = alignedTop + preset.offsetY;
  switch (layout) {
    case "right":
      return { x: out, y: dotH / 2 - h / 2, w, h };
    case "rightOffset":
      return { x: out, y: liftedY, w, h };
    case "left":
      return { x: dotW - out - w, y: dotH / 2 - h / 2, w, h };
    case "leftOffset":
      return { x: dotW - out - w, y: liftedY, w, h };
    case "top":
      return { x: dotW / 2 - w / 2, y: dotH - out - h, w, h };
    case "bot":
      return { x: dotW / 2 - w / 2, y: out, w, h };
  }
}

/**
 * Grammar-agnostic text-geometry helpers for the "click a rendered row and
 * land in source mode with the caret already there" gesture — the seam
 * `CodeField`'s `mode="rendered"` rows use to compute what `onOpenSource`
 * reports. Pure DOM; no grammar, no host.
 */

/** Absolute character offset of the start of `lineIndex` within `source`. */
export function lineStartOffset(source: string, lineIndex: number): number {
  const lines = source.replace(/\r\n?/g, "\n").split("\n");
  let offset = 0;
  for (let i = 0; i < lineIndex && i < lines.length; i++) offset += lines[i].length + 1;
  return offset;
}

/**
 * How far into `container`'s own text a click at (clientX, clientY) landed —
 * used to map a pixel click on a *rendered* row (built from separate name /
 * punctuation / type spans, not the raw source) back onto an approximate
 * column in that row's raw source line. Exact for the common case where the
 * row was authored with the same single-space `name: type = value` spacing
 * the read view renders; if punctuation was written differently, the mapped
 * column is a reasonable placement, not a guarantee.
 */
export function caretOffsetFromPoint(container: HTMLElement, clientX: number, clientY: number): number {
  const doc = document as Document & {
    caretPositionFromPoint?(x: number, y: number): { offsetNode: Node; offset: number } | null;
  };
  let node: Node | null = null;
  let nodeOffset = 0;
  if (typeof document.caretRangeFromPoint === "function") {
    const range = document.caretRangeFromPoint(clientX, clientY);
    if (range) {
      node = range.startContainer;
      nodeOffset = range.startOffset;
    }
  } else if (typeof doc.caretPositionFromPoint === "function") {
    const pos = doc.caretPositionFromPoint(clientX, clientY);
    if (pos) {
      node = pos.offsetNode;
      nodeOffset = pos.offset;
    }
  }
  if (!node || !container.contains(node)) return container.textContent?.length ?? 0;
  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
  let offset = 0;
  let current: Node | null;
  while ((current = walker.nextNode())) {
    // Chrome that shares the row but is not part of the source line — a
    // chevron glyph — is marked `data-caret-ignore`; counting it shifted
    // every mapped column one character right of the click.
    if (current.parentElement?.closest("[data-caret-ignore]")) {
      if (current === node) return offset;
      continue;
    }
    if (current === node) return offset + nodeOffset;
    offset += current.textContent?.length ?? 0;
  }
  return offset;
}

/*
 * The code text box. Sized to sit where a plain `<input>` sat — a port row,
 * an inspector field — so a board with nothing typed in code looks
 * unchanged. Colours are bbox-ui's own tokens (see theme.css), so the field
 * follows whatever theme the surrounding kit is painted with.
 */

.bbox-code-field {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  padding: 4px 6px;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  background: var(--color-card);
  color: var(--color-foreground);
  cursor: text;
  overflow: hidden;
  /* The field's own default type size — unchanged from before this rule
     existed (`.cm-scroller` used to hardcode the same 11px directly). Set
     HERE instead so a host that wants a bigger field (Port's `textSize`
     rung, port.tsx's `PortLabel`) can just set a bigger `font-size` on
     this element via its own `style` prop; `.cm-scroller` below now
     inherits rather than re-hardcoding it, which is the only way an
     ancestor override could ever reach CodeMirror's own internal DOM. */
  font-size: 11px;
}

.bbox-code-field[aria-disabled="true"] {
  opacity: 0.6;
  cursor: default;
}

.bbox-code-field:focus-within {
  border-color: var(--color-primary);
}

/*
 * CodeMirror parents its tooltips (the completion popup) onto whatever
 * `tooltipParent`/`[data-tooltip-host]` names — document.body by default,
 * NOT a descendant of `.bbox-code-field`, so this deliberately is not a
 * `.bbox-code-field .cm-tooltip` descendant selector (it would never
 * match). A host mounting the field inside its own stacked canvas content
 * (a tldraw `HTMLContainer` shape, a React Flow node) can paint a LATER
 * shape or node on top of an EARLIER one at any DOM depth; this is the
 * floor that beats it regardless of what the host's own shapes use — the
 * donor's own value, max signed 32-bit, "it needs to go to maximum z
 * level" (Zach's call, ported).
 *
 * WHY `.cm-tooltip.bbox-code-completion` + `!important`, not a bare
 * `.cm-tooltip` rule: CodeMirror's own base theme injects a same-stylesheet
 * rule shaped like `.ͼ1 .cm-tooltip { z-index: 500 }` — two class selectors,
 * specificity (0,2,0). A bare `.cm-tooltip` is (0,1,0) and loses outright,
 * source order never even gets consulted. Measured: computed z-index 500
 * in both host demos with round 1's rule in place, beaten by anything at
 * z ≥ 501 anywhere on the page (a tldraw `--layer-header-footer` panel at
 * 999, an ordinary body sibling at 600). `.bbox-code-completion` is a class
 * `codeGrammar.ts` adds to EVERY CodeField completion popup via
 * `autocompletion`'s `tooltipClass`, so pairing it with `.cm-tooltip`
 * reaches the same (0,2,0) specificity as CodeMirror's own rule — a tie
 * this stylesheet's load order is not guaranteed to win — so `!important`
 * (the donor's own choice: `.tl-container .cm-tooltip.TypeNameAutocomplete-cm
 * { z-index: 2147483647 !important }`) is what actually decides it.
 * A consumer with other unrelated CodeMirror instances on the page should
 * scope this rule tighter after install.
 */
.cm-tooltip.bbox-code-completion {
  z-index: 2147483647 !important;
}

.bbox-code-field .cm-editor {
  outline: none;
  background: transparent;
  height: auto;
}

.bbox-code-field .cm-scroller {
  overflow: hidden;
  /* D3 (Zach, 2026-09-17: "let it inherit, agreed"). Was a hard-pinned
     monospace stack, which meant a sketch board rendered hand-drawn port
     labels in a host that does not import this file and monospace ones in
     a host that does. The decision now lives in one token instead of in
     whether a stylesheet happened to be imported; the fallback is the exact
     stack this replaced, so a host with no skin loaded is unchanged. */
  /* Consolas added to match `textBox.layout.ts`'s stack exactly: the two
     had drifted, which nothing noticed until one skin token had to name a
     single fallback for both. A Windows host now gets the same face from
     a code field and a mono TextBox. */
  font-family: var(--bbox-skin-font-mono, ui-monospace, "SF Mono", Menlo, Consolas, monospace);
  /* Inherits from `.bbox-code-field` (11px there by default) instead of
     re-hardcoding its own copy — see that rule's own WHY. */
  font-size: inherit;
  line-height: 1.4;
}

.bbox-code-field .cm-content {
  padding: 0;
  caret-color: var(--color-primary);
  white-space: nowrap;
}

.bbox-code-field .cm-line {
  padding: 0;
}

.bbox-code-field .cm-placeholder {
  color: var(--color-muted-foreground);
  font-style: normal;
}

.bbox-code-field .cm-selectionBackground,
.bbox-code-field .cm-focused .cm-selectionBackground,
.bbox-code-field ::selection {
  background: color-mix(in srgb, var(--color-primary) 30%, transparent);
}

.bbox-code-field .cm-cursor {
  border-left-color: var(--color-primary);
}

/* Folded lane lines (`grammar.foldInactiveLinesAfter`): a quiet ellipsis,
   not a button — clicking it just moves the caret onto that line, which
   unfolds it. */
.bbox-code-field .bbox-code-field-ellipsis {
  color: var(--color-muted-foreground);
  cursor: text;
}

/* The wrapper a grammar-aware host puts around the field to carry its own
   diagnostics: a passive warning glyph and an accessible help line. Not
   part of CodeField itself — see the `signature` grammar's field wrapper
   for the pattern — but styled from the same sheet so the two ship together. */
.bbox-code-field-frame {
  position: relative;
  display: block;
  min-width: 0;
}

.bbox-code-field-frame[data-error="true"] .bbox-code-field {
  border-color: color-mix(in srgb, var(--bbox-danger) 60%, var(--color-border));
}

.bbox-code-field-frame__warning {
  position: absolute;
  top: 50%;
  right: 6px;
  transform: translateY(-50%);
  color: var(--bbox-warning);
  font-size: 11px;
  line-height: 1;
  pointer-events: none;
}

.bbox-code-field-frame__help {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* The `signature` grammar's three roles: the name carries the ink, the type
 * is an accent-tinted hint, the default is a muted value, and the two
 * glyphs between them are quieter than any of the three. These win over the
 * generic syntax token colours on purpose — a free-text name of three words
 * must not light up as three variable references. */
.bbox-code-field .bbox-sig-name,
.bbox-code-field .bbox-sig-name.tok-variableName {
  color: var(--color-foreground);
  font-weight: 600;
}

.bbox-code-field .bbox-sig-type,
.bbox-code-field .bbox-sig-type.tok-variableName {
  color: color-mix(in srgb, var(--color-primary) 55%, var(--color-foreground));
  font-weight: 400;
}

.bbox-code-field .bbox-sig-punct {
  color: var(--color-muted-foreground);
}

.bbox-code-field .bbox-sig-default {
  color: var(--color-foreground);
}

/*
 * RENDERED mode (`CodeField`'s `mode="rendered"`, `CodeFieldRows`): the same
 * three roles as source mode's marks, painted as React children instead of
 * CodeMirror decorations. `.bbox-code-seg--*` mirrors `.bbox-sig-*` above —
 * a grammar that reuses the `signature` role names gets one palette for
 * both modes for free.
 */
.bbox-code-field-rows {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  line-height: 1.6;
  color: var(--color-foreground);
  cursor: text;
}

.bbox-code-field-row {
  display: flex;
  flex-direction: column;
}

.bbox-code-field-row-content {
  display: flex;
  align-items: baseline;
  white-space: pre;
}

.bbox-code-field-chevron {
  display: inline-flex;
  width: 12px;
  flex-shrink: 0;
  color: var(--color-muted-foreground);
  font-size: 9px;
  cursor: default;
}

.bbox-code-field-chevron[role="button"] {
  cursor: pointer;
}

.bbox-code-field-preview {
  margin-left: 12px;
  padding-left: 8px;
  border-left: 1px solid var(--color-border);
}

.bbox-code-seg--name {
  color: var(--color-foreground);
  font-weight: 600;
}

.bbox-code-seg--type {
  color: color-mix(in srgb, var(--color-primary) 55%, var(--color-foreground));
}

.bbox-code-seg--default {
  color: var(--color-foreground);
}

.bbox-code-seg--punct {
  color: var(--color-muted-foreground);
}

/* A reference segment: underlined and clickable only once it resolves —
 * `resolveReference` returning `null` (an unknown name) leaves it looking
 * like ordinary accent text, matching source mode's plain `tok-variableName`
 * treatment for the same case. */
.bbox-code-ref[role="button"] {
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
}

.bbox-code-ref--unknown {
  color: var(--bbox-danger);
}

/* `CodeFieldModeToggle` — a small [Rendered | Source] switch. */
.bbox-code-field-toggle {
  display: inline-flex;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  overflow: hidden;
}

.bbox-code-field-toggle button {
  padding: 2px 8px;
  border: none;
  background: transparent;
  color: var(--color-muted-foreground);
  font-size: 11px;
  cursor: pointer;
}

.bbox-code-field-toggle button[data-active] {
  background: var(--color-muted);
  color: var(--color-foreground);
}

/* The completion tooltip's kind pill (`CodeFieldGrammar.completionBadge`). */
.bbox-code-completion-pill {
  margin-left: 6px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--color-muted);
  color: var(--color-muted-foreground);
  font-size: 10px;
  line-height: 1.6;
}

"use client";

import { acceptCompletion, completionStatus } from "@codemirror/autocomplete";
import {
  copyLineDown,
  copyLineUp,
  defaultKeymap,
  history,
  historyKeymap,
  moveLineDown,
  moveLineUp,
} from "@codemirror/commands";
import { syntaxHighlighting } from "@codemirror/language";
import {
  Compartment,
  EditorState,
  Prec,
  type Extension,
} from "@codemirror/state";
import {
  EditorView,
  keymap,
  placeholder as placeholderExtension,
  tooltips,
} from "@codemirror/view";
import { classHighlighter } from "@lezer/highlight";
import {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";

import { externalSync, singleLineGuard } from "./codeFieldGuards";
import { grammarExtensions, type CodeFieldGrammar } from "./codeGrammar";
import { CodeFieldRows, pruneExpandedPaths, rowIdentity } from "./codeFieldRows";
import { FieldGesture } from "./fieldGesture";

export interface CodeFieldProps {
  /** The value. The field follows it whenever nobody is editing. */
  value: string;
  /** Write, per keystroke — the field's one write policy (see `fieldGesture.ts` for why `live` is the only mode offered here). */
  onWrite(value: string): void;
  /** Open one undo step so an edit is one Ctrl+Z, not one per character. */
  beginEdit?(): void;
  /** The commit boundary — one call per gesture, however the field was left. */
  onEditEnd?(value: string, startValue: string): void;
  /**
   * What makes this field know its grammar: slot decorations, a completion
   * source, a language. Omit it and you get the plain code text box.
   */
  grammar?: CodeFieldGrammar;
  disabled?: boolean;
  placeholder?: string;
  ariaLabel?: string;
  ariaDescribedBy?: string;
  ariaInvalid?: boolean;
  className?: string;
  testId?: string;
  style?: CSSProperties;
  /** Take focus on mount; `'select'` also selects the whole line. */
  autoFocus?: boolean | "select";
  /** With `autoFocus`, put the caret here instead of selecting everything. */
  cursorAt?: number;
  /** With `autoFocus`, select exactly this range — the slot that was clicked, not the whole line. */
  selectRange?: { from: number; to: number };
  /**
   * A lane: several lines, one per thing. Enter inserts a line, Alt+↑/↓
   * move one, Shift+Alt+↓ copies one (all CodeMirror's default keymap);
   * Ctrl/Cmd+Enter is the exit that Enter is for a single line.
   */
  multiline?: boolean;
  /** Pin every line to this height so lines can sit on a host's own rows. */
  lineHeightPx?: number;
  align?: "left" | "right";
  /** Soft-wrap long lines (a viewer), instead of letting them run. */
  wrap?: boolean;
  /** Extra chrome rendered inside the field's frame, positioned by the host's CSS. */
  trailing?: ReactNode;
  /**
   * Enter and Escape both end the gesture by leaving the field (the value is
   * never discarded — Ctrl+Z is the retract). A host that owns its own
   * editing session supplies its own exits instead of the default `leave`.
   */
  onEnter?(): void;
  onEscape?(): void;
  onViewReady?(view: EditorView): void;
  /**
   * Controlled two-way toggle between the pretty RENDERED tree
   * (`grammar.lines`) and the live SOURCE document (CodeMirror) — the "code
   * block overlay" idea: rendered by default, source under the caret. Omit
   * entirely for a field that is always source (the original, and still
   * the right choice for a plain port row with nothing worth a read view).
   * The host owns the state; `CodeField` never flips it on its own.
   */
  mode?: "rendered" | "source";
  /** Used by the optional `CodeFieldModeToggle` sub-component; `CodeField` itself never calls this. */
  onModeChange?(mode: "rendered" | "source"): void;
  /**
   * A rendered row (or the blank space below the last one) was clicked.
   * Only meaningful with `mode` set. `owner` is `undefined` for a row from
   * this field's own `value` — the host typically responds by setting
   * `mode="source"` and computing `cursorAt` from `line`/`column` (see
   * `caretGeometry.ts`'s `lineStartOffset`) against `value` itself. `owner`
   * is set for a row that came from a reference's `expandLines()` (see
   * `CodeFieldReference.owner`) — `line`/`column` are into THAT source, not
   * this field's `value`, and the host must resolve `owner` to open it.
   */
  onOpenSource?(line: number, column: number, owner?: unknown): void;
  /**
   * Where the completion popup (and any other CodeMirror tooltip) is
   * parented. Takes priority over an ancestor `[data-tooltip-host]`; both
   * are host opt-ins, so the core stays free of any specific canvas
   * engine's name. A function is called once per mount. Defaults to the
   * nearest `[data-tooltip-host]` ancestor, else `document.body`.
   */
  tooltipParent?: HTMLElement | (() => HTMLElement | null);
}

/**
 * The code text box: one line (or a multi-line lane) of text that knows
 * what it is.
 *
 * It is a real CodeMirror document, so highlighting, the completion
 * tooltip, IME, undo and the caret all come from one mature engine rather
 * than a mirror-div. What the field does NOT know is any grammar — that
 * arrives through `grammar`, so a port line, a type alias and a plain label
 * are the same component with different grammars plugged in. Commit
 * semantics are `FieldGesture`'s, unchanged: a field never stops existing
 * with an uncommitted edit.
 *
 * With `mode` set, this is a thin dispatcher: `"rendered"` mounts
 * `CodeFieldRows` over `grammar.lines(value)` and CodeMirror never mounts at
 * all; `"source"` (or `mode` omitted) mounts the live document below. The
 * two never coexist — leaving rendered mode unmounts the row tree exactly
 * as `CodeFieldSourceView` unmounts when rendered mode takes over — so a
 * grammar with no `lines()` still works fine as an always-source field.
 *
 * WHY expansion state lives HERE and not inside `CodeFieldRows`: `CodeField`
 * itself is the one component instance that survives the `mode` toggle (only
 * its RETURNED subtree switches between the row tree and the live document);
 * `CodeFieldRows` fully unmounts every trip through Source. State that lived
 * only there reset to all-collapsed on every round trip even when nothing
 * was edited — the donor (`TypeBabbleV1.tsx`) lifts the same state for the
 * same reason, above its own UI/Source split.
 */
export interface CodeFieldHandle {
  /**
   * Move the caret to `offset` and focus the live document — the seam an
   * ALREADY-MOUNTED-in-Source field needs. `cursorAt` only places the
   * caret once, in the mount effect (`autoFocus`'s own next-frame retry);
   * a host whose owner field is already open in Source when a foreign row
   * is clicked has no prop change to hand it, since `cursorAt` changing
   * while mounted does nothing — the donor's `useSourceToggleEditor`
   * solves the identical problem with `enterSourceAt`'s "already open …
   * place the caret on the live view directly" branch. A no-op while
   * `mode === "rendered"` (no live document to place a caret in).
   */
  setCaret(offset: number): void;
  focus(): void;
}

export const CodeField = forwardRef<CodeFieldHandle, CodeFieldProps>(function CodeField(props, ref) {
  const { mode, grammar, value, onOpenSource, ariaLabel, className, testId } = props;
  const [expandedPaths, setExpandedPaths] = useState<ReadonlySet<string>>(() => new Set());
  const toggleExpanded = (path: string) =>
    setExpandedPaths((current) => {
      const next = new Set(current);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });
  const lines = grammar?.lines?.(value) ?? [];
  // Prune expansion keys an edit has deleted outright — see
  // `pruneExpandedPaths`'s own doc for what this does and does not fix.
  useEffect(() => {
    setExpandedPaths((current) => pruneExpandedPaths(current, lines));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lines.map(rowIdentity).join(",")]);
  const sourceRef = useRef<CodeFieldHandle | null>(null);
  useImperativeHandle(ref, () => ({
    setCaret: (offset) => sourceRef.current?.setCaret(offset),
    focus: () => sourceRef.current?.focus(),
  }), []);
  if (mode === "rendered") {
    return (
      <CodeFieldRows
        lines={lines}
        resolveReference={grammar?.resolveReference}
        onOpenSource={onOpenSource}
        expandedPaths={expandedPaths}
        onToggleExpanded={toggleExpanded}
        className={className}
        testId={testId}
      />
    );
  }
  return <CodeFieldSourceView {...props} ariaLabel={ariaLabel} ref={sourceRef} />;
});

/** Two-button `[Rendered | Source]` switch — the chrome `CodeField`'s `mode` toggle needs, matching how it looks on the field this was extracted from. Entirely optional: a host may drive `mode` from its own UI instead. */
export function CodeFieldModeToggle({
  mode,
  onModeChange,
  labels = { rendered: "UI", source: "Source" },
}: {
  mode: "rendered" | "source";
  onModeChange(mode: "rendered" | "source"): void;
  labels?: { rendered: string; source: string };
}) {
  return (
    <div className="bbox-code-field-toggle" data-slot="code-field-mode-toggle">
      <button type="button" data-active={mode === "rendered" || undefined} onClick={() => onModeChange("rendered")}>
        {labels.rendered}
      </button>
      <button type="button" data-active={mode === "source" || undefined} onClick={() => onModeChange("source")}>
        {labels.source}
      </button>
    </div>
  );
}

const CodeFieldSourceView = forwardRef<CodeFieldHandle, CodeFieldProps>(function CodeFieldSourceView({
  value,
  onWrite,
  beginEdit,
  onEditEnd,
  grammar,
  disabled = false,
  placeholder,
  ariaLabel,
  ariaDescribedBy,
  ariaInvalid,
  className,
  testId,
  style,
  autoFocus = false,
  cursorAt,
  selectRange,
  multiline = false,
  lineHeightPx,
  align = "left",
  wrap = false,
  trailing,
  onEnter,
  onEscape,
  onViewReady,
  tooltipParent,
}, ref) {
  const hostRef = useRef<HTMLDivElement>(null);
  const viewRef = useRef<EditorView | null>(null);
  const grammarCompartment = useRef(new Compartment());
  const editableCompartment = useRef(new Compartment());
  const placeholderCompartment = useRef(new Compartment());
  const metricsCompartment = useRef(new Compartment());

  const latest = useRef({
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    value,
    disabled,
    multiline,
  });
  latest.current = {
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    value,
    disabled,
    multiline,
  };

  const metrics = (): Extension => [
    EditorView.theme({
      ...(lineHeightPx
        ? { ".cm-line": { lineHeight: `${lineHeightPx}px`, height: `${lineHeightPx}px` } }
        : {}),
      ...(align === "right" ? { ".cm-content": { textAlign: "right" } } : {}),
    }),
    ...(wrap ? [EditorView.lineWrapping] : []),
  ];

  const gestureRef = useRef<FieldGesture | null>(null);
  if (!gestureRef.current) {
    gestureRef.current = new FieldGesture(
      {
        write: (next) => latest.current.onWrite(next),
        begin: () => latest.current.beginEdit?.(),
        end: (next, start) => latest.current.onEditEnd?.(next, start),
      },
      "live",
    );
  }
  const gesture = gestureRef.current;

  const leave = (view: EditorView) => {
    view.contentDOM.blur();
    gesture.commit();
  };

  useImperativeHandle(ref, () => ({
    setCaret: (offset) => {
      const view = viewRef.current;
      if (!view) return;
      const anchor = Math.max(0, Math.min(offset, view.state.doc.length));
      // WHY the scrollIntoView effect, not just a selection dispatch: on a
      // multi-line lane taller than its scroll host, an owner-jump can
      // land the caret well below the visible viewport (measured: y 557
      // in a 40px-tall host) with nothing on screen to show it happened.
      view.dispatch({ selection: { anchor }, effects: EditorView.scrollIntoView(anchor) });
      view.focus();
    },
    focus: () => viewRef.current?.focus(),
  }), []);

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const view = new EditorView({
      state: EditorState.create({
        doc: value,
        extensions: [
          history(),
          // Enter and Escape are the field's exits, handled on the raw event
          // so the keystroke can be STOPPED: once the field closes, the same
          // keydown would otherwise reach a host's own document listener
          // with nothing focused — a canvas host that re-enters editing on
          // Enter, or clears a selection on Escape, would immediately undo
          // the exit. A completion popup gets first refusal on a BARE
          // Enter/Escape — its own keymap (Prec.highest inside
          // `autocompletion()`) accepts or closes it. The MODIFIER form
          // (Ctrl/Cmd+Enter) is our own dedicated exit and must never fall
          // through to it: `defaultKeymap`'s Mod-Enter is `insertBlankLine`,
          // which used to run whenever a popup happened to be open, leaving
          // a newline in even a single-line field. Accept-or-close the
          // popup ourselves first, then exit.
          Prec.high(
            EditorView.domEventHandlers({
              keydown: (event, target) => {
                if (event.isComposing) return false;
                if (event.key !== "Enter" && event.key !== "Escape") return false;
                const completionActive = completionStatus(target.state) === "active";
                const modifierEnter = event.key === "Enter" && (event.ctrlKey || event.metaKey);
                if (completionActive && !modifierEnter) {
                  // A bare Enter accepts the popup, Escape closes it —
                  // CodeMirror's own completion keymap runs independently of
                  // native DOM bubbling, so returning `false` here still lets
                  // it fire. But native bubbling itself must still be cut:
                  // a host's OWN document-level keydown listener (tldraw
                  // cancels the whole editing session on Escape, with no
                  // shortcuts gate) would otherwise see the same event and
                  // react to it too, on top of the popup closing.
                  event.stopPropagation();
                  return false;
                }
                // In a lane a bare Enter is a new line; only the modifier form exits.
                if (event.key === "Enter" && latest.current.multiline && !modifierEnter) {
                  return false;
                }
                if (completionActive && modifierEnter) acceptCompletion(target);
                event.preventDefault();
                event.stopPropagation();
                const exit = event.key === "Enter" ? latest.current.onEnter : latest.current.onEscape;
                if (exit) exit();
                else leave(target);
                return true;
              },
            }),
          ),
          // The transaction-level backstop for the single-line contract
          // above: whatever inserts a newline — typed/pasted text (caught
          // below by the input handler too), or a COMMAND like
          // `insertBlankLine` reached via the fallback this same keydown
          // handler used to allow — never survives in a non-multiline field.
          singleLineGuard(() => latest.current.multiline),
          // A lane is a small IDE buffer, so the line keys people reach for
          // all work: CodeMirror's own Alt+↑/↓ and Shift+Alt+↑/↓, plus the
          // Ctrl forms for anyone whose window manager eats Alt+arrows.
          keymap.of([
            { key: "Ctrl-ArrowUp", run: moveLineUp },
            { key: "Ctrl-ArrowDown", run: moveLineDown },
            { key: "Ctrl-Shift-ArrowUp", run: copyLineUp },
            { key: "Ctrl-Shift-ArrowDown", run: copyLineDown },
            ...defaultKeymap,
            ...historyKeymap,
          ]),
          syntaxHighlighting(classHighlighter),
          grammarCompartment.current.of(grammar ? grammarExtensions(grammar) : []),
          editableCompartment.current.of(EditorView.editable.of(!disabled)),
          placeholderCompartment.current.of(placeholder ? placeholderExtension(placeholder) : []),
          metricsCompartment.current.of(metrics()),
          // The completion popup is parented to an explicit `tooltipParent`
          // if the caller gave one, else the nearest declared tooltip host
          // (`[data-tooltip-host]` — a modal, a canvas layer, anything that
          // must keep the popup inside its own stacking context), else the
          // document body. WHY the ancestor lookup exists at all, beside the
          // prop: a host mounting many fields (every row of a canvas) can
          // opt every one of them in at once by tagging a single container,
          // rather than threading `tooltipParent` through each — the field
          // stays host-agnostic either way, since neither path names a
          // specific canvas engine.
          tooltips({
            position: "absolute",
            parent:
              (typeof tooltipParent === "function" ? tooltipParent() : tooltipParent) ??
              host.closest<HTMLElement>("[data-tooltip-host]") ??
              document.body,
          }),
          // One line: a typed or pasted newline is dropped rather than
          // growing the field. A lane keeps its newlines — they are its rows.
          EditorView.inputHandler.of((target, from, to, insertedText) => {
            if (latest.current.multiline || !/[\r\n]/.test(insertedText)) return false;
            const cleaned = insertedText.replace(/[\r\n]+/g, "");
            target.dispatch({
              changes: { from, to, insert: cleaned },
              selection: { anchor: from + cleaned.length },
            });
            return true;
          }),
          EditorView.updateListener.of((update) => {
            if (!update.docChanged) return;
            if (update.transactions.every((tr) => tr.annotation(externalSync))) return;
            const text = update.state.doc.toString();
            gesture.focus(latest.current.value);
            gesture.change(text);
          }),
          EditorView.domEventHandlers({
            focus: () => {
              if (latest.current.disabled) return;
              gesture.focus(latest.current.value);
            },
            // A CodeMirror `contentDOM` can flicker focus during its own
            // mount work; a synchronous commit on the first flicker would
            // end the gesture the instant it began. Believed only once it
            // survives a macrotask.
            blur: () => {
              globalThis.setTimeout(() => {
                const current = viewRef.current;
                if (current && !current.hasFocus) gesture.commit();
              }, 0);
            },
          }),
        ],
      }),
      parent: host,
    });
    viewRef.current = view;
    onViewReady?.(view);
    // Focus now and again on the next frame: a host that is mid-transition
    // (a canvas entering its own editing state) can take focus back after
    // the first attempt, and a field that opened without focus is a dead
    // field.
    let frame = 0;
    if (autoFocus) {
      const take = () => {
        if (view.hasFocus || !viewRef.current) return;
        view.focus();
        const length = view.state.doc.length;
        if (selectRange) {
          const anchor = Math.max(0, Math.min(selectRange.from, length));
          const head = Math.max(anchor, Math.min(selectRange.to, length));
          view.dispatch({ selection: { anchor, head } });
        } else if (cursorAt !== undefined) {
          const anchor = Math.max(0, Math.min(cursorAt, length));
          view.dispatch({ selection: { anchor } });
        } else if (autoFocus === "select") {
          view.dispatch({ selection: { anchor: 0, head: view.state.doc.length } });
        }
      };
      take();
      frame = requestAnimationFrame(take);
    }
    return () => {
      cancelAnimationFrame(frame);
      viewRef.current = null;
      view.destroy();
    };
    // One mount for the field's lifetime; content, grammar and editability
    // flow through compartments and dispatches so a re-render never tears
    // the document down mid-gesture.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // The document follows the store whenever nobody is typing in it. Every
  // keystroke round-trips back through `value` (the field's one write
  // policy is `live`), so the equality guard is what keeps this from
  // re-fighting the caret.
  useEffect(() => {
    const view = viewRef.current;
    if (!view || view.state.doc.toString() === value) return;
    if (gesture.isEditing && view.hasFocus) return;
    view.dispatch({
      changes: { from: 0, to: view.state.doc.length, insert: value },
      annotations: externalSync.of(true),
    });
  }, [value, gesture]);

  useEffect(() => {
    viewRef.current?.dispatch({
      effects: grammarCompartment.current.reconfigure(grammar ? grammarExtensions(grammar) : []),
    });
  }, [grammar]);

  useEffect(() => {
    viewRef.current?.dispatch({
      effects: editableCompartment.current.reconfigure(EditorView.editable.of(!disabled)),
    });
  }, [disabled]);

  useEffect(() => {
    viewRef.current?.dispatch({ effects: metricsCompartment.current.reconfigure(metrics()) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lineHeightPx, align, wrap]);

  useEffect(() => {
    viewRef.current?.dispatch({
      effects: placeholderCompartment.current.reconfigure(
        placeholder ? placeholderExtension(placeholder) : [],
      ),
    });
  }, [placeholder]);

  // A canvas host typically calls `preventDefault()` on its own pointerdown,
  // so clicking the canvas never fires this field's native blur. A
  // capture-phase listener on `document` is the one place "clicked outside
  // the field" is observable regardless of what swallowed the native event.
  useEffect(() => {
    const handlePointerDown = (event: PointerEvent) => {
      const host = hostRef.current;
      const view = viewRef.current;
      if (!host || !view || !view.hasFocus) return;
      if (event.target instanceof Node && host.contains(event.target)) return;
      const element =
        event.target instanceof Element ? event.target : (event.target as Node | null)?.parentElement;
      if (element?.closest(".cm-tooltip")) return;
      leave(view);
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    return () => document.removeEventListener("pointerdown", handlePointerDown, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // A canvas host typically wires wheel on an ancestor for its own pan/zoom
  // (tldraw on its container, React Flow on its pane), which fires from a
  // wheel over ANY of its children including this one — scrolling inside a
  // focused field would otherwise zoom or pan the whole canvas underneath
  // it. `{ passive: false }` + a real listener (not React's synthetic wheel,
  // which React attaches passively by default and cannot stop natively)
  // is what actually keeps the native event from bubbling past us.
  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const handleWheel = (event: WheelEvent) => {
      if (viewRef.current?.hasFocus) event.stopPropagation();
    };
    host.addEventListener("wheel", handleWheel, { passive: false });
    return () => host.removeEventListener("wheel", handleWheel);
  }, []);

  // Unmount is an end boundary like any other — the one the browser refuses
  // to report, since no blur fires for a focused element removed from the DOM.
  useEffect(() => () => gesture.commit(), [gesture]);

  return (
    <div
      data-slot="code-field"
      className={`bbox-code-field bbox-code-tokens${className ? ` ${className}` : ""}`}
      ref={hostRef}
      role="textbox"
      aria-label={ariaLabel}
      aria-describedby={ariaDescribedBy}
      aria-invalid={ariaInvalid ? true : undefined}
      aria-disabled={disabled ? true : undefined}
      data-testid={testId}
      style={style}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => event.stopPropagation()}
    >
      {trailing}
    </div>
  );
});

import {
  Annotation,
  EditorState,
  Transaction,
  type AnnotationType,
  type Extension,
} from "@codemirror/state";

/**
 * Marks `CodeField`'s own imperative doc swaps (the `value`-prop sync) so
 * the change listener never echoes them back as typing. Lives here, not in
 * `codeField.tsx`, so `singleLineGuard` below can recognise and re-apply it
 * on a transaction it has to rebuild — annotations are not part of
 * CodeMirror's public `Transaction` surface (only `.annotation(type)` for a
 * type you already know to ask for, never an enumerable list), so the only
 * ones a filter can honestly preserve are ones it knows about by name.
 */
export const externalSync = Annotation.define<boolean>();

/**
 * The named annotations this guard knows how to detect and re-apply on a
 * transaction it has to rebuild: CodeMirror's own `Transaction.time` /
 * `userEvent` / `addToHistory` / `remote`, plus `externalSync` above.
 *
 * WHY this matters beyond bookkeeping: `userEvent` and `addToHistory` are
 * what `history()` groups undo steps by. Losing them made a rebuilt
 * transaction look like an ORDINARY edit with no origin and no history
 * opinion — inside CodeMirror's 500ms `newGroupDelay`, that merged
 * silently into whatever adjacent edit was already open. Type `P`, then
 * paste `a\nb` (copying a lane line with an empty selection is linewise
 * and carries a trailing `\n`, so this is common here): one Ctrl+Z used to
 * discard the typing AND the paste together, leaving `t: ` instead of
 * undoing the paste alone. `time` matters too — it feeds the SAME grouping
 * window, so a rebuilt transaction stamped with a fresh `Date.now()`
 * instead of the original's timestamp can drift outside the window the
 * original edit was actually inside.
 */
function knownAnnotations(tr: Transaction): Annotation<unknown>[] {
  const carried: Annotation<unknown>[] = [];
  function add<T>(type: AnnotationType<T>): void {
    const value = tr.annotation(type);
    if (value !== undefined) carried.push(type.of(value));
  }
  add(Transaction.time);
  add(Transaction.userEvent);
  add(Transaction.addToHistory);
  add(Transaction.remote);
  add(externalSync);
  return carried;
}

/** How many `\r`/`\n` characters sit in `text` before `pos` — the amount a position must shift left to land on the equivalent spot once those characters are removed. */
function newlinesBefore(text: string, pos: number): number {
  let count = 0;
  for (let i = 0; i < pos; i++) {
    const code = text.charCodeAt(i);
    if (code === 10 || code === 13) count++;
  }
  return count;
}

/**
 * A single-line `CodeField` must never contain a newline, by ANY path —
 * not just typed or pasted text (`EditorView.inputHandler` catches that
 * one, and stays for the tighter cursor placement it can do on a normal
 * keystroke) but also a COMMAND that inserts one directly, like
 * `defaultKeymap`'s `insertBlankLine` (reachable on Ctrl/Cmd+Enter when a
 * completion popup happens to be open and swallows the field's own exit
 * binding first). A `transactionFilter` sees every transaction regardless
 * of what produced it, so this is the actual guarantee, not a best effort
 * at the input layer.
 *
 * Things earlier passes at this got wrong, all fixed here:
 *
 * - The caret was clamped to the CLEANED text's length instead of shifted
 *   by how many stripped characters sat ahead of it.
 * - The replacement spec silently dropped every annotation and effect —
 *   `externalSync` (an external value-sync misread as typing) and, worse,
 *   CodeMirror's OWN `userEvent`/`addToHistory`/`time` (undo-grouping
 *   corruption — see `knownAnnotations`'s doc). `effects` are forwarded
 *   unconditionally (a plain array on `Transaction`, unlike annotations,
 *   which have no generic enumerable list); `scrollIntoView` likewise.
 * - A transaction that, once cleaned, changes the DOCUMENT not at all
 *   (pasting a bare `"\n"`, or pasting text that survives cleaning back to
 *   exactly what a replaced selection already said) either dispatched a
 *   pointless full document-replace (a dead undo step) or, at the other
 *   extreme, dropped the transaction so completely that a REPLACED
 *   SELECTION was left standing open instead of collapsed to where the
 *   paste actually ended — the very next keystroke would have overwritten
 *   the pasted text a second time. Both are handled by always computing
 *   the corrected selection and only including `changes` when the doc
 *   actually differs.
 */
export function singleLineGuard(isMultiline: () => boolean): Extension {
  return EditorState.transactionFilter.of((tr) => {
    if (isMultiline() || !tr.docChanged) return tr;
    const text = tr.newDoc.toString();
    if (!/[\r\n]/.test(text)) return tr;
    const cleaned = text.replace(/[\r\n]+/g, "");
    const { anchor, head } = tr.newSelection.main;
    const shift = (pos: number) => Math.max(0, Math.min(pos - newlinesBefore(text, pos), cleaned.length));
    const selection = { anchor: shift(anchor), head: shift(head) };
    const preserved = {
      effects: tr.effects,
      annotations: knownAnnotations(tr),
      scrollIntoView: tr.scrollIntoView,
    };
    if (cleaned === tr.startState.doc.toString()) {
      // Nothing textual changes, but the selection still has to land where
      // a real edit would have — a paste that replaced a selection with
      // (once cleaned) the same text it already held must still collapse
      // the selection to the end of the paste, not leave the old range
      // standing open for the next keystroke to clobber.
      return { selection, ...preserved };
    }
    return {
      changes: { from: 0, to: tr.startState.doc.length, insert: cleaned },
      selection,
      ...preserved,
    };
  });
}

"use client";

import { useState, type MouseEvent as ReactMouseEvent } from "react";

import { caretOffsetFromPoint } from "./caretGeometry";
import type { CodeFieldLine, CodeFieldReference } from "./codeGrammar";

/** Sum of a row's own segment text — its rendered line, stitched back together. */
function rowText(line: CodeFieldLine): string {
  return line.segments.map((segment) => segment.text).join("");
}

/**
 * A row's identity for expansion/React-key purposes: its line index PLUS
 * its own name segment, `${line}:${name}` — the donor's own scheme
 * (`typeAttributes.ts`'s `id: \`${line}:${match[1]}\``). WHY not the line
 * index alone (round 2's finding): inserting a line above shifts every
 * later index down by one, so a path keyed on the index alone silently
 * reassigns "expanded" to whatever row now happens to sit at that number
 * — expand only `target`, insert a line above it, and `origin` (now at
 * `target`'s old index) opens while `target` (now one index further down)
 * closes. Keying on the pair means an index shift changes the key, so the
 * row that moved simply drops out of `expandedPaths` (closes) instead of
 * a DIFFERENT row silently inheriting its open state — closing on an
 * unrelated edit is an acceptable rough edge; reassigning to the wrong
 * row is not. Falls back to the row's full text when no segment is
 * marked `role: "name"` (a grammar with no name concept at all).
 */
export function rowIdentity(line: CodeFieldLine): string {
  const name = line.segments.find((segment) => segment.role === "name")?.text ?? rowText(line);
  return `${line.line}:${name}`;
}

/**
 * Drops any `expandedPaths` entry whose TOP-LEVEL `line:name` no longer
 * appears among the current top-level `lines` — an edit that deletes an
 * expanded row (not just shifts it, `rowIdentity`'s own job) would
 * otherwise leave that key sitting there forever. `CodeField` calls this
 * on every `lines()` recompute.
 *
 * WHY this is a narrowing, not a full fix: a stale key can still
 * coincidentally match a DIFFERENT row that lands on the exact same line
 * index under the exact same name (insert `origin: int` above an expanded
 * `origin: Pose` — the new row at line 0 is ALSO named "origin", so the
 * stale `"0:origin"` key remains "valid" for it even though it belongs to
 * a row nobody ever expanded). Resolving that needs a stable identity per
 * row that survives edits, which this line-oriented, reparsed-on-every-
 * keystroke design does not carry — the donor's own `${line}:${name}`
 * scheme has the identical limitation.
 */
export function pruneExpandedPaths(
  expandedPaths: ReadonlySet<string>,
  lines: readonly CodeFieldLine[],
): ReadonlySet<string> {
  const currentTopLevel = new Set(lines.map(rowIdentity));
  let changed = false;
  const next = new Set<string>();
  for (const path of expandedPaths) {
    if (currentTopLevel.has(path.split("/")[0]!)) next.add(path);
    else changed = true;
  }
  return changed ? next : expandedPaths;
}

export interface CodeFieldRowsProps {
  /** `grammar.lines(value)` — the top-level rows. */
  lines: CodeFieldLine[];
  resolveReference?(name: string): CodeFieldReference | null;
  /**
   * A row (or the blank space below the last one) was clicked. `line` is
   * the row's own line INDEX and `column` an approximate offset within it
   * (`caretOffsetFromPoint` against the row's rendered spans — exact when
   * a row's segments concatenate back to its raw source spacing,
   * approximate otherwise). `owner` is `undefined` for a top-level row —
   * `line`/`column` are then straight into this field's own `value`,
   * compose with `lineStartOffset` for a flat offset. For a row that came
   * from a reference's `expandLines()`, `owner` carries THAT reference's
   * own owner token (`CodeFieldReference.owner`, defaulting to the
   * resolved segment's text) — `line`/`column` are into THAT source, not
   * this field's, and the host must resolve `owner` to open its source
   * (the donor's rule: a foreign row jumps to its real owner, never opens
   * this field's own document at an unrelated line).
   */
  onOpenSource?(line: number, column: number, owner?: unknown): void;
  /**
   * Which rows are expanded, keyed by path (`"3"`, `"3/1"`, …). Controlled
   * — pass this alongside `onToggleExpanded` to keep expansion state alive
   * across whatever remounts `CodeFieldRows` (`CodeField` does this across
   * its own `mode` toggle: `CodeFieldRows` itself unmounts every trip
   * through Source, so state living only here reset on every round trip —
   * the donor's `TypeBabbleV1` lifts this same state for the same reason).
   * Omit both to manage it internally instead (an uncontrolled default,
   * fine for a caller that never round-trips through another mode).
   */
  expandedPaths?: ReadonlySet<string>;
  onToggleExpanded?(path: string): void;
  className?: string;
  testId?: string;
}

/**
 * The RENDERED half of `CodeField`'s `mode` toggle: `grammar.lines()` painted
 * as bold-name / accent-type / muted-value rows, a reference segment as an
 * underlined link, and a chevron for a reference that can expand in place —
 * the "code block overlay" idea: rendered by default, source only under the
 * caret. `CodeField` mounts this in place of CodeMirror while `mode ===
 * "rendered"`; it never runs alongside the live document.
 */
export function CodeFieldRows({
  lines,
  resolveReference,
  onOpenSource,
  expandedPaths,
  onToggleExpanded,
  className,
  testId,
}: CodeFieldRowsProps) {
  const [uncontrolledExpanded, setUncontrolledExpanded] = useState<ReadonlySet<string>>(() => new Set());
  const expanded = expandedPaths ?? uncontrolledExpanded;
  const toggle =
    onToggleExpanded ??
    ((path: string) =>
      setUncontrolledExpanded((current) => {
        const next = new Set(current);
        if (next.has(path)) next.delete(path);
        else next.add(path);
        return next;
      }));

  const last = lines[lines.length - 1];
  return (
    <div
      data-slot="code-field-rows"
      className={`bbox-code-field-rows${className ? ` ${className}` : ""}`}
      data-testid={testId}
      // A click that reaches this container (not caught by a row, a
      // chevron, or a reference link on the way) landed on genuinely empty
      // space below the last row. There is no more specific position than
      // "the end of the last line."
      onClick={(event) => {
        if (event.target !== event.currentTarget || !onOpenSource || !last) return;
        onOpenSource(last.line, rowText(last).length);
      }}
    >
      {lines.map((line) => (
        <CodeFieldRow
          key={rowIdentity(line)}
          line={line}
          path={rowIdentity(line)}
          owner={undefined}
          resolveReference={resolveReference}
          onOpenSource={onOpenSource}
          expandedPaths={expanded}
          togglePath={toggle}
        />
      ))}
    </div>
  );
}

function CodeFieldRow({
  line,
  path,
  owner,
  resolveReference,
  onOpenSource,
  expandedPaths,
  togglePath,
}: {
  line: CodeFieldLine;
  path: string;
  /** The owner of THIS row's own source — `undefined` at the top level, the enclosing reference's owner once nested inside its `expandLines()`. */
  owner: unknown;
  resolveReference?(name: string): CodeFieldReference | null;
  onOpenSource?(line: number, column: number, owner?: unknown): void;
  expandedPaths: ReadonlySet<string>;
  togglePath(path: string): void;
}) {
  const referenceIndex = line.segments.findIndex((segment) => segment.isReference);
  const resolved = referenceIndex >= 0 && resolveReference
    ? resolveReference(line.segments[referenceIndex]!.text)
    : null;
  const expandable = Boolean(resolved?.expandLines);
  const isOpen = expandable && expandedPaths.has(path);

  const activateRow = (event: ReactMouseEvent<HTMLElement>) => {
    if (!onOpenSource) return;
    const column = caretOffsetFromPoint(event.currentTarget, event.clientX, event.clientY);
    onOpenSource(line.line, Math.min(column, rowText(line).length), owner);
  };

  const children = isOpen && resolved?.expandLines ? resolved.expandLines() : null;
  // The owner every row inside THIS reference's expansion carries: the
  // reference's own declared token, or (the common case — `expandLines`
  // alone is enough to mark rows as foreign) the resolved segment's text.
  const childOwner = resolved ? resolved.owner ?? line.segments[referenceIndex]!.text : owner;

  return (
    <div className="bbox-code-field-row" data-slot="code-field-row" data-depth={path.split("/").length - 1}>
      <span className="bbox-code-field-row-content" onClick={activateRow}>
        <span
          aria-hidden={expandable ? undefined : true}
          className="bbox-code-field-chevron"
          data-caret-ignore=""
          data-open={isOpen || undefined}
          role={expandable ? "button" : undefined}
          tabIndex={expandable ? 0 : undefined}
          onPointerDown={expandable ? (event) => event.stopPropagation() : undefined}
          onClick={expandable ? (event) => { event.stopPropagation(); togglePath(path); } : undefined}
        >
          {expandable ? (isOpen ? "▾" : "▸") : null}
        </span>
        {line.segments.map((segment, index) => {
          const isResolvedReference = index === referenceIndex && resolved;
          const className = `bbox-code-seg${segment.role ? ` bbox-code-seg--${segment.role}` : ""}${
            isResolvedReference ? ` bbox-code-ref bbox-code-ref--${resolved.kind}` : ""
          }`;
          if (isResolvedReference && resolved.onJump) {
            return (
              <span
                key={index}
                className={className}
                role="button"
                tabIndex={0}
                onPointerDown={(event) => event.stopPropagation()}
                onClick={(event) => { event.stopPropagation(); resolved.onJump!(); }}
                onKeyDown={(event) => {
                  if (event.key !== "Enter" && event.key !== " ") return;
                  event.preventDefault();
                  event.stopPropagation();
                  resolved.onJump!();
                }}
              >
                {segment.text}
              </span>
            );
          }
          return (
            <span key={index} className={className}>
              {segment.text}
            </span>
          );
        })}
      </span>
      {isOpen && children ? (
        <div className="bbox-code-field-preview">
          {children.map((child) => (
            <CodeFieldRow
              key={rowIdentity(child)}
              line={child}
              path={`${path}/${rowIdentity(child)}`}
              owner={childOwner}
              resolveReference={resolveReference}
              onOpenSource={onOpenSource}
              expandedPaths={expandedPaths}
              togglePath={togglePath}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
}

import {
  autocompletion,
  type CompletionContext,
  type CompletionResult,
} from "@codemirror/autocomplete";
import { RangeSetBuilder, type Extension } from "@codemirror/state";
import {
  Decoration,
  EditorView,
  WidgetType,
  type DecorationSet,
} from "@codemirror/view";

/** Which named region the caret sits in, and the text CodeMirror would replace on completion. */
export interface CodeFieldSlotAt {
  slot: string;
  start: number;
  end: number;
  query: string;
}

/** One highlighted span, expressed as a CSS class rather than a CodeMirror type. */
export interface CodeFieldDecorationRange {
  from: number;
  to: number;
  className: string;
}

export interface CodeFieldCompletion {
  label: string;
  detail?: string;
  /** CodeMirror's completion `type` — drives the built-in icon set, purely cosmetic. */
  type?: string;
}

export interface CodeFieldCompletionContext {
  text: string;
  pos: number;
  explicit: boolean;
}

export interface CodeFieldCompletionResult {
  /** Where the accepted completion starts replacing text. */
  from: number;
  /** Defaults to the caret. */
  to?: number;
  options: CodeFieldCompletion[];
}

/** One role-tagged run of text within a rendered row — a name, a type, a bit of punctuation. */
export interface CodeFieldSegment {
  text: string;
  /** A CSS-class hook (e.g. `"name"` → `.bbox-code-seg--name`); omit for unstyled text. */
  role?: string;
  /**
   * This segment names something `grammar.resolveReference` can look up.
   * The renderer asks only for segments actually on screen — resolution
   * never runs during `lines()` itself, so a grammar's parse stays cheap
   * even when resolution means a board-wide scan.
   */
  isReference?: boolean;
}

/** One row of the RENDERED-mode tree — `grammar.lines`' unit of output. */
export interface CodeFieldLine {
  /** 0-based index into the SOURCE this line came from — the field's own `value` for a top-level row, or the reference's own text for a row from `expandLines()`. This is what a `CodeFieldRows` click reports as `onOpenSource`'s `line` argument. */
  line: number;
  /**
   * Absolute character offset of the line's own start, within that SAME
   * source. NOT what `onOpenSource` reports (it reports `line`, the index,
   * so the host can place it against whichever source `owner` names) —
   * this is metadata on the row itself, e.g. for a grammar that wants to
   * report offsets without re-deriving them from `line` and the source text.
   */
  lineStart: number;
  /** Nesting depth. 0 for every row `lines()` returns directly; a reference's `expandLines()` returns its own rows at `parentDepth + 1`, applied by the renderer, not stamped here. */
  indent: number;
  segments: CodeFieldSegment[];
}

/** What a reference segment resolves to: a click target, and/or more rows to show in place. */
export interface CodeFieldReference {
  /** A grammar-defined vocabulary word (e.g. `"known"` / `"unknown"` / `"primitive"`) — a styling and behaviour hook, not interpreted by the field itself. */
  kind: string;
  /** Present when clicking the reference should navigate elsewhere instead of (or in addition to) expanding. */
  onJump?(): void;
  /**
   * Present when this reference can expand in place — e.g. a record type's
   * own fields, one level deeper. Called lazily, only while the row is
   * open, and only re-called when the row is toggled shut and open again —
   * so an expensive lookup (a live board scan) runs once per look, not
   * once per keystroke anywhere on the field.
   */
  expandLines?(): CodeFieldLine[] | null;
  /**
   * Identifies this reference as the owner of every row `expandLines()`
   * returns — an opaque token the grammar defines (a block id, a type
   * name, anything `onOpenSource`'s caller can recognise). A row inside an
   * expansion is NOT part of the field's own document — it's a preview of
   * something else's — so clicking one must report that it belongs to a
   * different source, not silently misapply its line number against the
   * top-level `value` (the donor's rule: a foreign row jumps to its real
   * owner and opens SOURCE there, at that row's own line — never "this
   * field's source at some unrelated line").
   *
   * Defaults to the resolved segment's own text (e.g. `"Pose"`) when
   * omitted, so `expandLines` alone is already enough to mark its rows as
   * foreign; set this explicitly for a richer token (an actual block
   * reference) a host can act on directly.
   */
  owner?: unknown;
}

/**
 * What makes a `CodeField` know its grammar. Every hook is optional — the
 * empty grammar `{}` is the plain code text box: a real CodeMirror document,
 * no slots, no completions, no marks. `slotAt` is the one function this
 * whole design rests on: a port line, a `Name = expr` alias, a nested
 * attribute tree are each a new `slotAt` plus a `decorate`/`complete` pair,
 * never a new editor.
 *
 * WHY a declarative object instead of a raw CodeMirror `Extension[]` (what
 * the field this was extracted from originally took): a grammar author
 * should not have to learn `RangeSetBuilder`, `StateField` and the
 * `autocompletion` API just to say "these are my three roles, this is what
 * completes after a colon". `grammarExtensions` below is the one place that
 * translation happens; a grammar that genuinely needs raw CodeMirror machinery
 * (a `StateField`, a widget) can still pass it through `CodeFieldGrammar.language`
 * alongside these hooks — `language` is any `Extension`, not just a lezer parser.
 */
export interface CodeFieldGrammar {
  /** A CodeMirror language/parser extension (e.g. `python()`), or any other raw extension the grammar needs mounted. */
  language?: Extension;
  /** Which slot the caret sits in. Drives `complete`; also useful to a host that wants to know what's under the cursor. */
  slotAt?(text: string, caret: number): CodeFieldSlotAt | null;
  /** Marks to paint over the raw text, recomputed on every document change. */
  decorate?(text: string): CodeFieldDecorationRange[];
  /**
   * One completion source, dispatched by slot. Return `null` (or an empty
   * `options` list) to offer nothing — that is the grammar's call, not the
   * field's: `signatureGrammar` refuses to complete the `name` slot so a
   * free-text label is never interrupted while it is typed.
   */
  complete?(
    slot: CodeFieldSlotAt | null,
    query: string,
    ctx: CodeFieldCompletionContext,
  ): CodeFieldCompletionResult | null;
  /**
   * Live-preview style folding for a lane: a line the caret is NOT on shows
   * at most this many characters, then an ellipsis; the caret's own line
   * always shows in full, and moving onto a folded line unfolds it (the
   * decoration recomputes from the selection). Omit for no folding. Has no
   * visible effect on a single-line field — there is only ever one line,
   * and it always holds the caret.
   */
  foldInactiveLinesAfter?: number;
  /**
   * The RENDERED-mode tree: the source parsed into rows of role-tagged
   * segments (bold name, accent type, muted default…), the "code block
   * overlay" — rendered by default, source only under the caret. Required
   * for `CodeField`'s `mode="rendered"`; a grammar that has no rendered
   * view (the plain code text box) simply omits it, and `mode` has nothing
   * to switch to.
   *
   * Nesting is a grammar concern, not a component one: `lines()` itself
   * only ever returns flat, `indent: 0` rows for the source's own lines —
   * a row that names a known reference nests DEEPER rows by resolving it
   * (`resolveReference(name).expandLines()`), not by the source text's own
   * indentation. That is what lets an attribute tree, a flat port lane and
   * a self-referencing type all share one renderer.
   */
  lines?(text: string): CodeFieldLine[];
  /**
   * What a segment marked `isReference` resolves to. Omit to render every
   * reference as plain text with no click target — the grammar's call, not
   * a default the field guesses at (a "known" judgement usually means a
   * live scan of something outside the field, e.g. a host's own registry).
   */
  resolveReference?(name: string): CodeFieldReference | null;
  /**
   * A short label for the completion badge/pill shown beside an option
   * whose `type` (`CodeFieldCompletion.type`) matches — the kind-pill
   * pattern from the grammar this was extracted from. Return `null`/
   * `undefined` for a type with no badge.
   */
  completionBadge?(type: string): string | null | undefined;
}

function decorationExtension(decorate: NonNullable<CodeFieldGrammar["decorate"]>): Extension {
  return EditorView.decorations.compute(["doc"], (state) => {
    const ranges = decorate(state.doc.toString())
      .filter((range) => range.to > range.from)
      .slice()
      .sort((a, b) => a.from - b.from || a.to - b.to);
    const builder = new RangeSetBuilder<Decoration>();
    for (const range of ranges) {
      builder.add(range.from, range.to, Decoration.mark({ class: range.className }));
    }
    return builder.finish();
  });
}

function completionExtension(grammar: CodeFieldGrammar): Extension {
  const complete = grammar.complete!;
  const slotAt = grammar.slotAt;
  const source = (context: CompletionContext): CompletionResult | null => {
    const text = context.state.doc.toString();
    const slot = slotAt ? slotAt(text, context.pos) : null;
    const result = complete(slot, slot?.query ?? "", {
      text,
      pos: context.pos,
      explicit: context.explicit,
    });
    if (!result || result.options.length === 0) return null;
    return {
      from: result.from,
      to: result.to ?? context.pos,
      options: result.options.map((option) => ({
        label: option.label,
        detail: option.detail,
        type: option.type,
      })),
    };
  };
  // WHY `tooltipClass` is set unconditionally (not only when a badge is
  // configured): `.bbox-code-completion` is the class `codeField.css`'s
  // z-index rule targets. Without it every plain CodeField (no
  // `completionBadge`) got a popup with only CodeMirror's own default
  // classes — the bare `.cm-tooltip` selector round 1 shipped never had
  // enough specificity to beat CodeMirror's base theme rule either way,
  // but this is what makes the round-2 fix apply to EVERY completion
  // popup, not only the ones with a kind pill.
  const badge = grammar.completionBadge;
  return autocompletion({
    override: [source],
    icons: false,
    tooltipClass: () => "bbox-code-completion",
    ...(badge && {
      addToOptions: [
        {
          position: 20,
          render: (completion) => {
            const label = completion.type ? badge(completion.type) : null;
            if (!label) return null;
            const pill = document.createElement("span");
            pill.className = "bbox-code-completion-pill";
            pill.dataset.kind = completion.type;
            pill.textContent = label;
            return pill;
          },
        },
      ],
    }),
  });
}

class CodeFieldEllipsisWidget extends WidgetType {
  override eq(): boolean {
    return true;
  }
  override toDOM(): HTMLElement {
    const span = document.createElement("span");
    span.className = "bbox-code-field-ellipsis";
    span.textContent = "…";
    return span;
  }
  override ignoreEvent(): boolean {
    return false;
  }
}

/**
 * The UTF-16 offset `maxCodePoints` *code points* into `text` — never
 * inside a surrogate pair. `for...of` (and the spread below) iterates by
 * code point, so a two-unit character (most emoji) always counts as one
 * and is never split; a naive `text.slice(0, maxChars)` on code UNITS can
 * land between a high and low surrogate, leaving a lone unpaired
 * surrogate on screen (renders as a replacement glyph, sometimes worse).
 */
function codePointOffset(text: string, maxCodePoints: number): number {
  let count = 0;
  let offset = 0;
  for (const char of text) {
    if (count >= maxCodePoints) break;
    offset += char.length;
    count += 1;
  }
  return offset;
}

function foldExtension(maxChars: number): Extension {
  return EditorView.decorations.compute(["doc", "selection"], (state): DecorationSet => {
    const builder = new RangeSetBuilder<Decoration>();
    const active = new Set<number>();
    for (const range of state.selection.ranges) {
      active.add(state.doc.lineAt(range.head).number);
      active.add(state.doc.lineAt(range.anchor).number);
    }
    for (let number = 1; number <= state.doc.lines; number += 1) {
      const line = state.doc.line(number);
      if (active.has(number) || [...line.text].length <= maxChars) continue;
      builder.add(
        line.from + codePointOffset(line.text, maxChars),
        line.to,
        Decoration.replace({ widget: new CodeFieldEllipsisWidget() }),
      );
    }
    return builder.finish();
  });
}

/** Translates a declarative `CodeFieldGrammar` into the CodeMirror extensions `CodeField` mounts. */
export function grammarExtensions(grammar: CodeFieldGrammar): Extension[] {
  const extensions: Extension[] = [];
  if (grammar.language) extensions.push(grammar.language);
  if (grammar.decorate) extensions.push(decorationExtension(grammar.decorate));
  if (grammar.complete) extensions.push(completionExtension(grammar));
  if (grammar.foldInactiveLinesAfter != null) {
    extensions.push(foldExtension(grammar.foldInactiveLinesAfter));
  }
  return extensions;
}

import {
  acceptCompletion,
  autocompletion,
  closeCompletion,
  completionStatus,
  currentCompletions,
  insertCompletionText,
  pickedCompletion,
  selectedCompletionIndex,
  setSelectedCompletion,
  startCompletion,
  type Completion,
  type CompletionContext,
  type CompletionResult,
} from "@codemirror/autocomplete";
import { cursorLineDown, cursorLineUp } from "@codemirror/commands";
import { Prec, StateEffect, StateField, type EditorState, type Extension } from "@codemirror/state";
import {
  EditorView,
  getTooltip,
  keymap,
  showTooltip,
  type Command,
  type Rect,
  type TooltipView,
  ViewPlugin,
} from "@codemirror/view";

/**
 * The autocomplete menu: one CodeMirror extension any field can mount.
 *
 * It is CodeMirror's own completion tooltip — its DOM, ARIA, mouse accept,
 * vertical flip (sticky for the session) and horizontal clamp are all
 * reused untouched — plus the parts the stock popup does not have: a
 * configurable anchor, a configurable end-of-list rule, a second-invocation
 * "widen" mode with a footer strip, Tab-vs-Enter replacement, a kind-badge
 * column and a "No matches" row.
 *
 * A field plugs it in through anything that takes an `Extension`. Today's
 * `CodeField` needs no change at all — a grammar passes the menu as its
 * `language` and leaves `complete` unset:
 *
 * ```ts
 * const grammar: CodeFieldGrammar = {
 *   language: [python(), completionMenu({ source, badge, footer })],
 * };
 * ```
 *
 * The later swap inside `codeGrammar.ts`'s `completionExtension` is
 * this, replacing its `autocompletion({...})` call:
 *
 * ```ts
 * return completionMenu({
 *   source: ({ text, pos, explicit }) => {
 *     const slot = grammar.slotAt?.(text, pos) ?? null;
 *     return grammar.complete!(slot, slot?.query ?? "", { text, pos, explicit });
 *   },
 *   badge: grammar.completionBadge,
 * });
 * ```
 *
 * (`complete`'s own `from`/`to` are then superseded by the menu's word
 * detection — pass `wordChar` when a grammar's slot is not an identifier run.)
 *
 * Never mount it beside a second `autocompletion()` in the same editor —
 * CodeMirror cannot merge two `override` lists and throws.
 */

/** Where the popup's left edge is pinned. See `CompletionMenuOptions.anchor`. */
export type CompletionMenuAnchor = "cursor" | "word" | "field";

/** What ↑ on the first item / ↓ on the last item does. See `CompletionMenuOptions.atEnds`. */
export type CompletionMenuAtEnds = "wrap" | "caret";

/** One row of the menu. Pure data — the menu owns every DOM and keyboard concern. */
export interface CompletionMenuItem {
  label: string;
  /** Right-aligned, and the first thing to truncate when the row is tight. */
  detail?: string;
  /** A kind tag. Drives `badge` and lands on the pill as `data-kind`, never interpreted otherwise. */
  type?: string;
  /** Struck through and dimmed, but still selectable. */
  deprecated?: boolean;
}

/** The identifier run around the caret: `[from, to)` is the whole word, `query` the part before the caret. */
export interface CompletionMenuWord {
  from: number;
  to: number;
  query: string;
}

export interface CompletionMenuContext {
  /** The whole document. */
  text: string;
  /** The caret. */
  pos: number;
  /** Opened by Ctrl+Space rather than by typing. */
  explicit: boolean;
  /**
   * Ctrl+Space was pressed again while the menu was open (JetBrains'
   * "second invocation") — offer the wider vocabulary. Pressing it once
   * more narrows back. Resets to `false` whenever the word being completed
   * changes, on Escape and on accept.
   */
  widened: boolean;
  word: CompletionMenuWord;
}

export interface CompletionMenuFooter {
  /** Beside the `Ctrl Space` key cap while narrow, e.g. `"every type on this board"`. */
  hint: string;
  /** Shown while widened instead of `hint`, e.g. `"back to likely matches"`. Defaults to `hint`. */
  widenedHint?: string;
  /** Told after every widen/narrow flip, whether it came from the key or a click on the footer. */
  onToggle?(widened: boolean): void;
}

export interface CompletionMenuOptions {
  /**
   * Return `null` to refuse outright (the menu stays closed, even on
   * Ctrl+Space — e.g. a free-text slot). Return `{ options: [] }` for
   * "nothing matched": closed while typing, a muted `No matches for “x”`
   * row when opened with Ctrl+Space. Never called while typing an empty
   * word, so a source never sees the keystroke that typed a space.
   *
   * Runs synchronously, on every keystroke, inside CodeMirror's state
   * update — keep it a pure function of its context; never dispatch.
   */
  source(ctx: CompletionMenuContext): { options: CompletionMenuItem[] } | null;
  /**
   * - `"cursor"` — the left edge follows the caret on every keystroke (VS Code).
   * - `"word"` — pinned to the start of the word being completed; typing
   *   inside the word does not slide it (IntelliJ, CodeMirror's default).
   * - `"field"` — pinned to the start of the line, i.e. the start of a
   *   single-line box (tight spaces).
   *
   * In every mode the popup prefers below, flips above only when below
   * does not fit and above has more room, stays on that side until it
   * closes, and slides sideways to stay on screen — never flips sideways.
   *
   * @default "word"
   */
  anchor?: CompletionMenuAnchor;
  /**
   * - `"wrap"` — ↓ on the last item goes to the first, ↑ on the first to the last.
   * - `"caret"` — ↓ on the last item closes the menu and moves the caret
   *   down a line; ↑ on the first closes it and moves the caret up. With a
   *   single item this is VS Code's behaviour.
   *
   * PageUp/PageDown always clamp at the ends.
   *
   * @default "wrap"
   */
  atEnds?: CompletionMenuAtEnds;
   /**
   * Whether ↓ on a CLOSED menu opens it instead of moving the caret — the
   * W3C combobox rule for a one-line field, which has no next line to move
   * to. The HOST declares this, because only the host knows whether the
   * field is single-line: a multiline field whose document happens to hold
   * one line right now is still a multiline field, and ↓ there belongs to
   * the caret. Even when true, ↓ only claims the key if the source actually
   * has something to show.
   *
   * @default false
   */
  openOnArrowDown?: boolean;
  /** Visible rows before the list scrolls. @default 10 */
  maxRows?: number;
  /** The kind pill for an item's `type`. Configuring it reserves a fixed-width column so every label lines up, pill or not. */
  badge?(type: string): string | null | undefined;
  /** A non-selectable strip under the list that toggles widen/narrow. Omit for no footer. */
  footer?: CompletionMenuFooter;
  /**
   * Matches ONE identifier character; the word is the maximal run of them
   * around the caret. Global/sticky flags are ignored.
   *
   * @default DEFAULT_WORD_CHAR (letters, digits, `_`, `$`)
   */
  wordChar?: RegExp;
}

// WHY both are options with defaults, not a decision baked in (Zach,
// 2026-09-14: "don't choose, support the different types, adjustable to
// people's preferences later"): cursor-following vs word-pinned and
// wrap vs fall-through-to-caret are each a real, shipped convention with
// its own users (VS Code vs IntelliJ). The defaults are only the reversible
// starting point; nothing below assumes either one.
const DEFAULT_ANCHOR: CompletionMenuAnchor = "word";
const DEFAULT_AT_ENDS: CompletionMenuAtEnds = "wrap";
const DEFAULT_MAX_ROWS = 10;

export const DEFAULT_WORD_CHAR = /[\p{L}\p{N}_$]/u;

function singleCharTester(wordChar: RegExp): (char: string) => boolean {
  // A `g`/`y` regex carries `lastIndex` between `test` calls and would
  // silently skip characters — strip those flags once, up front.
  const tester = new RegExp(wordChar.source, wordChar.flags.replace(/[gy]/g, ""));
  return (char) => tester.test(char);
}

/** The code point ending at UTF-16 offset `end` (never half a surrogate pair). */
function charBefore(text: string, end: number): string {
  const low = text.charCodeAt(end - 1);
  if (end >= 2 && low >= 0xdc00 && low <= 0xdfff) {
    const high = text.charCodeAt(end - 2);
    if (high >= 0xd800 && high <= 0xdbff) return text.slice(end - 2, end);
  }
  return text.slice(end - 1, end);
}

/** The code point starting at UTF-16 offset `start`. */
function charAt(text: string, start: number): string {
  return String.fromCodePoint(text.codePointAt(start)!);
}

/**
 * The identifier run around `pos`: scans left and right while characters
 * match `wordChar`. A caret between two non-word characters yields an
 * empty word at `pos`.
 */
export function wordAt(text: string, pos: number, wordChar: RegExp = DEFAULT_WORD_CHAR): CompletionMenuWord {
  const isWordChar = singleCharTester(wordChar);
  let from = pos;
  while (from > 0) {
    const char = charBefore(text, from);
    if (!isWordChar(char)) break;
    from -= char.length;
  }
  let to = pos;
  while (to < text.length) {
    const char = charAt(text, to);
    if (!isWordChar(char)) break;
    to += char.length;
  }
  return { from, to, query: text.slice(from, pos) };
}

/**
 * The document range an accepted `label` replaces.
 *
 * - `"tab"` replaces the whole identifier, both sides of the caret.
 * - `"enter"` replaces up to the caret, and also eats the text after the
 *   caret only when that text is a suffix of the pick — so `Ty|pe` → `Type`
 *   (not `Typepe`), while `Pos|xx` → `Posexx` keeps an unrelated tail.
 */
export function acceptRange(
  mode: "tab" | "enter",
  word: CompletionMenuWord,
  pos: number,
  text: string,
  label: string,
): { from: number; to: number } {
  if (mode === "tab") return { from: word.from, to: word.to };
  const after = text.slice(pos, word.to);
  return { from: word.from, to: label.endsWith(after) ? word.to : pos };
}

/** Either the next selected index, or "leave the list" in a direction. */
export type CompletionMenuStep = { index: number } | { exit: "up" | "down" };

/**
 * Where ↑/↓/PageUp/PageDown take the selection. `current` is `-1` when
 * nothing is selected; `count` is the number of SELECTABLE rows (0 for
 * the "No matches" row). `pageSize` > 1 means a page move, which clamps
 * at the ends regardless of `atEnds`.
 */
export function stepSelection(
  current: number,
  count: number,
  direction: "up" | "down",
  atEnds: CompletionMenuAtEnds,
  pageSize = 1,
): CompletionMenuStep {
  const paging = pageSize > 1;
  if (count <= 0) return atEnds === "caret" && !paging ? { exit: direction } : { index: current };
  if (current < 0) return { index: direction === "down" ? 0 : count - 1 };
  const next = current + (direction === "down" ? pageSize : -pageSize);
  if (paging) return { index: Math.max(0, Math.min(count - 1, next)) };
  if (next >= count) return atEnds === "wrap" ? { index: 0 } : { exit: "down" };
  if (next < 0) return atEnds === "wrap" ? { index: count - 1 } : { exit: "up" };
  return { index: next };
}

/**
 * The label runs to embolden for `query`: the first case-insensitive
 * occurrence (a prefix whenever there is one), as CodeMirror's flat
 * `[from, to, from, to…]` list. Compared slice by slice so a character
 * whose lower-case form has a different length cannot skew the offsets.
 */
export function matchRanges(label: string, query: string): number[] {
  if (!query) return [];
  const needle = query.toLowerCase();
  for (let index = 0; index + query.length <= label.length; index += 1) {
    if (label.slice(index, index + query.length).toLowerCase() === needle) {
      return [index, index + query.length];
    }
  }
  return [];
}

/** Per-word widen state. `wordFrom` is where the word under the caret starts. */
export interface CompletionMenuWidenState {
  widened: boolean;
  wordFrom: number;
}

/**
 * The widen reducer. An explicit set wins; otherwise moving to a
 * different word narrows back — "every type on this board" is a mode of
 * one word's conversation, not a sticky preference (the donor's
 * `broadenField` rule, systemsketch `typeNameCompletion.ts`).
 */
export function nextWidenState(
  previous: CompletionMenuWidenState,
  wordFrom: number,
  set?: boolean,
): CompletionMenuWidenState {
  if (set !== undefined) return { widened: set, wordFrom };
  if (wordFrom !== previous.wordFrom) return { widened: false, wordFrom };
  return previous;
}

const NO_MATCH_CLASS = "bbox-completion-menu__empty";

function wordAtState(state: EditorState, pos: number, wordChar: RegExp): CompletionMenuWord {
  // Words never span a newline, so scanning the caret's line is enough and
  // keeps this O(line) on every keystroke instead of O(document).
  const line = state.doc.lineAt(pos);
  const local = wordAt(line.text, pos - line.from, wordChar);
  return { from: local.from + line.from, to: local.to + line.from, query: local.query };
}

/** The completion popup's own tooltip view in `view`, if it is on screen. */
function menuTooltipView(view: EditorView): TooltipView | null {
  for (const tooltip of view.state.facet(showTooltip)) {
    if (!tooltip) continue;
    const tooltipView = getTooltip(view, tooltip);
    if (tooltipView?.dom.classList.contains("cm-tooltip-autocomplete")) return tooltipView;
  }
  return null;
}

/** Rows that fit in the list right now, minus one — the page step, as CodeMirror computes it. */
function pageStep(dom: HTMLElement): number {
  const list = dom.querySelector("ul");
  const row = list?.querySelector("li");
  if (!list || !row || row.offsetHeight === 0) return 1;
  return Math.max(1, Math.floor(list.clientHeight / row.offsetHeight) - 1);
}

export function completionMenu(options: CompletionMenuOptions): Extension {
  const anchor = options.anchor ?? DEFAULT_ANCHOR;
  const atEnds = options.atEnds ?? DEFAULT_AT_ENDS;
  const maxRows = Math.max(1, Math.floor(options.maxRows ?? DEFAULT_MAX_ROWS));
  const wordChar = options.wordChar ?? DEFAULT_WORD_CHAR;
  const openOnArrowDown = options.openOnArrowDown ?? false;
  const { badge, footer } = options;

  const setWidened = StateEffect.define<boolean>();
  const widenField = StateField.define<CompletionMenuWidenState>({
    create: (state) => ({ widened: false, wordFrom: wordAtState(state, state.selection.main.head, wordChar).from }),
    update(value, tr) {
      let set: boolean | undefined;
      for (const effect of tr.effects) if (effect.is(setWidened)) set = effect.value;
      if (set === undefined && !tr.docChanged && !tr.selection) return value;
      const wordFrom = wordAtState(tr.state, tr.state.selection.main.head, wordChar).from;
      return nextWidenState(value, wordFrom, set);
    },
  });

  // The rows the menu rendered, keyed by CodeMirror's own completion
  // object — so `optionClass`/`addToOptions` can style a row from the
  // source's data without widening CodeMirror's `Completion` type.
  const rows = new WeakMap<Completion, CompletionMenuItem | "no-match">();
  let acceptMode: "tab" | "enter" = "enter";

  // WHY one `apply` for every row, reading the accept mode from a closure
  // rather than CodeMirror's `from`/`to`: Tab and Enter replace DIFFERENT
  // ranges (`acceptRange`), and CodeMirror's `apply` has no idea which key
  // fired it. Routing both keys through `acceptCompletion` (not a
  // hand-rolled insert) keeps its guards — read-only, a list mid-refresh,
  // the 75 ms "just opened" interaction delay. A mouse click arrives here
  // with the default, Enter's semantics.
  const apply = (view: EditorView, completion: Completion) => {
    const { state } = view;
    const pos = state.selection.main.head;
    const word = wordAtState(state, pos, wordChar);
    const range = acceptRange(acceptMode, word, pos, state.doc.toString(), completion.label);
    view.dispatch({
      ...insertCompletionText(state, completion.label, range.from, range.to),
      annotations: pickedCompletion.of(completion),
      effects: setWidened.of(false),
    });
  };
  // The "No matches" row is a statement, not a candidate: a click on it does
  // nothing (Enter/Tab on it close the menu instead — see `accept` — so
  // neither key is silently swallowed).
  const inert = () => {};

  const compute = (state: EditorState, pos: number, explicit: boolean): CompletionResult | null => {
    const word = wordAtState(state, pos, wordChar);
    if (!explicit && word.query === "") return null;
    const { widened } = state.field(widenField);
    const result = options.source({ text: state.doc.toString(), pos, explicit, widened, word });
    if (!result) return null;
    let completions: Completion[];
    if (result.options.length > 0) {
      completions = result.options.map((item) => {
        const completion: Completion = { label: item.label, detail: item.detail, type: item.type, apply };
        rows.set(completion, item);
        return completion;
      });
    } else if (explicit) {
      const completion: Completion = { label: `No matches for “${word.query}”`, apply: inert };
      rows.set(completion, "no-match");
      completions = [completion];
    } else {
      return null;
    }
    return {
      from: word.from,
      to: pos,
      options: completions,
      // The source already ranked its answer; CodeMirror's fuzzy filter
      // would impose a second, disagreeing opinion (the donor's own call).
      filter: false,
      getMatch: (completion) => (rows.get(completion) === "no-match" ? [] : matchRanges(completion.label, word.query)),
      // Recompute synchronously on each keystroke rather than waiting out
      // CodeMirror's re-query debounce — the list and (for `anchor:
      // "cursor"`) the popup's position then change in the same frame as
      // the typed letter. An empty list closes at once instead of lingering
      // disabled for a debounce. `explicit` carries over from the query
      // that opened this session, as CodeMirror's own result state does.
      update: (_current, from, _to, context) =>
        compute(context.state, context.pos, explicit) ?? { from, options: [] },
    };
  };
  const source = (context: CompletionContext) => compute(context.state, context.pos, context.explicit);

  const isNoMatch = (completions: readonly Completion[]) =>
    completions.length === 1 && rows.get(completions[0]!) === "no-match";

  const toggleWidened = (view: EditorView) => {
    // WHY nothing happens with no word typed: an explicit open on an empty
    // word already lists everything the source has, so "widen" has nothing
    // left to add and "narrow" would have no query to narrow to. Toggling
    // anyway left the menu silently widened for the word typed next.
    if (wordAtState(view.state, view.state.selection.main.head, wordChar).query === "") return;
    const next = !view.state.field(widenField).widened;
    view.dispatch({ effects: setWidened.of(next) });
    startCompletion(view);
    footer?.onToggle?.(next);
  };

  const move =
    (direction: "up" | "down", paging: boolean): Command =>
    (view) => {
      if (completionStatus(view.state) === null) {
        if (!openOnArrowDown || direction !== "down" || paging) return false;
        // Ask the source first. Claiming the key and then opening nothing
        // would leave ↓ dead in a field whose source has no answer here.
        const pos = view.state.selection.main.head;
        const probe = options.source({
          text: view.state.doc.toString(),
          pos,
          explicit: true,
          widened: view.state.field(widenField).widened,
          word: wordAtState(view.state, pos, wordChar),
        });
        if (!probe || probe.options.length === 0) return false;
        if (view.state.field(widenField).widened) view.dispatch({ effects: setWidened.of(false) });
        startCompletion(view);
        return true;
      }
      const tooltip = menuTooltipView(view);
      // Nothing on screen yet (the first query is still pending): the key
      // belongs to the caret, exactly as if the menu were closed.
      if (!tooltip) return false;
      const completions = currentCompletions(view.state);
      // A list mid-refresh (Ctrl+Space re-querying) is still on screen;
      // swallow the key rather than let it move the caret under it.
      if (completions.length === 0) return true;
      const count = isNoMatch(completions) ? 0 : completions.length;
      const current = selectedCompletionIndex(view.state) ?? -1;
      const step = stepSelection(current, count, direction, atEnds, paging ? Math.max(2, pageStep(tooltip.dom)) : 1);
      if ("exit" in step) {
        closeCompletion(view);
        (step.exit === "down" ? cursorLineDown : cursorLineUp)(view);
        return true;
      }
      if (step.index !== current && step.index >= 0) view.dispatch({ effects: setSelectedCompletion(step.index) });
      return true;
    };

  const accept =
    (mode: "tab" | "enter"): Command =>
    (view) => {
      if (completionStatus(view.state) === null || !menuTooltipView(view)) return false;
      const completions = currentCompletions(view.state);
      if (completions.length === 0) return mode === "tab";
      if (isNoMatch(completions)) {
        closeCompletion(view);
        return true;
      }
      acceptMode = mode;
      try {
        const accepted = acceptCompletion(view);
        // Tab with a visible menu never falls through to the browser's
        // focus move, even inside the just-opened interaction delay.
        return accepted || mode === "tab";
      } finally {
        acceptMode = "enter";
      }
    };

  const invoke: Command = (view) => {
    if (completionStatus(view.state) !== null && menuTooltipView(view)) {
      toggleWidened(view);
    } else {
      // A fresh explicit open always starts narrow.
      if (view.state.field(widenField).widened) view.dispatch({ effects: setWidened.of(false) });
      startCompletion(view);
    }
    return true;
  };

  const menuKeymap = Prec.highest(
    keymap.of([
      { key: "Ctrl-Space", run: invoke },
      // CodeMirror's own macOS alternates (Ctrl-Space is the input-source
      // switch there), kept so switching to this menu drops no binding.
      { mac: "Alt-`", run: invoke },
      { mac: "Alt-i", run: invoke },
      {
        key: "Escape",
        run: (view) => {
          if (!closeCompletion(view)) return false;
          if (view.state.field(widenField).widened) view.dispatch({ effects: setWidened.of(false) });
          return true;
        },
      },
      { key: "ArrowDown", run: move("down", false) },
      { key: "ArrowUp", run: move("up", false) },
      { key: "PageDown", run: move("down", true) },
      { key: "PageUp", run: move("up", true) },
      { key: "Tab", run: accept("tab") },
      { key: "Enter", run: accept("enter") },
    ]),
  );

  // WHY the popup is moved through the tooltip view's `getCoords`, not by
  // returning a different `from` (the obvious route — CodeMirror places the
  // popup at the result's `from`): `from` is also CodeMirror's bookkeeping
  // for the completed range, and its Backspace rule closes the popup
  // whenever the caret was sitting exactly at `from`. With `from` = caret
  // (the "cursor" anchor) EVERY Backspace would close the menu. `getCoords`
  // is `TooltipView`'s documented hook for "the view finds its own screen
  // position"; everything downstream of it — flip-and-stay, horizontal
  // clamp, the hide-when-scrolled-away check — is still CodeMirror's.
  const anchorCoords =
    anchor === "word"
      ? null
      : (view: EditorView) => (): Rect => {
          const head = view.state.selection.main.head;
          const pos = anchor === "cursor" ? head : view.state.doc.lineAt(head).from;
          // A null (position scrolled out of the DOM) is what CodeMirror's
          // own `coordsAtPos` fallback returns too; its measure hides the
          // tooltip for it.
          return view.coordsAtPos(pos) as Rect;
        };

  const footerFor = new WeakMap<HTMLElement, HTMLElement>();
  const patched = new WeakSet<TooltipView>();

  // WHY the footer is a strip of its own and not a final list option (what
  // the donor shipped: a "show every type on this board" row at the foot
  // of the list): as an option, ↓ from the last real item lands on it, Enter
  // on it toggles instead of inserting, and in `atEnds: "caret"` it would
  // stand between the last item and the caret leaving the list. It is
  // chrome that explains a key, not a candidate — so it lives outside the
  // `<ul>`, where CodeMirror's selection cannot reach it at all.
  const renderFooter = (view: EditorView, dom: HTMLElement) => {
    if (!footer) return;
    let strip = footerFor.get(dom);
    if (!strip) {
      strip = document.createElement("div");
      strip.className = "bbox-completion-menu__footer";
      const key = strip.appendChild(document.createElement("kbd"));
      key.textContent = "Ctrl Space";
      strip.appendChild(document.createElement("span"));
      // mousedown: keep focus in the editor (a focus move would close the
      // popup via CodeMirror's blur rule). click: do what the key does.
      strip.addEventListener("mousedown", (event) => event.preventDefault());
      strip.addEventListener("click", (event) => {
        event.preventDefault();
        toggleWidened(view);
      });
      footerFor.set(dom, strip);
    }
    const { widened } = view.state.field(widenField);
    // With no word typed the explicit list already IS everything, so the
    // strip would promise a toggle that cannot change the list (it also
    // stops ↓-into-an-empty-field looking like it has a hidden second mode).
    const empty = wordAtState(view.state, view.state.selection.main.head, wordChar).query === "";
    // Append FIRST and hide with the attribute: if an empty word skipped the
    // append, "no footer on screen" would also be true with the hiding rule
    // broken, and the check for it could never fail.
    if (dom.lastElementChild !== strip) dom.appendChild(strip);
    strip.hidden = empty;
    dom.classList.toggle("bbox-completion-menu--has-footer", !empty);
    if (empty) return;
    const text = widened ? (footer.widenedHint ?? footer.hint) : footer.hint;
    const label = strip.lastElementChild!;
    if (label.textContent !== text) label.textContent = text;
    strip.dataset.widened = widened ? "true" : "false";
    // CodeMirror re-creates its `<ul>` with `appendChild` whenever the
    // option list changes, which would land the new list AFTER the strip;
    // re-appending keeps the strip last in DOM order too (the CSS `order`
    // already keeps it last on screen).
    if (dom.lastElementChild !== strip) dom.appendChild(strip);
  };

  // Runs after every update, once every plugin (the tooltip plugin
  // included) has updated and before the next measure — so a freshly
  // created popup has its anchor hook, row cap and footer in place before
  // it is first positioned or painted.
  const decorateTooltip = EditorView.updateListener.of((update) => {
    const openNow = completionStatus(update.state) !== null;
    // WHY the close is watched here rather than inside `widenField`: reading
    // the completion's own state field from that field's `update` is a cycle
    // CodeMirror forbids. Widening is a mode of ONE open menu — when it
    // closes for any reason at all (Esc, accept, a click away, focus lost),
    // it goes back to narrow, so a refocus can never reopen a silently
    // widened list.
    if (completionStatus(update.startState) !== null && !openNow && update.state.field(widenField).widened) {
      update.view.dispatch({ effects: setWidened.of(false) });
    }
    const tooltipView = menuTooltipView(update.view);
    // CodeMirror sets aria-haspopup/controls/activedescendant on the content
    // element but never the expanded state, which the combobox pattern needs.
    // It follows what is ON SCREEN, not `completionStatus`: a "pending" query
    // has no popup yet, and announcing one that is not there is a lie.
    const expanded = tooltipView ? "true" : "false";
    if (update.view.contentDOM.getAttribute("aria-expanded") !== expanded) {
      update.view.contentDOM.setAttribute("aria-expanded", expanded);
    }
    if (!tooltipView) return;
    // The "No matches" row is a statement, not a candidate. CodeMirror
    // selects the first option on open regardless, so clear it: -1 is its
    // own "nothing selected", which also drops aria-activedescendant.
    if (isNoMatch(currentCompletions(update.state)) && (selectedCompletionIndex(update.state) ?? -1) >= 0) {
      update.view.dispatch({ effects: setSelectedCompletion(-1) });
    }
    const { dom } = tooltipView;
    if (!patched.has(tooltipView)) {
      patched.add(tooltipView);
      if (anchorCoords) tooltipView.getCoords = anchorCoords(update.view);
      dom.style.setProperty("--bbox-completion-rows", String(maxRows));
      dom.dataset.anchor = anchor;
    }
    renderFooter(update.view, dom);
  });

  // The listener below only runs on an update, so a freshly mounted, closed
  // editor would carry no expanded state at all until its first transaction.
  const ariaOnMount = ViewPlugin.define((view) => {
    view.contentDOM.setAttribute("aria-expanded", "false");
    // Reconfiguring the field onto a grammar WITHOUT this menu tears the
    // plugin down while the attribute is still on the element — leaving a
    // combobox that claims an expanded popup nothing can close.
    return { destroy: () => view.contentDOM.removeAttribute("aria-expanded") };
  });

  return [
    widenField,
    ariaOnMount,
    // Ahead of `autocompletion()` so it outranks anything at the same
    // precedence; CodeMirror's own completion keymap is switched off below
    // (`defaultKeymap: false`) so no key has two owners.
    menuKeymap,
    decorateTooltip,
    autocompletion({
      override: [source],
      defaultKeymap: false,
      icons: false,
      // `bbox-code-completion` is the class codeField.css's z-index floor
      // targets, so the menu stacks exactly like CodeField's own popup.
      tooltipClass: () => "bbox-code-completion bbox-completion-menu",
      optionClass: (completion) => {
        const row = rows.get(completion);
        if (row === "no-match") return NO_MATCH_CLASS;
        return row?.deprecated ? "bbox-completion-menu__deprecated" : "";
      },
      addToOptions: badge
        ? [
            {
              position: 20,
              render: (completion) => {
                const row = rows.get(completion);
                if (row === "no-match") return null;
                // The cell renders even with no pill in it, so every label
                // starts at the same x — a ragged label column is what makes
                // a kind pill harder to scan than no pill at all.
                const cell = document.createElement("span");
                cell.className = "bbox-completion-menu__badge-cell";
                const text = row?.type ? badge(row.type) : null;
                if (text) {
                  const pill = cell.appendChild(document.createElement("span"));
                  pill.className = "bbox-completion-menu__badge";
                  pill.dataset.kind = row!.type;
                  pill.textContent = text;
                }
                return cell;
              },
            },
          ]
        : [],
    }),
  ];
}

/**
 * The live-commit contract `CodeField` follows.
 *
 * WHY a gesture object instead of "call `onWrite` on change, `onEditEnd` on
 * blur": a text field's edit is a *gesture* with three boundaries — it
 * begins, it produces values, and it ends exactly once — and how the field
 * was left (blur, Enter, Escape, the host unmounting the panel) only
 * decides *when* the gesture ends, never *whether* the value survives. The
 * browser will not tell you about the last one: no `blur` fires for a
 * focused element removed from the DOM, so a naive commit-on-blur field
 * silently drops whatever was typed the instant its panel unmounts. This
 * class is driven from the React lifecycle instead (`CodeField`'s unmount
 * effect calls `commit()`), where that boundary is observable.
 *
 * Two write policies, both loss-free:
 *
 * - `live` — every keystroke writes straight into the caller's store, so
 *   the store is the only copy of the text and there is nothing left to
 *   lose. `CodeField` uses this exclusively (see WHY below).
 * - `exit` — the value is buffered and written once, at the end boundary,
 *   for a write that is genuinely expensive. Still loss-free, because
 *   unmount is itself an end boundary.
 *
 * `begin` fires lazily, on the first keystroke that actually changes the
 * value, so a field that was merely focused leaves no trace in undo
 * history. `end` is the commit boundary a caller can hang a semantic
 * "rename" or a debounced round trip off, without the live write ever
 * having to wait for it.
 */

export type FieldCommitMode = "live" | "exit";

export interface FieldGestureHooks {
  /** Write the value. Per keystroke in `live`, once at the end in `exit`. */
  write(value: string): void;
  /**
   * Open one undoable step. Called lazily — on the first keystroke that
   * really changes the value — so merely focusing a field leaves no trace.
   */
  begin?(): void;
  /** The commit boundary. Fires exactly once per gesture, whatever ended it. */
  end?(value: string, startValue: string): void;
}

export class FieldGesture {
  mode: FieldCommitMode;

  private readonly hooks: FieldGestureHooks;
  private editing = false;
  private began = false;
  private start = "";
  private current = "";

  constructor(hooks: FieldGestureHooks, mode: FieldCommitMode = "live") {
    this.hooks = hooks;
    this.mode = mode;
  }

  get isEditing(): boolean {
    return this.editing;
  }

  get startValue(): string {
    return this.start;
  }

  get value(): string {
    return this.current;
  }

  /** Enter the field. Idempotent: re-entering keeps the original pre-edit value. */
  focus(value: string): void {
    if (this.editing) return;
    this.editing = true;
    this.began = false;
    this.start = value;
    this.current = value;
  }

  /** One keystroke, paste, or IME commit. */
  change(value: string): void {
    if (!this.editing) this.focus(this.current);
    if (value === this.current) return;
    this.current = value;
    if (this.mode !== "live") return;
    this.ensureBegun();
    this.hooks.write(value);
  }

  /**
   * End the gesture and keep the value. Every exit route calls this — blur,
   * Enter, Escape, and the unmount cleanup — so it must stay idempotent.
   */
  commit(): void {
    if (!this.editing) return;
    if (this.mode === "exit" && this.current !== this.start) {
      this.ensureBegun();
      this.hooks.write(this.current);
    }
    const value = this.current;
    const start = this.start;
    this.editing = false;
    this.began = false;
    this.hooks.end?.(value, start);
  }

  private ensureBegun(): void {
    if (this.began) return;
    this.began = true;
    this.hooks.begin?.();
  }
}

/**
 * packages/bbox-ui/src/flex.fields.ts
 *
 * `Flex`'s controllable props as data — every `id` is a real `FlexProps`
 * key, every default mirrors `./flex.tsx`; `test/flex.fields.test.ts`
 * pins the two together. `FLEX_PRESETS` is empty: Flex paints nothing, so
 * there is no semantic ladder for a preset to govern.
 */
import type { FieldOption, FieldSpec, PresetSpec } from "./schema";

import { FLEX_ALIGN_VALUES, FLEX_DIRECTIONS, FLEX_JUSTIFY_VALUES, FLEX_SIZES, type FlexAlign, type FlexDirection, type FlexJustify, type FlexSize } from "./flex";

const DIRECTION_LABELS: Record<FlexDirection, string> = { row: "Row", column: "Column" };
const JUSTIFY_LABELS: Record<FlexJustify, string> = {
  start: "Start",
  center: "Center",
  end: "End",
  between: "Between",
  around: "Around",
  evenly: "Evenly",
};
const ALIGN_LABELS: Record<FlexAlign, string> = { start: "Start", center: "Center", end: "End", stretch: "Stretch" };

const opts = <T extends string>(values: readonly T[], labels: Record<T, string>): FieldOption[] =>
  values.map((value) => ({ value, label: labels[value] }));

const SIZE_LABELS: Record<FlexSize, string> = { sm: "Small", md: "Medium", lg: "Large", xl: "Extra Large" };

export const FLEX_FIELDS: FieldSpec[] = [
  {
    id: "size",
    label: "Size",
    kind: "segments",
    defaultValue: "md",
    options: opts(FLEX_SIZES, SIZE_LABELS),
    cascades: true,
    hint: "Relayed to the members; the Flex itself paints nothing at any size.",
  },
  { id: "direction", label: "Direction", kind: "segments", defaultValue: "row", options: opts(FLEX_DIRECTIONS, DIRECTION_LABELS) },
  {
    id: "justify",
    label: "Justify",
    kind: "segments",
    defaultValue: "start",
    options: opts(FLEX_JUSTIFY_VALUES, JUSTIFY_LABELS),
    hint: "Along the direction. Between/Around/Evenly are CSS's three spacing schemes — the dnd-kit lab's edge-to-edge, around, and including-edge.",
  },
  { id: "align", label: "Align", kind: "segments", defaultValue: "center", options: opts(FLEX_ALIGN_VALUES, ALIGN_LABELS), hint: "Across the direction." },
  { id: "gap", label: "Gap", kind: "number", defaultValue: 8, min: 0, max: 48, unit: "px", group: "spacing" },
  { id: "padding", label: "Padding", kind: "number", defaultValue: 0, min: 0, max: 48, unit: "px", group: "spacing" },
  { id: "wrap", label: "Wrap", kind: "toggle", defaultValue: false },
];

export const FLEX_PRESETS: PresetSpec[] = [];

import type { ComponentProps, CSSProperties } from "react";

import { cn } from "./lib/utils";

/**
 * packages/bbox-ui/src/flex.tsx
 *
 * Flex = the thing that fills a slot. An ordered run of members laid out
 * by CSS flexbox in one direction, with the four knobs a person actually
 * reaches for (direction, justify, align, gap) and a padding. Paints
 * nothing of its own. It replaced RowContainer on 2026-09-11 (Zach: "flex
 * can do both column or row") — a RowContainer was a Flex with
 * `direction: "row"`.
 *
 * WHY the name is Flex and not "FlexBox" or "Slot" (Zach, 2026-09-11:
 * "instead of calling these slots, maybe we should just call them flex
 * boxes because that's what they really are"): the two words name two
 * different things. A SLOT is a named hole on a parent — Block's
 * `header.left` — the API role; it exists whether or not anything fills
 * it. A FLEX is the component that fills a slot and lays members out; it
 * can also be used on its own, nested in another Flex, or as a row in a
 * Block's body. CSS calls the concept a flex container, and every
 * library Zach copies calls the component `Flex` (Radix Themes, Chakra,
 * Mantine) — so the component is `Flex` and the holes stay `slots`.
 */

export const FLEX_DIRECTIONS = ["row", "column"] as const;
export type FlexDirection = (typeof FLEX_DIRECTIONS)[number];

export const FLEX_JUSTIFY_VALUES = ["start", "center", "end", "between", "around", "evenly"] as const;
export type FlexJustify = (typeof FLEX_JUSTIFY_VALUES)[number];

export const FLEX_ALIGN_VALUES = ["start", "center", "end", "stretch"] as const;
export type FlexAlign = (typeof FLEX_ALIGN_VALUES)[number];

const JUSTIFY_CONTENT: Record<FlexJustify, CSSProperties["justifyContent"]> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  between: "space-between",
  around: "space-around",
  evenly: "space-evenly",
};

const ALIGN_ITEMS: Record<FlexAlign, CSSProperties["alignItems"]> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  stretch: "stretch",
};

export const FLEX_SIZES = ["sm", "md", "lg", "xl"] as const;
export type FlexSize = (typeof FLEX_SIZES)[number];

export interface FlexProps extends ComponentProps<"div"> {
  /**
   * The size rung this Flex relays to its members. It paints nothing of
   * its own (D2, 2026-09-11): a Flex exists to lay members out, and `size`
   * is here so a row can override the bar above it and hand the new value
   * down. Read by the page's inheritance walk, echoed as `data-size`.
   */
  size?: FlexSize;
  direction?: FlexDirection;
  justify?: FlexJustify;
  align?: FlexAlign;
  /** px between members. */
  gap?: number;
  /** px inset from the Flex's own edges. */
  padding?: number;
  /** Members wrap onto the next line/column instead of overflowing. */
  wrap?: boolean;
}

/**
 * Lays `children` (structural — composed by hand or by a host's member
 * list, never a `FieldSpec` row) along `direction`. Width fills the
 * parent; height hugs contents.
 */
export function Flex({
  size = "md",
  direction = "row",
  justify = "start",
  align = "center",
  gap = 8,
  padding = 0,
  wrap = false,
  className,
  style,
  children,
  ...props
}: FlexProps) {
  return (
    <div
      data-slot="flex"
      data-size={size}
      data-direction={direction}
      data-justify={justify}
      data-align={align}
      className={cn("flex w-full min-w-0", className)}
      style={{
        flexDirection: direction,
        justifyContent: JUSTIFY_CONTENT[justify],
        alignItems: ALIGN_ITEMS[align],
        flexWrap: wrap ? "wrap" : "nowrap",
        gap,
        padding,
        ...style,
      }}
      {...props}
    >
      {children}
    </div>
  );
}

