 * `bbox-ui-v2.systemsketch` — not invented.
 */

/* ------------------------------------------------------------------ */
/* Text size rungs                                                     */
/* ------------------------------------------------------------------ */

/**
 * The three text rungs, named on the board as
 * `Medium (h3)` / `Large (h2)` / `Extra Large (h1)`.
 */
export const TEXT_SIZES = {
  md: 24,
  lg: 36,
  xl: 44,
} as const;

export type TextSize = keyof typeof TEXT_SIZES;

export const TEXT_SIZE_NAMES: Record<TextSize, string> = {
  md: "Medium (h3)",
  lg: "Large (h2)",
  xl: "Extra Large (h1)",
};

/** Small metadata text (description, type, chip) — the board's `s` rung. */
export const META_FONT_PX = 18;

/**
 * Glyph (icon) size is derived from the title size, never set independently.
 * WHY: board rule, written by Zach — "The Icon and Title always go next to
 * each other. The icon should resize with the title text size." 0.9 × 44 ≈ 40
 * reproduces the face he already approved; the rungs become 44→40, 36→32, 24→22.
 */
export const ICON_RATIO = 0.9;

export function glyphPx(size: TextSize): number {
  return Math.round(TEXT_SIZES[size] * ICON_RATIO);
}

/* ------------------------------------------------------------------ */
/* Block — Simple View                                                 */
/* ------------------------------------------------------------------ */

/** Simple View container, measured: 384 × 258, solid stroke, no fill. */
export const SIMPLE_BLOCK = {
  width: 384,
  height: 258,
} as const;

/** Tag chip (e.g. `Draft 1`): oval, measured 102 × 39. */
export const CHIP = {
  minWidth: 102,
  height: 39,
} as const;

/**
 * Stroke width of the Block container border (`border-2` on `Block`). CSS
 * absolute positioning resolves against a *padding* box, so this stroke
 * shifts a host's coordinate origin; placement math elsewhere compensates
 * so no adapter has to know.
 *
 * INTEGRATION (T1-SPEC.md §0): the port dot's own ring width used to live
 * here as `PORT_RING_PX`, alongside this constant — it is now
 * `PORT_SURFACE_RING_PX`/`PORT_STATE_RING_PX` in the rebuilt
 * `port.layout.ts`, deleted from here with the rest of the old Port
 * section. `BLOCK_BORDER_PX` itself stays — Block's own fact, not Port's.
 */
export const BLOCK_BORDER_PX = 2;

/* ------------------------------------------------------------------ */
/* Header + chip — the chip reserves a region, it is not just aligned  */
/* ------------------------------------------------------------------ */

/** Horizontal padding inside the Block container (`px-4` on `Block`). */
export const BLOCK_PADDING_X = 16;

/**
 * Chip inset from the container's right edge, measured: container right
 * 4915, chip oval right 4887 → 28.
 */
export const CHIP_INSET_RIGHT = 28;

/**
 * Clear gap between the title's right edge and the chip's left edge,
 * measured: chip left 4785, title right 4775 → 10.
 */
export const CHIP_TITLE_GAP = 10;

/**
 * Width available to the header's content (glyph + title).
 *
 * Without a chip: the normal padded width — container border and `px-4`
 * padding off both sides.
 *
 * With a chip: `containerWidth − CHIP_INSET_RIGHT − CHIP.minWidth −
 * CHIP_TITLE_GAP`. WHY: on the board the chip is not merely right-aligned —
 * it RESERVES its region, and the title's room ends before it. The earlier
 * out-of-flow chip kept a centred title from shifting when a tag appeared,
 * but traded a shift for a collision (the chip painted over the title's
 * last letters), and a collision is worse. A title that no longer fits
 * truncates with a visible ellipsis, never a silent clip.
 */
export function headerContentWidth(
  containerWidth: number = SIMPLE_BLOCK.width,
  hasChip: boolean = false,
): number {
  if (hasChip) {
    return containerWidth - CHIP_INSET_RIGHT - CHIP.minWidth - CHIP_TITLE_GAP;
  }
  return containerWidth - 2 * (BLOCK_BORDER_PX + BLOCK_PADDING_X);
}

/**
 * CSS `right` for the chip, absolutely positioned inside the header. The
 * header spans the Block's *padding* box (already `BLOCK_BORDER_PX +
 * BLOCK_PADDING_X` inside the container edge), so the container-edge inset
 * is re-expressed in that frame here, once.
 */
export const CHIP_RIGHT_IN_HEADER_PX =
  CHIP_INSET_RIGHT - BLOCK_BORDER_PX - BLOCK_PADDING_X;

/**
 * CSS `padding-right` the header takes on while it hosts a chip: the chip's
 * span plus both clearances, in the header's own frame. This is what makes
 * the chip a *reservation* — the flexed title can never extend into it, so
 * the title's box and the chip's box cannot intersect, whatever the title
 * says. For any container width, the header content's right limit under
 * this padding lands exactly `headerContentWidth(width, true)` from the
 * container's left edge.
 */
export const HEADER_CHIP_RESERVED_PX =
  CHIP_RIGHT_IN_HEADER_PX + CHIP.minWidth + CHIP_TITLE_GAP;

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * packages/bbox-ui/src/pill.fields.ts
 *
 * `Pill`'s controllable props as data. `Pill` is the flagship cascade
 * example (docs/T1-SPEC.md §4.3): its look is driven primarily by `state`
 * (via the shared `APPEARANCE_FIELDS` bundle) with a closed set of literal
 * paint fields — `PILL_PAINT_FIELDS` — as the escape hatch a preset governs
 * and an instance may individually override (see `./pill.tsx` and
 * `./pill.presets.ts`).
 *
 * WHY the literal 13-hue tldraw-style swatch grid the pre-ruling Pill
 * design proposed is rejected: it is exactly the raw-colour-first surface
 * Zach's ruling argues against ("there is like a good visual color grammar
 * that takes thinking to get right and we should ship good defaults").
 * Pill's paint fields instead select from bbox-ui's own curated TOKEN
 * NAMES, not an arbitrary hex.
 */
import type { FieldOption, FieldSpec } from "./schema";
import { APPEARANCE_FIELDS } from "./appearance.fields";

/** The token names ANY paint field in this spec may select from — the
 * curated vocabulary, not an arbitrary colour. `"transparent"` is a real,
 * distinct 9th option (a hollow line/fill), not the absence of a value. */
export const PAINT_TOKENS = [
  "foreground",
  "muted-foreground",
  "primary",
  "bbox-received",
  "bbox-warning",
  "bbox-success",
  "bbox-danger",
  "bbox-accent",
  "transparent",
] as const;
export type PaintToken = (typeof PAINT_TOKENS)[number];

const PAINT_TOKEN_OPTIONS: FieldOption[] = PAINT_TOKENS.map((t) => ({ value: t, label: t }));

/**
 * T1-SPEC.md §4.3 pins these three as inline literal unions with no
 * exported array (`"solid" | "dashed" | "dotted" | "none"` etc., built
 * inline as `[...].map(...)`). Pulled out as real exported `as const`
 * arrays here — same values, same order, same behaviour — purely so
 * `pill.fields.test.ts` can pin `FieldSpec.options` against a real runtime
 * union (the T0/Port convention: `PORT_STATES`, `PORT_TEXT_LAYOUTS`, …)
 * instead of a second hand-typed literal that could silently drift from
 * the first. Reported as a lane-scoped deviation, not a spec disagreement.
 */
export const PILL_LINE_STYLES = ["solid", "dashed", "dotted", "none"] as const;
export type PillLineStyle = (typeof PILL_LINE_STYLES)[number];

export const PILL_FILL_STYLES = ["none", "semi", "solid"] as const;
export type PillFillStyle = (typeof PILL_FILL_STYLES)[number];

export const PILL_LINE_THICKNESSES = ["thin", "med", "thick"] as const;
export type PillLineThickness = (typeof PILL_LINE_THICKNESSES)[number];

/**
 * Pill's own font-size rung — a small CHIP scale (11-16px), deliberately
 * NOT the 18-44px board scale `Port`/`Glyph`/`TextBox` each carry their
 * own copy of (docs/T1-SPEC.md §0's "three components each get their own
 * rung, in their own file" rule, extended to a fourth here). `pill.tsx`
 * imports this directly (never the reverse) — same one-way edge as its
 * existing `PILL_PAINT_FIELDS`/`PillFillStyle` imports — so there is no
 * circular dependency between the schema file and the component file.
 */
export const PILL_SIZES = { sm: 11, md: 12, lg: 14, xl: 16 } as const;
export type PillSize = keyof typeof PILL_SIZES;
export const PILL_SIZE_LABELS: Record<PillSize, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
  xl: "Extra Large",
};

/** Pill's own literal escape-hatch fields — governed by PILL_PRESETS in
 * the normal case, individually overridable (see the §1.4 worked example,
 * `pill.tsx`'s cascade call, and `pill.fields.test.ts`). */
export const PILL_PAINT_FIELDS: FieldSpec[] = [
  {
    id: "lineStyle",
    label: "Line Style",
    kind: "segments",
    defaultValue: "solid",
    options: PILL_LINE_STYLES.map((v) => ({ value: v, label: v })),
  },
  {
    id: "lineColor",
    label: "Line Color",
    kind: "segments",
    defaultValue: "foreground",
    options: PAINT_TOKEN_OPTIONS,
  },
  {
    id: "lineThickness",
    label: "Line Thickness",
    kind: "segments",
    defaultValue: "med",
    options: PILL_LINE_THICKNESSES.map((v) => ({ value: v, label: v })),
  },
  {
    id: "lineOpacity",
    label: "Line Opacity",
    kind: "number",
    defaultValue: 1,
    min: 0,
    max: 1,
    step: 0.1,
  },
  {
    id: "fillStyle",
    label: "Fill Style",
    kind: "segments",
    defaultValue: "none",
    options: PILL_FILL_STYLES.map((v) => ({ value: v, label: v })),
  },
  {
    id: "fillColor",
    label: "Fill Color",
    kind: "segments",
    defaultValue: "transparent",
    options: PAINT_TOKEN_OPTIONS,
  },
  {
    id: "fillOpacity",
    label: "Fill Opacity",
    kind: "number",
    defaultValue: 1,
    min: 0,
    max: 1,
    step: 0.1,
  },
];

/** No preset governs this — unlike Port's `size`, Pill's is a plain,
 * always-editable field with a real component default (`pill.tsx`'s own
 * `size = "md"`), still marked `cascades` so a header can hand its rung
 * down the same way it hands one to a Port. */
export const PILL_SIZE_FIELD: FieldSpec = {
  id: "size",
  label: "Size",
  kind: "segments",
  defaultValue: "md",
  options: (Object.keys(PILL_SIZES) as PillSize[]).map((size) => ({
    value: size,
    label: PILL_SIZE_LABELS[size],
  })),
  cascades: true,
};

export const PILL_CHILDREN_FIELD: FieldSpec = {
  id: "children",
  label: "Label",
  kind: "text",
  defaultValue: "Pill",
  hint: "Omitting it renders the bare rounded outline with no label.",
};

export const PILL_FIELDS: FieldSpec[] = [
  ...APPEARANCE_FIELDS,
  ...PILL_PAINT_FIELDS,
  PILL_SIZE_FIELD,
  PILL_CHILDREN_FIELD,
];

/**
 * packages/bbox-ui/src/pill.presets.ts
 *
 * `PILL_PRESETS` — one per `AppearanceState`, each a `state`-selected,
 * mutually exclusive alternative governing Pill's four line/fill paint
 * fields (never `lineThickness`/`lineOpacity`/`fillOpacity` — those stay
 * freely editable regardless of state, a deliberate, narrower governed
 * set; see docs/T1-SPEC.md §4.3).
 *
 * NOTE (deviation, reported loudly per the T1 lane brief): `valueSet`'s
 * `fillColor` below is `"muted-foreground"`, copied verbatim from
 * T1-SPEC.md's own pinned `pill.presets.ts` code block (§4.3) — but
 * T1-SPEC.md §2.2's `STATE_TOKENS.valueSet` (appearance.ts, already
 * shipped by Lane A) instead pairs a `"muted-foreground"` ring with a
 * `"muted"` fill, and §3's colour-grammar table repeats that "muted" fill
 * reading. This is a disagreement inside the spec itself (verbatim code
 * vs. its own worked table), not a spec-vs-real-component conflict this
 * lane has standing to resolve — kept exactly as pinned; see the lane
 * report for the flag.
 */
import type { PresetSpec } from "./schema";
import { APPEARANCE_STATE_LABELS, APPEARANCE_STATES, type AppearanceState } from "./appearance";

const GOVERNS = ["lineStyle", "lineColor", "fillStyle", "fillColor"];

// WHY `AppearanceState` and not `string`: a loose index signature makes this
// table non-total, so adding a seventh state satisfies every other Record in
// the codebase, typechecks clean, and then throws at runtime — the preset is
// built with `values: undefined` and both `Pill` and the product inspector
// die reading `lineStyle` off it. That is a harder failure than the silent
// fallback the same fix removed from `block.tsx`, in the one file where the
// cascade actually has presets.
const PRESET_PAINT: Record<
  AppearanceState,
  { lineStyle: string; lineColor: string; fillStyle: string; fillColor: string }
> = {
  empty: { lineStyle: "solid", lineColor: "foreground", fillStyle: "none", fillColor: "transparent" },
  valueSet: {
    lineStyle: "solid",
    lineColor: "muted-foreground",
    fillStyle: "semi",
    fillColor: "muted-foreground",
  },
  wired: { lineStyle: "solid", lineColor: "primary", fillStyle: "solid", fillColor: "primary" },
  received: {
    lineStyle: "solid",
    lineColor: "bbox-received",
    fillStyle: "solid",
    fillColor: "bbox-received",
  },
};

export const PILL_PRESETS: PresetSpec[] = APPEARANCE_STATES.map((state) => ({
  id: state,
  label: APPEARANCE_STATE_LABELS[state],
  selector: "state",
  governs: GOVERNS,
  values: PRESET_PAINT[state],
}));

import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { governedFieldIds, resolveField } from "./schema";

import { cn } from "./lib/utils";
import { SketchOutline } from "./sketchOutline";
import { toneOverride, type AppearanceState, type Lens, type Tone, paintVar } from "./appearance";
import {
  PILL_PAINT_FIELDS,
  PILL_SIZES,
  type PaintToken,
  type PillFillStyle,
  type PillLineStyle,
  type PillLineThickness,
  type PillSize,
} from "./pill.fields";
import { PILL_PRESETS } from "./pill.presets";

const PAINT_FIELD_BY_ID = Object.fromEntries(PILL_PAINT_FIELDS.map((f) => [f.id, f])) as Record<
  "lineStyle" | "lineColor" | "lineThickness" | "lineOpacity" | "fillStyle" | "fillColor" | "fillOpacity",
  (typeof PILL_PAINT_FIELDS)[number]
>;

/** The four fields a preset can ever reach — always exactly
 * `["lineStyle", "lineColor", "fillStyle", "fillColor"]` (PILL_PRESETS'
 * own `governs`), computed once so `pill.fields.test.ts` reads it off the
 * same real data instead of a re-typed literal. */
const GOVERNED_PAINT_FIELD_IDS = governedFieldIds(PILL_PRESETS);

/**
 * DEVIATION from appearance.ts's own illustrative one-liner
 * (`toneOverride(tone, governedFieldIds)`, T1-SPEC.md §2.2), reported per
 * the lane brief: that pattern is correct for `Port`, whose only "governed"
 * concepts are two COLOUR slots (ring/fill) computed by hand. Pill's
 * `governs` set mixes two colour fields (`lineColor`/`fillColor`) with two
 * STYLE-ENUM fields (`lineStyle`/`fillStyle`, whose legal values are
 * `"solid"|"dashed"|…` and `"none"|"semi"|"solid"`, never a token name).
 * Feeding all four through `toneOverride` stuffs a token string like
 * `"bbox-danger"` into `fillStyle`, which resolves to nothing in
 * `FILL_STYLE_ALPHA` (a real `NaN`-producing bug, caught by
 * `pill.fields.test.ts`). A tone therefore overrides only the two colour
 * fields; the current state's own `lineStyle`/`fillStyle` — solid outline
 * only, or outline-plus-fill — still decides the SHAPE of the paint, and
 * the tone decides its hue.
 */
const PILL_TONE_COLOR_FIELD_IDS = ["lineColor", "fillColor"];

/**
 * The subject a Pill's paint is resolved against — raw props with `tone`
 * folded in as an override.
 *
 * WHY this is EXPORTED rather than inlined in the component: `tone` is sugar
 * that writes the override layer (appearance.ts's own contract), never a
 * second preset family, since two families claiming the same paint fields is
 * what `assertDisjointPresets` forbids. Anything that wants to know what a
 * Pill will paint has to apply the same transform, and the product inspector
 * did not: it resolved raw props, so with any tone set its trace reported the
 * state preset winning with `primary` while the pill painted the tone's
 * colour, and the Line Color control sat live but inert, claiming an override
 * that was not on screen. One exported function is what stops the panel and
 * the pixels drifting apart again.
 */
export function pillResolutionSubject(
  props: Record<string, unknown>,
): Record<string, unknown> {
  const tone = (props.tone as Tone | undefined) ?? "neutral";
  return { ...props, ...toneOverride(tone, PILL_TONE_COLOR_FIELD_IDS) };
}

/** Border width per rung — `med` (2px) matches the existing `border-2`
 * convention `Block`'s container and `Port`'s ring already use, so a
 * `state:"empty"` Pill reads as the same weight of line as everything
 * else on the board, not a fourth, unrelated stroke width. */
const LINE_THICKNESS_PX: Record<PillLineThickness, number> = {
  thin: 1,
  med: 2,
  thick: 3,
};

/** Padding per `size` rung. `md` is `"2px 12px"` — the exact pixel
 * equivalent of the pre-`size` shell's hardcoded `px-3 py-0.5` Tailwind
 * classes (`0.75rem`/`0.125rem` at the default 16px root), so shipping
 * `size` changes nothing for a Pill that never sets it. */
const PILL_SIZE_PADDING: Record<PillSize, string> = {
  sm: "0 8px",
  md: "2px 12px",
  lg: "2px 14px",
  xl: "4px 16px",
};

// WHY a total Record and not passing `lineStyleResolved` straight through
// to CSS `borderStyle`: it typechecked and painted correctly only because
// every current `PillLineStyle` member happens to spell a real CSS
// border-style keyword. React's own `CSSProperties["borderStyle"]` type
// accepts an arbitrary string, so a future member that ISN'T valid CSS
// (or that means something bbox-ui-specific, the way a future line style
// might) would still typecheck, ship, and silently paint no border at
// all. A `Record` over the real union forces every member to state its
// real CSS value at the definition site.
const BORDER_STYLE_CSS: Record<PillLineStyle, NonNullable<CSSProperties["borderStyle"]>> = {
  solid: "solid",
  dashed: "dashed",
  dotted: "dotted",
  none: "none",
};

/**
 * `fillStyle`'s baked-in coverage before the freely-editable `fillOpacity`
 * further scales it — WHY two separate knobs: `fillStyle` is the governed,
 * semantic choice ("does this carry a value" — §3's colour grammar), while
 * `fillOpacity` is the ungoverned escape hatch nothing ever takes away.
 * Collapsing them into one field would let a preset silently fight a
 * numeric override instead of the two composing cleanly.
 */
const FILL_STYLE_ALPHA: Record<PillFillStyle, number> = { none: 0, semi: 0.35, solid: 1 };

// WHY a total Record and not the `var(--${token})` template it replaces:
// the template typechecked for any `PaintToken` and was byte-correct only
// because every existing token name happens to equal its CSS custom
// property's name. A future token whose CSS variable is spelled
// differently (or that isn't a `var()` reference at all, the way
// `"transparent"` already isn't) would still typecheck and silently paint
// nothing — same class of defect as `PillLineStyle` below. A `Record`
// over the real union makes a new member a compile error until someone
// states what it resolves to.
export const PAINT_TOKEN_VALUE: Record<PaintToken, string> = {
  foreground: "var(--foreground)",
  "muted-foreground": "var(--muted-foreground)",
  primary: paintVar("primary"),
  "bbox-received": "var(--bbox-received)",
  "bbox-warning": "var(--bbox-warning)",
  "bbox-success": "var(--bbox-success)",
  "bbox-danger": "var(--bbox-danger)",
  "bbox-accent": "var(--bbox-accent)",
  transparent: "transparent",
};

/** A resolved `PaintToken` → a real CSS colour, honouring `alpha` (0-1)
 * via `color-mix` rather than the element's own `opacity` (which would
 * also fade the label text and border together). `"transparent"` is a
 * real token (§4.3), never treated as "no value". Exported so `trace.tsx`
 * can reuse the SAME token→CSS mapping rather than a second copy that
 * could silently drift from this one. */
export function paintColor(token: PaintToken, alpha: number): string {
  const value = PAINT_TOKEN_VALUE[token];
  if (value === "transparent" || alpha <= 0) return "transparent";
  return alpha >= 1 ? value : `color-mix(in oklch, ${value} ${Math.round(alpha * 100)}%, transparent)`;
}

export interface PillProps extends Omit<ComponentProps<"span">, "children"> {
  state?: AppearanceState;
  tone?: Tone;
  lens?: Lens;
  lensBefore?: string;
  lineStyle?: PillLineStyle;
  lineColor?: PaintToken;
  lineThickness?: PillLineThickness;
  lineOpacity?: number;
  fillStyle?: PillFillStyle;
  fillColor?: PaintToken;
  fillOpacity?: number;
  /** The chip's own font-size/padding rung (`PILL_SIZES`) — ungoverned by
   * any preset, unlike `Port`'s `size`, but still `cascades` so a header
   * can hand its rung down the same way. */
  size?: PillSize;
  children?: ReactNode;
}

/**
 * Pill = a rounded-outline text slot whose look is driven primarily by
 * `state` (the shared `APPEARANCE_FIELDS` bundle), with `lineStyle` /
 * `lineColor` / `fillStyle` / `fillColor` as a closed, preset-governed
 * escape hatch (docs/T1-SPEC.md §4.3).
 *
 * WHY those four are destructured WITHOUT a JS default, unlike everything
 * else here: an explicit value is exactly what makes a subject's OVERRIDE
 * candidate present (`resolve.ts`'s `resolveField`). Giving them a
 * `= "..."` default would make every Pill's raw props carry a value on
 * these fields, so the cascade would report `winner: "override"` even when
 * nobody reached past the preset — the §1.4 worked example (a Pill that
 * stores `{state:"wired"}` and nothing else) would be impossible to render
 * correctly. `lineThickness` / `lineOpacity` / `fillOpacity` DO take real
 * JS defaults: no preset ever governs them (`PILL_PRESETS`'s own `governs`
 * list omits them), so their cascade default and component default are
 * the same fact, and a plain destructured default is honest.
 *
 * WHY this render function calls `resolveField` (the schema's cascade)
 * instead of a hand-written lookup like `Port`'s `portDotStyle`: Pill has
 * real presets to resolve through, so the pixels it paints must be
 * produced by the SAME computation the product inspector's trace panel
 * reads — otherwise the trace would be a second, informal description of
 * paint this render never actually did (`resolve.ts`'s own doc comment).
 */
export function Pill({
  state = "empty",
  tone = "neutral",
  lens = "normal",
  // `lensBefore` has no visual mapping on Pill yet (no donor evidence for a
  // diff-lens rendering here) — destructured only so it never leaks onto
  // the DOM span as an unrecognized attribute.
  lensBefore: _lensBefore = "",
  lineStyle,
  lineColor,
  lineThickness = "med",
  lineOpacity = 1,
  fillStyle,
  fillColor,
  fillOpacity = 1,
  size = "md",
  className,
  style,
  children,
  ...props
}: PillProps) {
  const subject = pillResolutionSubject({ state, tone, lineStyle, lineColor, fillStyle, fillColor });

  const lineStyleResolved = resolveField(PAINT_FIELD_BY_ID.lineStyle, subject, PILL_PRESETS)
    .resolved as PillLineStyle;
  const lineColorResolved = resolveField(PAINT_FIELD_BY_ID.lineColor, subject, PILL_PRESETS)
    .resolved as PaintToken;
  const fillStyleResolved = resolveField(PAINT_FIELD_BY_ID.fillStyle, subject, PILL_PRESETS)
    .resolved as PillFillStyle;
  const fillColorResolved = resolveField(PAINT_FIELD_BY_ID.fillColor, subject, PILL_PRESETS)
    .resolved as PaintToken;

  const hollow = lineStyleResolved === "none";

  return (
    <span
      data-slot="pill"
      data-state={state}
      data-tone={tone}
      data-lens={lens}
      data-size={size}
      data-line-style={lineStyleResolved}
      data-fill-style={fillStyleResolved}
      className={cn(
        // `rounded-[…]` rather than `rounded-full`: the capsule is the
        // DEFAULT, not a law. A Pill is a text slot with a line around it,
        // so its corner treatment is exactly what a skin is for — unlike a
        // Port dot, which stays `rounded-full` unconditionally because a
        // circle is what a Port IS (port.tsx's `portDotClassName`).
        "relative box-border inline-flex w-fit items-center justify-center whitespace-nowrap rounded-[var(--bbox-skin-radius-pill,9999px)] text-center leading-tight text-foreground",
        className,
      )}
      style={{
        borderStyle: hollow ? "none" : BORDER_STYLE_CSS[lineStyleResolved],
        borderWidth: hollow ? 0 : LINE_THICKNESS_PX[lineThickness],
        // D4 (Zach, 2026-09-17: "yes should go sketchy"). The CSS ring is
        // blanked only by the sketch skin, which is the one that supplies
        // `--bbox-skin-line-override`; every other skin leaves the token
        // undefined so the `var()` fallback IS the resolved colour and
        // nothing about this line changes.
        //
        // WHY the skin may not simply name a colour here: `lineColor` is
        // governed by the `state` preset family. A second selector claiming
        // it is precisely what `assertDisjointPresets` forbids. So the skin
        // says only "do not paint the CSS one" and the drawn outline below
        // is handed the SAME resolved colour — state keeps the hue, the
        // skin takes the shape.
        borderColor: `var(--bbox-skin-line-override, ${paintColor(lineColorResolved, lineOpacity)})`,
        background: paintColor(fillColorResolved, FILL_STYLE_ALPHA[fillStyleResolved] * fillOpacity),
        padding: PILL_SIZE_PADDING[size],
        fontSize: PILL_SIZES[size],
        ...style,
      }}
      {...props}
    >
      {!hollow && (
        <SketchOutline
          // Stretched, not measured: a Pill is sized by its own content and
          // learning its real pixels would mean a ResizeObserver. The
          // nominal box is a typical chip; see sketchOutline.tsx on the
          // (sub-pixel, invisible) cost.
          stretch
          width={120}
          height={26}
          borderWidth={LINE_THICKNESS_PX[lineThickness]}
          radius={13}
          stroke={paintColor(lineColorResolved, lineOpacity)}
          seed={`pill:${lineColorResolved}:${size}`}
        />
      )}
      {children}
    </span>
  );
}

/**
 * packages/bbox-ui/src/port.fields.ts
 *
 * `Port`'s controllable props as data — the rebuilt shape, pinned by
 * docs/T1-SPEC.md §4.7 (superseding `PORT-SPEC.md §3`'s own table where
 * the two disagree: `APPEARANCE_FIELDS` no longer carries `textSize` —
 * every text-bearing component gets its own ladder, T1-SPEC.md §2.1 —
 * and `tone` resolves via `toneOverride`, not a second preset family).
 * ONE FLAT PROPERTY SPACE (Zach's ruling): `APPEARANCE_FIELDS` is spread
 * directly into `PORT_FIELDS` rather than nested under an `appearance`
 * key. Every `id` below is a real `PortProps` key (see `./port.tsx`);
 * `readFields`/`resolveField` look subjects up by that key directly.
 * `test/port.fields.test.ts` pins every default/option against the real
 * component and layout module — never a retyped literal.
 */
import type { FieldOption, FieldSpec } from "./schema";

import { APPEARANCE_FIELDS } from "./appearance.fields";
import {
  BLOCK_SIDES,
  BLOCK_SIDE_LABELS,
  PORT_DIAMETER_LABELS,
  PORT_DIAMETERS,
  PORT_DIRECTION_LABELS,
  PORT_DIRECTIONS,
  PORT_REVEAL_LABELS,
  PORT_REVEALS,
  PORT_SIZE_RUNG_LABELS,
  PORT_SIZE_RUNGS,
  PORT_TEXT_LAYOUT_LABELS,
  PORT_TEXT_LAYOUTS,
  PORT_TEXT_SIZE_LABELS,
  PORT_TEXT_SIZES,
  SECONDARY_SLOT_LAYOUT_LABELS,
  SECONDARY_SLOT_LAYOUTS,
  SLOT_ALIGNS,
  SLOT_ORIGINS,
  SLOT_ORIGIN_LABELS,
  type PortTextSize,
} from "./port.layout";

const DIRECTION_OPTIONS: FieldOption[] = PORT_DIRECTIONS.map((direction) => ({
  value: direction,
  label: PORT_DIRECTION_LABELS[direction],
}));

const EDGE_OPTIONS: FieldOption[] = BLOCK_SIDES.map((side) => ({
