/**
 * The interaction axis's visibility policy (PORT-SPEC.md §1.3.2):
 * `"onHover"` replaces the donor's `subtle` (opacity, not colour, so it
 * has no place on the state/colour axis). Host-computed, never persisted
 * — see `port.fields.ts`'s `reveal` field.
 */
export const PORT_REVEALS = ["always", "onHover"] as const;
export type PortReveal = (typeof PORT_REVEALS)[number];
export const PORT_REVEAL_LABELS: Record<PortReveal, string> = {
  always: "Always",
  onHover: "On Hover",
};

// `PortRole`/`PortDecoration` (and `PORT_ROLES`/`PORT_ROLE_LABELS`/
// `PORT_DECORATIONS`/`PORT_DECORATION_LABELS`) REMOVED 2026-09-12, per
// Zach's ruling on the port-props proposal (D4): these are Python-specific
// annotations (a `configuration`/`control`/`error` port role, a
// `mutates`/`variadic-*` collar) that belong to whichever app has that
// domain knowledge — SystemSketch, not this generic design system — never
// to base `Port`'s own panel. Confirmed dead weight before removal: no
// host adapter (React Flow, tldraw) ever set or read either prop, and
// neither is part of any persisted shape (`git log`/recon, 2026-09-12). A
// consuming app that wants them back composes its own ring/cue as a thin
// wrapper OVER `PortDot`/`Port` (an absolutely-positioned sibling span,
// the same technique `PortDecorationRing`/`PortRoleCue` used internally)
// rather than reaching for a prop this package no longer carries.

/**
 * `PortDot`'s SECOND independently-positioned slot (the two-slot proposal,
 * 2026-09-12): generic content hugging a corner of the dot, closer in than
 * the label slot's own "Offset" positions — Zach's diagram names these
 * "Secondary Slot Placement", all four already offset variants (there is
 * no plain, flush-against-the-dot member on this axis the way the label
 * slot has `top`/`bot`/`right`/`left`). Spelled with its own vocabulary,
 * not a subset of `PortTextLayout` reused wholesale — that type's members
 * name where the LABEL flows (mirrored input/output content, wide gap);
 * this one names which CORNER of the dot's own box a small cue hugs
 * (content-agnostic, tight gap) — conflating the two would let a caller
 * pass a bare `"left"` here and land on the wrong geometry entirely.
 *
 * REPLACES `portBadgeSide`/`portCueSide` (both removed here): those
 * computed one FIXED axis opposite the label, assuming the only content
 * this slot would ever hold was the producer-count badge. Now that
 * `PortDot`'s secondary slot is genuinely generic (`PortDotProps.secondarySlot`,
 * any `ReactNode` — port.tsx), the "opposite the label" rule survives only
 * as `defaultSecondarySlotLayout`'s AUTO default below; an explicit
 * `secondarySlotLayout` always wins.
 */
export type SecondarySlotLayout = "leftOffset" | "rightOffset" | "topOffset" | "botOffset";

export const SECONDARY_SLOT_LAYOUTS: SecondarySlotLayout[] = [
  "leftOffset",
  "rightOffset",
  "topOffset",
  "botOffset",
];

export const SECONDARY_SLOT_LAYOUT_LABELS: Record<SecondarySlotLayout, string> = {
  leftOffset: "Left Offset",
  rightOffset: "Right Offset",
  topOffset: "Top Offset",
  botOffset: "Bot Offset",
};

/** How tightly the secondary slot hugs the dot's own box — deliberately
 * SMALLER than `PORT_LABEL_GAP` (the diagram's own visual distinction: a
 * "small badge/cue hugging a corner", not content sitting flush beside the
 * dot). Equal to the old hardcoded `PortCountBadge` overlay's own gap
 * (`port.tsx`, pre-two-slot) — carried forward, not re-guessed. */
export const PORT_SECONDARY_SLOT_GAP_PX = 6;

/**
 * The secondary slot's AUTO default position, given wherever the label is
 * actually flowing — the same "opposite the label" rule `portBadgeSide`
 * used to compute (2026-09-12 port-props D5's fix for "the badge sat on
 * top of a left-flowing label"), generalized from one fixed axis to the
 * secondary slot's own independent, always-offset vocabulary. Only
 * consulted when a caller omits `secondarySlotLayout` outright — an
 * explicit value always wins (`PortDot`, port.tsx).
 */
export function defaultSecondarySlotLayout(labelLayout: PortTextLayout): SecondarySlotLayout {
  switch (labelLayout) {
    case "left":
    case "leftOffset":
      return "rightOffset";
    case "right":
    case "rightOffset":
      return "leftOffset";
    case "top":
      return "botOffset";
    case "bot":
      return "topOffset";
  }
}

/* ------------------------------------------------------------------ */
/* Port anchors on a block boundary — carried forward verbatim         */
/* from layout.ts (PORT-SPEC.md §4, verified against the running app)  */
/* ------------------------------------------------------------------ */

/**
 * Stroke width of the Block container border. Re-declared here (not
 * imported) because the placement math needs it and `layout.ts` is
 * frozen for the whole of T1 — see this file's own header.
 *
 * INTEGRATION: kept file-local (not exported) — `layout.ts` also exports
 * a `BLOCK_BORDER_PX` (frozen, §0's "keeps exactly what it exports"
 * list), and re-exporting both of equal name through the barrel
 * (`packages/bbox-ui/src/index.ts`) is an ambiguous `export *` collision
 * TypeScript refuses to resolve. Nothing outside this file imports this
 * copy (verified: only `layout.ts`'s is imported elsewhere), so dropping
 * `export` here is the whole fix — nothing else needs to change.
 */
const BLOCK_BORDER_PX = 2;

/**
 * Point on the boundary of a `width × height` rectangle where a port dot
 * centers. `t` runs 0→1 along the side (top→bottom for left/right,
 * left→right for top/bottom). Hosts translate this into their own space:
 * tldraw positions absolutely from shape props, React Flow feeds it to a
 * Handle's `top`/`left` percentage.
 */
export function portAnchor(
  side: BlockSide,
  t: number,
  width: number = SIMPLE_BLOCK.width,
  height: number = SIMPLE_BLOCK.height,
): { x: number; y: number } {
  switch (side) {
    case "left":
      return { x: 0, y: t * height };
    case "right":
      return { x: width, y: t * height };
    case "top":
      return { x: t * width, y: 0 };
    case "bottom":
      return { x: t * width, y: height };
  }
}

/** Pair with `portDotPlacement` to centre the dot's box on the anchor. */
export const PORT_DOT_CENTER_TRANSFORM = "translate(-50%, -50%)";

/**
 * CSS `left`/`top` (px) that centre a port dot ON the container boundary —
 * half in, half out. For an absolutely positioned element inside `Block`,
 * whose containing box is the Block's *padding* box (inset `BLOCK_BORDER_PX`
 * from the outer boundary `portAnchor` speaks in — compensated here, once).
 * Combine with `PORT_DOT_CENTER_TRANSFORM`.
 */
export function portDotPlacement(
  side: BlockSide,
  t: number,
  width: number = SIMPLE_BLOCK.width,
  height: number = SIMPLE_BLOCK.height,
): { left: number; top: number } {
  const anchor = portAnchor(side, t, width, height);
  return { left: anchor.x - BLOCK_BORDER_PX, top: anchor.y - BLOCK_BORDER_PX };
}

/**
 * CSS offsets for a label absolutely positioned inside the dot's box.
 * Plain data — spreads into any host's style object.
 *
 * WHY it extends CSSProperties rather than standing alone: a newer @types/react
 * gave `CSSProperties` a `--${string}` index signature (CSS custom properties),
 * and TS refuses to assign a same-shaped but nominally distinct interface into
 * an indexed type — every host that passed this straight into a `style` prop
 * failed to typecheck with no change of its own.
 */
export interface PortLabelPlacement extends CSSProperties {
  left?: string;
  right?: string;
  top?: string;
  bottom?: string;
  transform: string;
}

/**
 * A port dot's box, named so it cannot be mistaken for anything else.
 *
 * WHY an object and not two positional numbers: `portLabelPlacement` once
 * took `(layout, diameterPx, boxInsetPx)` — when the resized-dot fix needed
 * the height too, reusing the third positional slot would have silently
 * re-read every existing caller's inset as a height (a 21px label move with
 * no compile error). A named box makes a stale numeric call fail to
 * typecheck instead of quietly moving labels.
 */
export interface PortDotBox {
  w: number;
  h: number;
}

/**
 * How far the label's near edge sits from the dot box's near edge, measured
 * from the box's origin-side edge along the label's own axis: the dot's span
 * ALONG THAT AXIS plus the gap — `w` for left/right labels, `h` for top/bot.
 * The label's near edge clears the RING's outer edge by the gap, not the
 * box's — so the ring's painted overhang goes in before the gap.
 */
export function portLabelOut(layout: PortTextLayout, dot: PortDotBox): number {
  const alongAxis = layout === "top" || layout === "bot" ? dot.h : dot.w;
  return alongAxis + PORT_RING_OVERHANG_PX + PORT_LABEL_GAP;
}

/**
 * Where the label sits relative to the dot: its near edge lands
 * `PORT_LABEL_GAP` px clear of the dot's outer edge — the same geometry
 * the core `Port`'s flex row produces, so a host-positioned label and a
 * flex-flowed one agree to the pixel.
 *
 * An "Offset" layout keeps that same along-axis distance and instead
 * LIFTS the label clear of the trace wire — see `SlotAlign`'s own WHY.
 * It anchors by the label's BOTTOM edge (`bottom`, no `translateY`), where
 * the plain layouts anchor by their centre, because "clear of the wire" is
 * a statement about the bottom edge and must not drift with the label's
 * own height.
 *
 * WHY `calc(50% + Npx)` and not a plain px `bottom`: 50% of the
 * positioning context is the dot's own centre line REGARDLESS of
 * `boxInsetPx` (the inset is symmetric), so the one expression is correct
 * for React Flow's inset Handle and tldraw's flush wrapper alike. A px
 * value measured from the container's bottom edge would need the inset
 * subtracted and would silently be wrong for whichever host was not the
 * one it was written against.
 *
 * `boxInsetPx` is how far the positioning context is inset from the dot's
 * border box: React Flow's `Handle` IS the bordered dot, so its padding box
 * sits `PORT_SURFACE_RING_PX + PORT_STATE_RING_PX` inside; tldraw's
 * unbordered wrapper passes 0.
 */
export function portLabelPlacement(
  layout: PortTextLayout,
  dot: PortDotBox,
  boxInsetPx: number = 0,
): PortLabelPlacement {
  const preset = TEXT_LAYOUT_AS_PLACEMENT[layout];
  return slotPlacementStyle(
    { origin: preset.origin, align: preset.align, offsetX: 0, offsetY: preset.offsetY },
    dot,
    PORT_LABEL_GAP,
    boxInsetPx,
  );
}

/* ------------------------------------------------------------------ */
/* THE UNIFIED SLOT PLACEMENT MODEL (2026-09-15)                       */
/* ------------------------------------------------------------------ */

/**
 * Which side of the dot a slot anchors to — the ORIGIN. Four values,
 * shared by BOTH slots.
 *
 * Zach, 2026-09-15: "Its just Top, bottom, right, left. thoose basically
 * set the origins. and then sepertly we can always control a x and y
 * offset. seems simpler and more general… Ok yes I think I would now
 * consider like top/left/right/etc for both secondary and primary thoose
 * are just presets!"
 *
 * WHY this replaces two separate enums: `PortTextLayout` and
 * `SecondarySlotLayout` both spell `rightOffset`, mean different things,
 * and carry different gaps (8px vs 6px) — a caller could pass one where
 * the other was wanted and land on plausible-but-wrong geometry with no
 * type error, because they are both just strings at the persistence
 * boundary. One origin type for both slots deletes that whole class.
 *
 * The named placements that used to be enum members are now PRESETS over
 * (origin, offsetX, offsetY) — "Right" is `{right, 0, 0}` and the old
 * "Right Offset" is `{right, 0, -lift}`. That also makes NEGATIVE offsets
 * fall out for free, which the enum could never express.
 */
export type SlotOrigin = "top" | "bottom" | "left" | "right";

export const SLOT_ORIGINS: SlotOrigin[] = ["top", "bottom", "left", "right"];

export const SLOT_ORIGIN_LABELS: Record<SlotOrigin, string> = {
  top: "Top",
  bottom: "Bottom",
  left: "Left",
  right: "Right",
};

/** Where a slot sits: an origin on the dot, plus a free displacement.
 *  `offsetX` is +right, `offsetY` is +DOWN (screen convention), so a
 *  label lifted clear of a trace wire carries a NEGATIVE `offsetY`. */
/**
 * WHICH PART OF THE SLOT is the reference point — the slot's own anchor,
 * on the axis the origin leaves free.
 *
 * Zach, 2026-09-15: "we need to be able to align to the slot left edge,
 * middle or right edge. and then we position that… We defintily don't
 * want to kinda be dynamically calculating the x/y offset if the slot
 * length changes right. so its important we can basically use a different
 * part of the slot as the reference edge."
 *
 * That is the fix for a real defect, not a convenience. With the anchor
 * fixed at the CENTRE, "the label's bottom edge clears the trace wire"
 * could only be expressed as an offset DERIVED from the content's own
 * height — and the component cannot know that height: measured live, a
 * label was 26.2px where the `textSize * 1.25` formula said 23, because
 * the `CodeField` inside it adds line-height 1.4, 4px padding and 1px
 * borders, and it changes again for any other slot content. Making the
 * reference edge selectable turns that guarantee into pure CSS —
 * `translate(…, -100%)` puts the bottom edge ON the line whatever the
 * height is — so the offset beside it can be a static number that never
 * needs recomputing when the slot grows.
 *
 * Named on the CROSS axis, since the origin already pins the other one: a
 * `left`/`right` origin leaves the vertical free (start = top edge,
 * end = bottom edge), a `top`/`bottom` origin the horizontal (start =
 * left edge, end = right edge).
 */
export type SlotAlign = "start" | "center" | "end";

export const SLOT_ALIGNS: SlotAlign[] = ["start", "center", "end"];

/** The CSS translate percentage that puts the chosen edge on the
 *  reference line. Height/width independent by construction — that is the
 *  entire point. */
const ALIGN_SHIFT: Record<SlotAlign, string> = {
  start: "0%",
  center: "-50%",
  end: "-100%",
};

export interface SlotPlacement {
  origin: SlotOrigin;
  /** Which part of the slot lands on the origin's line. Defaults to
   *  `center` everywhere it is omitted, which is the historic behaviour. */
  align: SlotAlign;
  offsetX: number;
  offsetY: number;
}

/**
 * THE ONE ANCHOR RULE, stated once so every path can agree on it: the
 * slot's content anchors by the edge FACING its origin, centred on the
 * other axis, sitting `gap` clear of the dot's PAINTED ring. `offsetX`/
 * `offsetY` then translate it from there.
 *
 * - origin "right"  → content's LEFT edge at the ring, vertically centred
 * - origin "left"   → content's RIGHT edge at the ring, vertically centred
 * - origin "top"    → content's BOTTOM edge at the ring, horizontally centred
 * - origin "bottom" → content's TOP edge at the ring, horizontally centred
 *
 * WHY one fixed rule and no "when offsetY ≠ 0 anchor the bottom instead"
 * mode: a hidden anchor switch is exactly the kind of thing that reads
 * fine in the one case it was written for and silently does the wrong
 * thing in the next. The cost is that a lift computed for one label
 * height is only tight for that height — which is why the lifted default
 * is RESOLVED from the live text size rather than frozen into a preset
 * literal (see `SlotAlign`'s own WHY).
 */
export function slotPlacementStyle(
  placement: SlotPlacement,
  dot: PortDotBox,
  gapPx: number,
  boxInsetPx: number = 0,
): PortLabelPlacement {
  const { origin, align, offsetX, offsetY } = placement;
  // The chosen edge, as a percentage of the slot's OWN size — so it stays
  // correct when the slot grows, with no recomputation anywhere.
  const shift = ALIGN_SHIFT[align];
  const outX = `${dot.w + PORT_RING_OVERHANG_PX + gapPx - boxInsetPx}px`;
  const outY = `${dot.h + PORT_RING_OVERHANG_PX + gapPx - boxInsetPx}px`;
  // Both offsets ride in the TRANSFORM rather than the edge properties, so
  // the cross-axis `-50%` centring and the displacement compose without
  // either needing to know the content's own size — and a percentage and
  // a px value never have to be added by hand.
  switch (origin) {
    // WHY every origin uses the SAME unmirrored signs even though `left`
    // anchors by `right:` and `top` by `bottom:` — both of which grow
    // toward the origin: a transform is applied in SCREEN space, not in
    // the anchor's direction, so `translate(5px)` moves right on all four.
    // An earlier version mirrored the sign so `+x` would mean "away from
    // the dot", which reads well until you notice the control reverses
    // itself depending on the origin, and contradicts this very type's
    // "+x right, +y DOWN" contract. Screen space is what every design tool
    // means by an x/y offset, and it is the one convention that does not
    // change meaning halfway down the origin list.
    case "right":
      return { left: outX, top: "50%", transform: `translate(${offsetX}px, calc(${shift} + ${offsetY}px))` };
    case "left":
      return { right: outX, top: "50%", transform: `translate(${offsetX}px, calc(${shift} + ${offsetY}px))` };
    case "top":
      return { bottom: outY, left: "50%", transform: `translate(calc(${shift} + ${offsetX}px), ${offsetY}px)` };
    case "bottom":
      return { top: outY, left: "50%", transform: `translate(calc(${shift} + ${offsetX}px), ${offsetY}px)` };
  }
}



/**
 * The old six-member `PortTextLayout` as (origin, offsetY) — the
 * compatibility read for everything already persisted.
 *
 * `PortTextLayout`'s literals are written into saved tldraw shapes
 * (`T.literalEnum` in both shape utils), so a board saved before this
 * change still hands them back. This is the one place that translation
 * lives; nothing downstream needs to know the old vocabulary existed.
 * The two lifted members are marked by `align: "end"` and nothing else —
 * no flag, and no offset resolved from the live text size. Aligning the
 * slot's BOTTOM edge to the origin line is what puts a label clear of the
 * wire whatever its height turns out to be, which is why the remaining
 * `offsetY` is the static `-PORT_LABEL_GAP` and not a computed lift.
 */
export const TEXT_LAYOUT_AS_PLACEMENT: Record<
  PortTextLayout,
  { origin: SlotOrigin; align: SlotAlign; offsetY: number }
> = {
  top: { origin: "top", align: "center", offsetY: 0 },
  bot: { origin: "bottom", align: "center", offsetY: 0 },
  right: { origin: "right", align: "center", offsetY: 0 },
  left: { origin: "left", align: "center", offsetY: 0 },
  // The two lifted members are now a STATIC placement: anchor the slot's
  // BOTTOM edge (`align: "end"`) on the dot's centre line, then push it up
  // by one gap. Height-independent by construction, where the previous
  // form had to derive the lift from the label's own height — a number the
  // component cannot actually know (Zach, 2026-09-15: "We defintily don't
  // want to kinda be dynamically calculating the x/y offset if the slot
  // length changes right").
  rightOffset: { origin: "right", align: "end", offsetY: -PORT_LABEL_GAP },
  leftOffset: { origin: "left", align: "end", offsetY: -PORT_LABEL_GAP },
};

/** The same compatibility read for the secondary slot's own four-member
 *  enum — every member is a corner hug, so none is "lifted". */
export const SECONDARY_LAYOUT_AS_ORIGIN: Record<SecondarySlotLayout, SlotOrigin> = {
  leftOffset: "left",
  rightOffset: "right",
  topOffset: "top",
  botOffset: "bottom",
};

"use client";

import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { resolveField } from "./schema";

import { cn } from "./lib/utils";
import { SketchOutline } from "./sketchOutline";
import {
  STATE_TOKENS,
  TONE_TOKENS,
  type AppearanceState,
  type Lens,
  type Tone,
  paintVar,
} from "./appearance";
import { CodeField } from "./codeField";
import { LABELED_PORT_FIELDS } from "./port.fields";
import { PORT_PRESETS } from "./port.presets";
import {
  PORT_DIAMETERS,
  PORT_HIT_PX,
  PORT_LABEL_GAP,
  PORT_RING_OVERHANG_PX,
  PORT_SECONDARY_SLOT_GAP_PX,
  PORT_STATE_RING_PX,
  PORT_SURFACE_RING_PX,
  PORT_TEXT_SIZES,
  slotPlacementStyle,
  SECONDARY_LAYOUT_AS_ORIGIN,
  TEXT_LAYOUT_AS_PLACEMENT,
  defaultSecondarySlotLayout,
  inwardTextLayout,
  originFlexDirection,
  portLabelPlacement,
  type BlockSide,
  type PortDirection,
  type PortReveal,
  type PortSize,
  type PortSizeRung,
  type PortTextLayout,
  type PortTextSize,
  type SecondarySlotLayout,
  type SlotOrigin,
  type SlotAlign,
  type SlotPlacement,
} from "./port.layout";

/** The two fields `Port`'s own `size` rung governs — looked up once from
 * `PORT_FIELDS` (never re-typed) so `resolveField` runs the SAME
 * computation the product inspector's trace panel reads, exactly
 * `pill.tsx`'s own `PAINT_FIELD_BY_ID` pattern. */
const DIAMETER_FIELD = LABELED_PORT_FIELDS.find((f) => f.id === "diameter")!;
const TEXT_SIZE_FIELD = LABELED_PORT_FIELDS.find((f) => f.id === "textSize")!;

/**
 * Fills in `textLayout`/`secondarySlotLayout` with their real AUTO defaults
 * (`inwardTextLayout(edge)`, `defaultSecondarySlotLayout`) when a subject
 * omits them, so the inspector's own trace resolves against what actually
 * PAINTS rather than each field's own static `defaultValue` (port.fields.ts:
 * "leftOffset", correct only when textLayout happens to be "right"). Same
 * shape as `pill.tsx`'s own `pillResolutionSubject` — imported by
 * `packages/panel/src/bench.tsx`'s Port registration exactly the way
 * Pill's already is, not reimplemented. Fixes the Secondary Slot dropdown
 * showing a stale "Left Offset" no matter what Label Slot Location is
 * actually set to — the real rendered badge position was always correct
 * (`PortDot`'s own `secondarySlotLayout ?? defaultSecondarySlotLayout(...)`
 * fallback), only the panel's DISPLAY of the unset field's value was wrong.
 */
/**
 * The flex row's displacement for a slot — the SAME translate
 * `slotPlacementStyle` emits for an absolutely-positioned host, so the two
 * paths move a label by the identical rule.
 *
 * `undefined` (not a zero translate) when there is nothing to displace, so
 * an untouched port emits no style at all.
 *
 * The sign mirrors on an origin that faces the other way for the same
 * reason it does in `slotPlacementStyle`: `+x` must mean "rightward on
 * screen" whichever side the slot hangs off, or the control would reverse
 * itself halfway through the origin list.
 */
function flexOffsetTransform(placement: SlotPlacement): CSSProperties | undefined {
  const { origin, align, offsetX, offsetY } = placement;
  // The align shift is a DELTA FROM CENTRE here, where `slotPlacementStyle`
  // states it absolutely.
  //
  // WHY they differ: the anchored path positions from an EDGE (`top: 50%`)
  // and translates the whole way, so `end` is -100%. A flex row has
  // already centred the label against the dot (`items-center`), so the
  // same reference edge is half a step away: -50% puts the label's bottom
  // on the dot's centre line, +50% its top. Stating the delta rather than
  // reusing the absolute number is what makes both paths land the chosen
  // edge in the SAME place — the alternative, re-centring the row, is the
  // layout-resizing margin this deliberately replaced.
  const alignShift = align === "center" ? 0 : align === "end" ? -50 : 50;
  const crossIsVertical = origin === "left" || origin === "right";
  if (offsetX === 0 && offsetY === 0 && alignShift === 0) return undefined;
  // Unmirrored offsets, for the same reason `slotPlacementStyle`'s are: a
  // transform is screen-space, so the signs mean one thing on all four
  // origins.
  // A zero shift emits plain px rather than `calc(0% + Npx)` — same
  // result, but the style a reader sees matches what they asked for.
  const along = (px: number) => `${px}px`;
  const cross = (px: number) => (alignShift === 0 ? `${px}px` : `calc(${alignShift}% + ${px}px)`);
  const x = crossIsVertical ? along(offsetX) : cross(offsetX);
  const y = crossIsVertical ? cross(offsetY) : along(offsetY);
  return { transform: `translate(${x}, ${y})` };
}

export function portResolutionSubject(props: Record<string, unknown>): Record<string, unknown> {
  const edge = (props.edge as BlockSide | undefined) ?? "left";
  const textLayout = (props.textLayout as PortTextLayout | undefined) ?? inwardTextLayout(edge);
  // `labelOffset`'s FieldSpec must declare a static `defaultValue` (19, the
  // computed lift at Port's default "md" dot), but the real default scales
  // with the dot — so a Port at `lg` genuinely lifts 22px while the panel
  // would keep printing 19. Resolving it here is what makes the Expert
  // control read the number actually on screen.
  //
  // WHY `resolveField` and not `props.diameter ?? "md"`: `diameter` is
  // GOVERNED by the `size` cascade (PORT_PRESETS), so a Port carrying
  // `size: "lg"` and no explicit `diameter` renders an 18px dot while its
  // raw prop is undefined. Reading the prop directly reported the `md`
  // lift (19) for a port that was really lifting 22 — the exact
  // panel-disagrees-with-the-pixels bug this function exists to prevent,
  // reintroduced one field over. Resolving through the SAME call `Port`
  // itself makes is what keeps them in step.
  const diameterResolved = resolveField(
    DIAMETER_FIELD,
    // `size` takes Port's OWN real default when absent — it is the
    // cascade's selector, and a selector must have a value to match on.
    { size: props.size ?? "md", diameter: props.diameter, textSize: props.textSize },
    PORT_PRESETS,
  ).resolved as PortSize;
  const diameterPx =
    typeof diameterResolved === "number" ? diameterResolved : PORT_DIAMETERS[diameterResolved];
  // Same cascade for textSize — the lifted default is a function of the
  // label's real height, so reading the raw prop would repeat the very bug
  // the diameter resolution above exists to avoid.
  const textSizeResolved = resolveField(
    TEXT_SIZE_FIELD,
    { size: props.size ?? "md", diameter: props.diameter, textSize: props.textSize },
    PORT_PRESETS,
  ).resolved as PortTextSize;
  return {
    ...props,
    textLayout,
    secondarySlotLayout:
      (props.secondarySlotLayout as SecondarySlotLayout | undefined) ?? defaultSecondarySlotLayout(textLayout),
    // Each slot's placement, resolved the way the component resolves it, so
    // the Expert controls read the numbers actually on screen rather than
    // the static literals their FieldSpecs are forced to declare. Same
    // mechanism the secondary layout above already uses.
    labelOrigin: (props.labelOrigin as SlotOrigin | undefined) ?? TEXT_LAYOUT_AS_PLACEMENT[textLayout].origin,
    labelOffsetX: (props.labelOffsetX as number | undefined) ?? 0,
    labelAlign: (props.labelAlign as SlotAlign | undefined) ?? TEXT_LAYOUT_AS_PLACEMENT[textLayout].align,
    labelOffsetY:
      (props.labelOffsetY as number | undefined) ?? TEXT_LAYOUT_AS_PLACEMENT[textLayout].offsetY,
    secondaryOrigin:
      (props.secondaryOrigin as SlotOrigin | undefined) ??
      SECONDARY_LAYOUT_AS_ORIGIN[
        (props.secondarySlotLayout as SecondarySlotLayout | undefined) ?? defaultSecondarySlotLayout(textLayout)
      ],
    secondaryAlign: (props.secondaryAlign as SlotAlign | undefined) ?? "center",
    secondaryOffsetX: (props.secondaryOffsetX as number | undefined) ?? 0,
    secondaryOffsetY: (props.secondaryOffsetY as number | undefined) ?? 0,
  };
}

/**
 * packages/bbox-ui/src/port.tsx — TWO primitives, split 2026-09-15 on
 * Zach's ruling: "I want to split into two primatives now. Port and
 * Labeled Port. Port is just the actual like Port geometry its self in
 * isolation. Labeled Port is composite of the port + the primary and
 * secondary slots, that we will then put things into thoose slots".
 *
 * `Port` — the geometry, alone. The disc, the 2px surface ring, the 3px
 * state ring, the lit core, the 40px hit halo. It knows nothing about
 * labels, slots, producers or which wall it sits on. This is what used to
 * be called `PortDot`; the rename is the point of the split, so there is
 * no `PortDot` alias — one name per thing.
 *
 * `LabeledPort` — the composite: a `Port` plus its two slots. This is
 * what `Port` used to be.
 *   - The LABEL slot (the "primary" slot) — `PortLabel`, a real
 *     single-line `CodeField`, positioned by `textLayout`
 *     (`./port.layout.ts`'s six-member `PortTextLayout`, auto-defaulting
 *     via `inwardTextLayout(edge)`), lifted clear of a trace wire by
 *     its preset's `align: "end"` when the layout is one of the two Offset
 *     members — see `SlotAlign` (port.layout.ts).
 *     A host owning its own slot model passes `labelSlot` instead and
 *     the built-in field steps aside entirely.
 *   - The SECONDARY slot — generic `ReactNode` hugging one corner of the
 *     dot's own box, positioned by `secondarySlotLayout`, auto-defaulting
 *     to the side opposite the label. `producers >= 2` composes a
 *     `PortCountBadge` as its fallback content for prop-only hosts.
 *
 * WHY the secondary slot moved OUT of the geometry and into the composite
 * (this split): it is not geometry. The dot is a shape; where a badge
 * hangs off it is an arrangement fact, and arrangement is exactly what
 * `LabeledPort` is for. The composite wraps the `Port` in a box of the
 * dot's own dimensions when — and only when — there is slot content to
 * carry, so the slot's offsets resolve against the same rectangle they
 * always did and the pixels do not move.
 *
 * ANATOMY (PORT-SPEC.md §2.1): `Port` and `PortLabel` are SIBLINGS, never
 * parent/child — a real host positions both absolutely from the
 * *container's* layout at a shared anchor, and needs the dot to win
 * z-order/hit-arbitration against its own label independently.
 * `LabeledPort` is the flex-row PAIRING of those two siblings for a
 * standalone specimen; a host placing a real port on a real block wall
 * instead uses `Port`/`PortLabel` directly, positioned via
 * `./port.layout.ts`'s `portDotPlacement`/`portLabelPlacement` — never
 * nested one inside the other. This is T0's own anatomy bug
 * (PORT-SPEC.md §0.2): a single flex parent could not reproduce that
 * independence.
 *
 * WHY the `portDot*` helpers keep their names (`portDotClass`,
 * `portDotStyle`, `PortDotPaintInput`, `PortDotBox`): "dot" now names the
 * disc INSIDE `Port` rather than a component of its own, and it is still
 * the right word for the thing they paint. Renaming them to `portClass`/
 * `portStyle` would have churned every adapter and test for a vaguer word.
 *
 * PORT COLOUR COMES FROM STATE, NOT TYPE (Zach, 2026-09-10 ruling — see
 * docs/T1-SPEC.md and PORT-SPEC.md's standing amendment). `portDotStyle`
 * below reads colour from `STATE_TOKENS`/`TONE_TOKENS` (./appearance.ts) —
 * the SAME two lookups the cascade's worked example (docs/T1-SPEC.md §1.4)
 * illustrates.
 */

/* ------------------------------------------------------------------ */
/* The dot's paint — state (+ tone override, + the interaction axis)   */
/* ------------------------------------------------------------------ */

export interface PortDotPaintInput {
  state?: AppearanceState;
  tone?: Tone;
  dimmed?: boolean;
  hinting?: boolean;
}

/**
 * Static half of the dot's class — sizing/shape/transition only. Every
 * COLOUR fact (the two-layer box-shadow ring, the fill) is dynamic per
 * state/tone and lives in `portDotStyle` instead: two concentric rings of
 * DIFFERENT, per-state token colours cannot be expressed as a static
 * Tailwind border class the way T0's single `border-2` could. Exported —
 * same reason T0 exported it — "so host adapters can paint the same dot
 * on elements they own" (e.g. a React Flow `Handle`).
 *
 * `hover:scale-110` is a real CSS `:hover` pseudo-class, deliberately NOT
 * a `hover`/`hovering` prop (2026-09-12 port-props ruling, D2) — nothing
 * ever needs to SET hover from outside (a host doesn't drive it, a
 * document never persists it), so giving it a prop would be a control
 * that never does anything a real `:hover` doesn't already do on its own.
 * Preview it in Storybook via the pseudo-states addon, not a boolean arg.
 */
export function portDotClass(): string {
  return "relative box-border inline-flex shrink-0 rounded-full transition-transform duration-[50ms] ease-in-out hover:scale-110 motion-reduce:transition-none motion-reduce:hover:scale-100";
}

/**
 * Resolves ONE paint channel (ring, fill, or core) to a real CSS colour
 * value — or `null`, meaning "state says this channel does not paint at
 * all".
 *
 * `base` is the STATE_TOKENS token for this channel at the current state;
 * `null` there is authoritative and wins outright, before `tone` is even
 * consulted — this is "state owns the presence/fill bit" (Judge round 6,
 * finding R12). When `base` DOES paint and a non-neutral tone is set, the
 * tone's hue leads via `color-mix` but is blended WITH the state's own
 * base colour rather than replacing it outright: a flat substitution
 * (tried first, see the fix's git history) collapses every state that
 * shares a base token's "shape" — `empty`'s hollow `foreground` ring and
 * `valueSet`'s hollow `muted-foreground` ring, or `wired`'s lit `primary`
 * core and `received`'s solid `bbox-received` fill — into one identical
 * tone-coloured circle, re-breaking the same "State control goes inert"
 * bug one level down. Blending keeps the tone recognisably dominant while
 * the state's own hue still shows through enough that every persistable
 * state stays distinguishable under any single tone (verified by
 * `test/port.paint.test.ts`).
 */
function toneColor(base: string | null, toneToken: string | null): string | null {
  if (base == null) return null;
  if (toneToken == null) return paintVar(base);
  return `color-mix(in srgb, ${paintVar(toneToken)} 70%, ${paintVar(base)} 30%)`;
}

/**
 * The dot's ring/fill, resolved from the cascade's token lookups via
 * `toneColor` above. `tone` is sugar that writes the override layer
 * (`toneOverride`, appearance.ts) — Port has no separate settable paint
 * field for an override to land on (see `port.presets.ts` for why
 * `PORT_PRESETS` is empty), so this function IS that override, computed
 * directly rather than through `resolveFields` against a governed
 * property that doesn't exist.
 *
 * Two host-set, never-persisted modifiers compose OVER the resting paint,
 * never replacing `state`'s own reading (2026-09-12 port-props ruling —
 * `outOfFocus`/`eligible`/`dragging` used to be three overlapping ways of
 * saying "the host is doing something to this port"; now there are two):
 *
 * - `dimmed` — the port is out of focus, OR mid-drag and not a legal
 *   target ("not eligible ⇒ dimmed": one boolean covers both, since
 *   they're the identical grey-ring-and-faded read). Forces the ring to
 *   `muted-foreground` and fades the WHOLE dot to ~45% opacity, leaving
 *   the resting fill/core colour underneath untouched (so a `dimmed`
 *   `wired` port is still legible as "wired, just not focused right now"
 *   rather than becoming indistinguishable grey).
 * - `hinting` — the pointer is over this port mid-drag, previewing it
 *   BECOMING `wired`: it wears `wired`'s own shape (hollow ring, lit
 *   core) in `--primary` ink regardless of `state`, scaled up with a
 *   wide halo. Wearing `empty`'s own ink here would read as "this port is
 *   broken" rather than "drop here" — see `portCoreStyle` below for the
 *   matching core paint. `hinting` wins over `dimmed` when both are set
 *   (the one port under the pointer is by definition the eligible one).
 */
/**
 * The dot's ring colour, as one exported derivation.
 *
 * WHY extracted rather than left inline: the sketch skin draws the ring as
 * a path instead of as box-shadow layers, and it has to be the SAME colour.
 * A second copy of this three-branch precedence (hinting > dimmed > tone >
 * state) is exactly how a `hinting` port would end up orange in one skin
 * and grey in another. `null` means "this state paints no ring at all".
 */
export function portRingColor({
  state = "empty",
  tone = "neutral",
  dimmed = false,
  hinting = false,
}: PortDotPaintInput): string | null {
  const toneToken = TONE_TOKENS[tone];
  const { ring } = STATE_TOKENS[state];
  return hinting
    ? paintVar("primary")
    : dimmed
      ? paintVar("muted-foreground")
      : toneColor(ring, toneToken);
}

export function portDotStyle({
  state = "empty",
  tone = "neutral",
  dimmed = false,
  hinting = false,
}: PortDotPaintInput): CSSProperties {
  const toneToken = TONE_TOKENS[tone];
  const { fill } = STATE_TOKENS[state];
  const ringColor = portRingColor({ state, tone, dimmed, hinting });
  // `hinting` renders hollow (fill: null), matching `wired`'s own shape —
  // see the module doc above and `portCoreStyle`'s matching lit core.
  const fillColor = hinting ? null : toneColor(fill, toneToken);

  const layers: string[] = [];
  if (ringColor != null) {
    const stateRingPx = hinting ? 4 : PORT_STATE_RING_PX;
    layers.push(`0 0 0 ${PORT_SURFACE_RING_PX}px var(--card)`);
    layers.push(`0 0 0 ${PORT_SURFACE_RING_PX + stateRingPx}px ${ringColor}`);
  }
  if (hinting) {
    layers.push("0 0 0 9px color-mix(in srgb, var(--bbox-primary, var(--primary)) 38%, transparent)");
  }

  // WHY conditionally-built, never `key: cond ? … : undefined`: a caller
  // that spread-merges this bag over its own positioning style (the React
  // Flow adapter merges dot paint + `PORT_DOT_CENTER_TRANSFORM` into one
  // Handle style) had its centering transform DELETED by a literal
  // `transform: undefined` key winning the spread — React Flow's own
  // stylesheet (`.react-flow__handle-right { transform: translate(50%,-50%) }`)
  // then took over, measured live as +12px outward drift of every
  // right-wall handle at zoom 1. Only emit a key when it actually paints.
  const style: CSSProperties = {};
  // Behind a token so the sketch skin can blank the CSS rings and let the
  // drawn one take their place. Undefined on every other skin, so the
  // `var()` fallback IS the layer list and nothing changes. `initial`
  // scoped to a subtree puts them back — see skin.css's exemption note.
  if (layers.length > 0) style.boxShadow = `var(--bbox-skin-dot-rings, ${layers.join(", ")})`;
  // The disc's resting paint is OPAQUE, never "transparent": a wall-mounted
  // dot straddles the block's border, and a transparent interior let the
  // wall line show through the middle of a hollow (`empty`/`wired`) dot.
  // SystemSketch's reference circle is `fill={surface}` for exactly this
  // reason; `var(--card)` is the same token the 2px surface ring already
  // uses, so ring and disc read as one punch-out rather than a window.
  style.background = fillColor ?? "var(--card)";
  if (dimmed && !hinting) style.opacity = 0.45;
  if (hinting) style.transform = "scale(1.18)";
  return style;
}

/** The core's own diameter as a fraction of the dot's — small enough to
 * read as "something lit inside the ring", never competing with the fill
 * for the disc's whole area. */
const PORT_CORE_RATIO = 0.42;

/**
 * The small inner "core" dot lit for `wired` (disc kept hollow, core lit
 * instead of the old solid fill) and `received` (core matches the already
 * -solid fill, so it reads as "fully lit" rather than losing the core in
 * its own fill colour) — 2026-09-12 port-props ruling, "the three circles
 * are one token-table row." A `null` return means "no core layer at all",
 * not a transparent one, so `empty`/`valueSet` never mount the extra span.
 */
export function portCoreStyle({ state = "empty", tone = "neutral", hinting = false }: PortDotPaintInput): CSSProperties | null {
  const toneToken = TONE_TOKENS[tone];
  const core = hinting ? "primary" : STATE_TOKENS[state].core;
  const color = hinting ? paintVar("primary") : toneColor(core, toneToken);
  if (color == null) return null;
  return { background: color };
}

/* ------------------------------------------------------------------ */
/* The secondary slot — generic content hugging a corner of the dot's  */
/* own box (two-slot proposal, 2026-09-12). `role`/`decoration` (the   */
/* old semantic-role cue and mutates/variadic ring) were removed       */
/* 2026-09-12 (port.layout.ts's own WHY, above their old import site). */
/* ------------------------------------------------------------------ */

// WHY total lookups and not ternaries: a ternary has a fall-through, so
// widening either union ships a live panel segment that renders exactly like
// the default, typecheck clean and every test green. A Record over the real
// union is a compile error until someone says what the new member looks like.
const REVEAL_CLASS: Record<PortReveal, string> = {
  always: "",
  onHover: "opacity-0 transition-opacity hover:opacity-100 focus-within:opacity-100",
};

/** One offset per `SecondarySlotLayout` corner, hugging the dot at
 * `PORT_SECONDARY_SLOT_GAP_PX` clearance — the exact geometry the old
 * hardcoded `PortCountBadge` overlay always used, now addressable by
 * `secondarySlotLayout` independently of the label's own flow side rather
 * than derived from it every time. The gap is measured from the dot's
 * PAINTED ring, not its layout box, same as `portLabelOut`/`BADGE_OFFSET_PX`
 * used to (see port.layout.ts's own WHY on `PORT_RING_OVERHANG_PX`) —
 * otherwise the badge sits `PORT_RING_OVERHANG_PX` closer to the ring than
 * the label does. */
const SECONDARY_SLOT_OFFSET_PX = PORT_RING_OVERHANG_PX + PORT_SECONDARY_SLOT_GAP_PX;
const SECONDARY_SLOT_STYLE: Record<SecondarySlotLayout, CSSProperties> = {
  leftOffset: {
    right: "100%",
    marginRight: SECONDARY_SLOT_OFFSET_PX,
    top: "50%",
    transform: "translateY(-50%)",
  },
  rightOffset: {
    left: "100%",
    marginLeft: SECONDARY_SLOT_OFFSET_PX,
    top: "50%",
    transform: "translateY(-50%)",
  },
  topOffset: {
    bottom: "100%",
    marginBottom: SECONDARY_SLOT_OFFSET_PX,
    left: "50%",
    transform: "translateX(-50%)",
  },
  botOffset: {
    top: "100%",
    marginTop: SECONDARY_SLOT_OFFSET_PX,
    left: "50%",
    transform: "translateX(-50%)",
  },
};

/**
 * The many-to-one producer count — `Port`'s own default secondary-slot
 * content (`producers >= 2`, the unchanged threshold from before this
 * change). Kept as an exported, documented EXAMPLE of what the now-generic
 * secondary slot can hold: `PortDot` itself does not know this component
 * exists, does no `producers` counting, and does not position it — a
 * consumer composes something else in its place (a role cue, a status
 * dot) the exact same way, by passing different `secondarySlot` content.
 */
export function PortCountBadge({ count }: { count: number }) {
  return (
    <span
      data-slot="port-count"
      className="flex min-w-[16px] items-center justify-center rounded-[7px] bg-foreground/10 px-[5px] text-[10px] font-semibold leading-[16px] text-foreground"
      style={{ height: 16 }}
    >
      {count}
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* PortDot — the disc + both rings + the lit core + the hit halo +     */
/* the generic secondary slot. Independently positionable (module doc). */
/* ------------------------------------------------------------------ */

export interface PortProps extends ComponentProps<"span"> {
  state?: AppearanceState;
  tone?: Tone;
  diameter?: PortSize;
  /** Author-set, persisted — same shape as `bar.fields.ts`'s existing
   * `hidden`. Replaces the old `state: "hidden"` rung: painting nothing is
   * a visibility fact, not a seventh kind of content (appearance.ts's own
   * WHY). */
  hidden?: boolean;
  /** Host-set, never persisted — the port is out of focus, or mid-drag and
   * not a legal target. Replaces `outOfFocus` (a `state` rung) and
   * `eligible` (inverted): see `portDotStyle`'s own WHY. */
  dimmed?: boolean;
  /** Host-set, never persisted — the pointer is over this port mid-drag. */
  hinting?: boolean;
}

/**
 * The dot alone: the disc, the 2px surface-coloured gap ring, the 3px
 * state ring, the small lit "core" some states paint on top
 * (`portCoreStyle`), a 40px invisible hit halo (always centred on the dot
 * regardless of `diameter`), and the optional generic secondary slot.
 *
 * `hidden` renders NOTHING ("not painted at all; the container counts it
 * into `+N more`") — see `PortHiddenSummary` below for that
 * container-owned summary.
 */
export function Port({
  state = "empty",
  tone = "neutral",
  diameter = "md",
  hidden = false,
  dimmed = false,
  hinting = false,
  className,
  style,
  ...props
}: PortProps) {
  if (hidden) return null;
  const diameterPx = typeof diameter === "number" ? diameter : PORT_DIAMETERS[diameter];
  // A fixed 40px hit target regardless of the painted diameter — the
  // donor's own `inset: -14px` is this formula evaluated at diameter=12.
  const haloInset = (diameterPx - PORT_HIT_PX) / 2;
  const coreStyle = portCoreStyle({ state, tone, hinting });
  const ringColor = portRingColor({ state, tone, dimmed, hinting });
  return (
    <span
      data-slot="port-dot"
      data-state={state}
      data-tone={tone}
      data-diameter={diameter}
      data-dimmed={dimmed || undefined}
      data-hinting={hinting || undefined}
      className={cn(portDotClass(), className)}
      style={{
        width: diameterPx,
        height: diameterPx,
        ...portDotStyle({ state, tone, dimmed, hinting }),
        ...style,
      }}
      {...props}
    >
      {/* The drawn ring. Zach asked for sketch to reach every component;
          a Port is also the one he flagged as most likely to want back to
          normal, which the exemption recipe in skin.css covers in two
          lines. Colour comes from `portRingColor` — the same derivation
          the box-shadow rings use — so `state` keeps sole ownership of it. */}
      {ringColor != null && (
        <SketchOutline
          shape="ellipse"
          // Lands the drawn ring on the SAME centre-line the box-shadow
          // rings use. Those paint an annulus from `d/2 + SURFACE` out to
          // `d/2 + SURFACE + STATE`, so its centre-line diameter is
          // `d + 2*SURFACE + STATE`; SketchOutline insets the path by one
          // border width per side, hence the extra 2*STATE.
          width={diameterPx + PORT_SURFACE_RING_PX * 2 + PORT_STATE_RING_PX * 3}
          height={diameterPx + PORT_SURFACE_RING_PX * 2 + PORT_STATE_RING_PX * 3}
          borderWidth={PORT_STATE_RING_PX}
          stroke={ringColor}
          seed={`port:${state}:${diameter}`}
        />
      )}
      <span
        data-slot="port-dot-halo"
        aria-hidden
        className="absolute rounded-full"
        style={{ inset: haloInset }}
      />
      {coreStyle && (
        <span
          data-slot="port-dot-core"
          aria-hidden
          className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full"
          style={{
            width: `${PORT_CORE_RATIO * 100}%`,
            height: `${PORT_CORE_RATIO * 100}%`,
            ...coreStyle,
          }}
        />
      )}
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* PortLabel — the label slot, now a real single-line CodeField.       */
/* `PortName`/`PortType`/`PortDefaultChip` (the old three-span layout)  */
/* are REMOVED here — confirmed zero usage outside this file before    */
/* removal (recon, 2026-09-12), same standard `role`/`decoration`'s     */
/* removal above was held to.                                          */
/* ------------------------------------------------------------------ */

/** Stable no-op so an unwired `PortLabel` (no `onLabelWrite`) doesn't
 * allocate a fresh throwaway function every render — `Port` is
 * presentational ("props in, DOM out"); a field with nowhere to write
 * still has to satisfy `CodeField`'s required `onWrite`. */
function noopWrite() {}

export interface PortLabelProps extends ComponentProps<"span"> {
  /**
   * The label's ENTIRE content, as one line — "a port is one line of
   * code" (`get_aruco: ArucoSrv`). REPLACES the old separate `name`/
   * `type`/`defaultValue` props, folded into this single string rather
   * than kept apart: no parser anywhere in this workspace splits a
   * composed `name: Type = default` line back into three fields on edit,
   * and every REAL caller already in this workspace (the tldraw/React
   * Flow adapters, the docs examples, the port-inspector demo) already
   * passed one composed string as `children` and never touched
   * `name`/`type`/`defaultValue` at all — this is that same shape, now
   * also the thing `CodeField` actually edits.
   */
  children?: string;
  direction?: PortDirection;
  textSize?: PortTextSize;
  /** Same fact as `PortDot`'s own `hidden` — see its docblock. */
  hidden?: boolean;
  /** No caret, no edits — a read-only port. */
  disabled?: boolean;
  /**
   * Fired on every keystroke (`CodeField`'s own live `onWrite`). Omit for
   * a label that shows `children` but never persists an edit anywhere —
   * `Port` does no editing state of its own (same category as `dimmed`/
   * `hinting`: host-set/host-observed, never internal). A host that wants
   * typed text to stick wires this to whatever updates its own store; one
   * left unwired simply reverts to `children` the moment the field blurs
   * (`CodeField`'s own controlled-value contract), same as an `<input>`
   * with no `onChange`.
   */
  onLabelWrite?(value: string): void;
  /** Shown when `children` is empty. */
  placeholder?: string;
}

/**
 * The label slot: a real single-line `CodeField` (`./codeField.tsx`,
 * ported from `claude/code-field`) bound to `children` as its whole
 * `value` — grammar-free (a plain code text box; wiring the Python
 * `name: Type = default` grammar/autocomplete is explicitly out of scope
 * for this change, see this file's module doc). Independently
 * positionable from `PortDot` — see the module doc at the top of this
 * file.
 *
 * `direction` no longer reorders the label's CONTENT — there is nothing
 * left TO reorder once it's one free-typed string, unlike the old
 * direction-mirrored name/type/chip span order. It still sets the
 * field's text alignment, so the caret-adjacent edge still visually hugs
 * the dot on whichever side the port sits, the same visual intent the
 * old mirroring served.
 */
export function PortLabel({
  children = "",
  direction = "input",
  textSize = "sm",
  hidden = false,
  disabled = false,
  onLabelWrite,
  placeholder,
  className,
  style,
  ...props
}: PortLabelProps) {
  // "no dot, no slot" — a hidden port's label disappears along with its
  // dot, whether the two are rendered together (`Port`, which never even
  // calls this far) or a host positions them independently and passes
  // `hidden` through.
  if (hidden) return null;
  return (
    <span
      data-slot="port-label"
      data-direction={direction}
      className={cn("flex min-w-0 items-center overflow-hidden", className)}
      style={style}
      {...props}
    >
      <CodeField
        value={children}
        onWrite={onLabelWrite ?? noopWrite}
        disabled={disabled}
        placeholder={placeholder}
        // Text hugs the dot on the side the label actually flows toward —
        // `right`/`rightOffset` grow away to the right (dot sits at the
        // field's LEFT, so left-align), `left`/`leftOffset` the mirror.
        // `direction` still carries this intent (see the docblock above)
        // now that content order itself has nothing left to mirror.
        align={direction === "output" ? "right" : "left"}
        // `textSize` scales the field's own font (codeField.css inherits
        // it from this wrapper — see its own WHY) so a Port at `lg`/`xl`
        // doesn't stay pinned to the field's compact default size.
        style={{ fontSize: PORT_TEXT_SIZES[textSize] }}
        testId="port-label-field"
      />
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* PortHiddenSummary — the container's "+N more", never one Port's job */
/* ------------------------------------------------------------------ */

export interface PortHiddenSummaryProps extends ComponentProps<"span"> {
  count: number;
  direction?: PortDirection;
}

/**
 * A container's own roll-up over its `state: "hidden"` ports
 * (PORT-SPEC.md §2.1's `.BlockNode-hiddenPorts`, §4's "owned by the
 * host" table) — never rendered by one `Port` instance, which is why
 * `PortDot`/`PortLabel` simply return `null` for a hidden port instead
 * of rendering this themselves. Exported here because it shares Port's
 * own typography tokens.
 */
export function PortHiddenSummary({
  count,
  direction = "input",
  className,
  style,
  ...props
}: PortHiddenSummaryProps) {
  return (
    <span
      data-slot="port-hidden-summary"
      data-direction={direction}
      className={cn("italic font-semibold text-muted-foreground", className)}
      style={{ fontSize: 11, lineHeight: "16px", height: 16, ...style }}
      {...props}
    >
      +{count} more
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* Port — the flex-row PAIRING of PortDot + PortLabel, for a standalone */
/* specimen. A host placing a real port on a real block wall uses       */
/* PortDot/PortLabel directly instead (see the module doc).             */
/* ------------------------------------------------------------------ */

export interface LabeledPortProps extends ComponentProps<"div"> {
  /** The label slot's ENTIRE content, one line — see `PortLabelProps`'s
   * own doc for why `name`/`type`/`defaultValue` (removed here) folded
   * into this single string instead of staying apart. */
  children?: string;
  direction?: PortDirection;
  edge?: BlockSide;
  /** The cascading rung a header (Bar/Flex) hands down — governs
   * `diameter`/`textSize` together via `PORT_PRESETS`. An explicit
   * `diameter`/`textSize` still wins (see `Port`'s own render). */
  size?: PortSizeRung;
  diameter?: PortSize;
  /** Sensible default is `inwardTextLayout(edge)` when omitted. Six
   * values now (`PortTextLayout`, port.layout.ts) — the two-slot
   * proposal's "Label Slot Placement": `top | bot | right | left |
   * rightOffset | leftOffset`. */
  textLayout?: PortTextLayout;
  textSize?: PortTextSize;
  state?: AppearanceState;
  tone?: Tone;
  lens?: Lens;
  lensBefore?: string;
  /** Author-set, persisted — same shape as `bar.fields.ts`'s existing
   * `hidden`. See `PortDot`'s own docblock. */
  hidden?: boolean;
  /** Host-set, never persisted — see `portDotStyle`'s own WHY. */
  dimmed?: boolean;
  hinting?: boolean;
  reveal?: PortReveal;
  /** Host-computed many-to-one count — never persisted. `>= 2` composes
   * `PortCountBadge` as the secondary slot's default content, unchanged
   * threshold from before the two-slot proposal. */
  producers?: number;
  /**
   * The label slot's placement, reaching PAST `textLayout` (which is the
   * Simple-tier PRESET over exactly these three — Zach, 2026-09-15:
   * "thoose are just presets!"). Omit any of them and the preset decides;
   * set one and it wins. `offsetX` is + away from the dot along the
   * origin's own axis, `offsetY` is + DOWN, and both may be negative.
   */
  labelOrigin?: SlotOrigin;
  /** Which part of the slot lands on the origin's line — the reference
   *  edge. `end` on a side origin is what makes 'clear of the trace wire'
   *  a static offset instead of one derived from the label's height. */
  labelAlign?: SlotAlign;
  labelOffsetX?: number;
  labelOffsetY?: number;
  /** The secondary slot's placement — the SAME three controls over the
   *  SAME `SlotOrigin` type, with `secondarySlotLayout` as its preset. */
  secondaryOrigin?: SlotOrigin;
  secondaryAlign?: SlotAlign;
  secondaryOffsetX?: number;
  secondaryOffsetY?: number;
  /**
   * Content for the LABEL position, supplied by a host that owns its own
   * slot model (the /create bench's `ctx.slots.label`). When present it
   * REPLACES the built-in `PortLabel`/`CodeField` — same position, same
   * lift — so the label's text can be an ordinary, deletable member of a
   * real slot rather than a string this component owns (Zach, 2026-09-15:
   * "even the text is just a member in the label slot that can be
   * deleted"). Absent means the built-in field, which is what every
   * prop-only host still uses: the tldraw/React Flow adapters, blockFace,
   * and Storybook all compose `Port` from flat props and have no instance
   * tree to build a slot out of.
   */
  labelSlot?: ReactNode;
  /**
   * Content for the SECONDARY position, same contract as `labelSlot`.
   * Present — INCLUDING empty — beats the built-in `producers >= 2` count
   * badge, which is the fallback for prop-only hosts only.
   */
  secondarySlot?: ReactNode;
  /**
   * Host layout fact, never persisted (same status as `dimmed`) — do NOT
   * add this to `port.fields.ts`. When true, `Port` renders the dot as its
   * OWN box with the label placed out of flow at the shared wall anchor,
   * instead of the flex dot+label pairing — see this file's own module doc:
   * a wall-mounted port positions `PortDot`/`PortLabel` independently, never
   * as one flex box, because the flex pairing made a card's centering
   * depend on its label's width (measured live on the /create bench: the
   * `in` dot sat 2.5px inside the wall, `cfg` 3px outside, `out` 25.3px
   * outside, all three on the SAME wall). Anchored mode makes the port's
   * box the dot, so centering the card centers the dot.
   */
  anchored?: boolean;
  /** Where that default `PortCountBadge` (or, with `producers < 2`,
   * nothing) sits. Omit for the AUTO default — the corner opposite
   * wherever the label is actually flowing (`defaultSecondarySlotLayout`,
   * port.layout.ts). */
  secondarySlotLayout?: SecondarySlotLayout;
  /** No caret, no edits on the label's `CodeField` — see `PortLabelProps`. */
  disabled?: boolean;
  /** Fired on every keystroke of the label's `CodeField` — see
   * `PortLabelProps.onLabelWrite`'s own doc for what an unwired field does. */
  onLabelWrite?(value: string): void;
  /** Shown in the label's `CodeField` when `children` is empty. */
  placeholder?: string;
}

/**
 * Port = the dot, the label, paired as flex siblings for a standalone
 * specimen (Storybook, the product inspector, a detached copy) — a real
 * host instead positions `PortDot`/`PortLabel` independently, at a
 * shared anchor, per `./port.layout.ts`. `hidden` renders nothing at all,
 * same as its `PortDot`/`PortLabel` parts.
 *
 * `lens`/`lensBefore` (the diff/lint overlay, `./appearance.ts`) are
 * accepted and exposed as `data-lens` for a host to style, but T1 does
 * not itself define lens paint tokens (docs/T1-SPEC.md §3 covers only
 * `state`/`tone`) — wiring a concrete lens treatment is left to whichever
 * component's board evidence calls for it first, same status as every
 * other bundle field with no board-driven paint yet.
 *
 * `size` (2026-09-11) is the cascading rung `diameter`/`textSize` resolve
 * through — see the `resolveField` calls in the body below and
 * `port.presets.ts`'s own `PORT_PRESETS`.
 */
export function LabeledPort({
  direction = "input",
  edge = "left",
  // `size` DOES take a real JS default ("md", matching `state`/`tone`
  // above) — it is the cascade's SELECTOR, and a selector must always
  // have a value for a preset to match against. `diameter`/`textSize`
  // deliberately do NOT (mirroring `pill.tsx`'s own paint fields): an
  // explicit value is exactly what makes their OVERRIDE candidate present
  // in `resolveField` below, so a caller reaching past `size` reads
  // honestly instead of every Port carrying a materialized diameter/
  // textSize that silently outranks the preset layer.
  size = "md",
  diameter,
  textLayout,
  textSize,
  state = "empty",
  tone = "neutral",
  lens = "normal",
  lensBefore: _lensBefore = "",
  hidden = false,
  dimmed = false,
  hinting = false,
  reveal = "always",
  producers = 0,
  anchored = false,
  labelOrigin,
  labelAlign,
  labelOffsetX,
  labelOffsetY,
  secondaryOrigin,
  secondaryAlign,
  secondaryOffsetX,
  secondaryOffsetY,
  labelSlot,
  secondarySlot,
  secondarySlotLayout,
  disabled = false,
  onLabelWrite,
  placeholder,
  className,
  style,
  children = "",
  ...props
}: LabeledPortProps) {
  if (hidden) return null;
  const resolvedTextLayout = textLayout ?? inwardTextLayout(edge);
  // `size` cascades `diameter`/`textSize` together through the SAME
  // cascade the product inspector's trace panel reads — never a
  // hand-written `size === "xl" ? ... : ...` beside it (`pill.tsx`'s own
  // `resolveField` calls are the precedent). The subject carries the
  // RAW `diameter`/`textSize` (undefined unless a caller passed one), so
  // an explicit prop reaches past `size` honestly instead of always
  // winning by construction.
  const sizeSubject = { size, diameter, textSize };
  const diameterResolved = resolveField(DIAMETER_FIELD, sizeSubject, PORT_PRESETS)
    .resolved as PortSize;
  const textSizeResolved = resolveField(TEXT_SIZE_FIELD, sizeSubject, PORT_PRESETS)
    .resolved as PortTextSize;
  const diameterPx =
    typeof diameterResolved === "number" ? diameterResolved : PORT_DIAMETERS[diameterResolved];
  // `anchored`: the root box IS the dot (no flex pairing) — see PortProps's
  // own doc for why. The label goes out of flow, placed by the same
  // `portLabelPlacement` geometry every wall surface already uses.
  // The label's lift for an "Offset" layout, 0 otherwise — see
  // `SlotAlign`'s own WHY (port.layout.ts). Both branches below need
  // it, so it is resolved once against the SAME dot box either would use.
  // Which corner the secondary slot hugs — the AUTO default is the side
  // opposite wherever the label is flowing. Resolved HERE now that the
  // composite owns the slot; the geometry primitive has no idea a label
  // or a second slot exists.
  const resolvedSecondaryLayout = secondarySlotLayout ?? defaultSecondarySlotLayout(resolvedTextLayout);
  // ── Each slot's placement, resolved once ────────────────────────────
  //
  // The named layout is the PRESET; an explicit origin/offset reaches past
  // it. `textLayout` still carries the preset because it is what every
  // host and every saved tldraw shape already speaks — this resolution is
  // the single place that vocabulary is translated into the unified
  // (origin, x, y) model (`TEXT_LAYOUT_AS_PLACEMENT`, port.layout.ts).
  const textLayoutPreset = TEXT_LAYOUT_AS_PLACEMENT[resolvedTextLayout];
  // The lifted default is computed from the LIVE text size, never frozen:
  // a lift correct at `md` puts an `xl` label's bottom edge back below the
  // centre line, with the wire cutting through it (see `SlotAlign`).
  const labelPlacement: SlotPlacement = {
    origin: labelOrigin ?? textLayoutPreset.origin,
    align: labelAlign ?? textLayoutPreset.align,
    offsetX: labelOffsetX ?? 0,
    offsetY: labelOffsetY ?? textLayoutPreset.offsetY,
  };
  const secondaryPlacement: SlotPlacement = {
    origin: secondaryOrigin ?? SECONDARY_LAYOUT_AS_ORIGIN[resolvedSecondaryLayout],
    align: secondaryAlign ?? "center",
    offsetX: secondaryOffsetX ?? 0,
    offsetY: secondaryOffsetY ?? 0,
  };
  // The flex row still needs a scalar LIFT: a transform does not grow the
  // row, and a standalone specimen's box must contain what it paints.
  // Upward displacement only — a downward one needs no headroom above.

  // A host-given `secondarySlot` WINS outright — INCLUDING when it is
  // empty, which is what makes the count badge deletable (Zach,
  // 2026-09-15: "yes the producer badge can be delted it just a member of
  // the slot"). The `producers >= 2` badge is only the fallback for a
  // prop-only host that never supplied a slot at all (the adapters,
  // blockFace, Storybook), so `undefined` and "the slot exists and is
  // empty" stay distinguishable — a `??` here would have resurrected the
  // badge the moment someone emptied it.
  //
  // WHY hoisted out of the JSX attribute it used to live in: written
  // inline it was a nested ternary whose middle arm is a self-closing
  // element, and SWC reads the `/>` that follows a `?` as the start of a
  // regex literal ("Unterminated regexp literal", whole page 500).
  // TypeScript's own parser accepts it, so `tsc` stayed green and only
  // running the real app caught it.
  const resolvedSecondarySlot: ReactNode =
    secondarySlot !== undefined
      ? secondarySlot
      : producers >= 2
        ? <PortCountBadge count={producers} />
        : undefined;
  // The label POSITION's geometry, resolved once and worn by whichever
  // content occupies it — the built-in `PortLabel` or a host's own
  // `labelSlot`. Sharing the one object is what stops a slot from drifting
  // out of alignment with the CodeField it replaces.
  // The flex row's half of the placement. `flexDirection` + `gap` already
  // put the label at its ORIGIN (flush, centred on the cross axis) — the
  // offsets are then the same translate the anchored path emits, so both
  // paths displace by the identical rule and cannot drift apart.
  //
  // WHY a transform rather than the old `alignItems: flex-end` +
  // `marginBottom` pair: a margin RESIZES the row, so the same offset
  // meant two different things depending on which path drew it, and only
  // one direction (up) was expressible at all. A displacement should move
  // the label, not resize the port — and a transform is the one mechanism
  // that says exactly that, in both directions, in both paths.
  const labelSlotStyle: CSSProperties | undefined = anchored
    ? { ...slotPlacementStyle(labelPlacement, { w: diameterPx, h: diameterPx }, PORT_LABEL_GAP), whiteSpace: "nowrap" }
    : flexOffsetTransform(labelPlacement);
  const rootStyle: CSSProperties = anchored
    ? { position: "relative", width: diameterPx, height: diameterPx }
    : {
        // The RESOLVED origin, not the preset — so the Expert control
        // actually moves the label in this path too.
        flexDirection: originFlexDirection(labelPlacement.origin),
        // + PORT_RING_OVERHANG_PX: the gap is measured from the flex box's
        // edge, but the ring paints PAST it (box-shadow, not a border) — see
        // port.layout.ts's own WHY. Without this a flex-flowed specimen and
        // a wall-anchored label (which goes through `portLabelOut`) disagree
        // by the ring's overhang.
        gap: PORT_LABEL_GAP + PORT_RING_OVERHANG_PX,
      };
  return (
    <div
      data-slot="port"
      data-state={state}
      data-direction={direction}
      data-edge={edge}
      data-size={size}
      data-text-layout={resolvedTextLayout}
      data-lens={lens !== "normal" ? lens : undefined}
      className={cn(
        "flex w-fit items-center",
        // The skin's font, for the same reason `Block` carries it: a Port
        // mounted on a Block wall inherits it from that Block, but a
        // STANDALONE Port has no Block above it, so the sketch capture
        // showed the board's "sensor bus" label still in the UI font while
        // every wall-mounted label had gone hand-drawn. Nothing else about
        // a Port is skinned — the dot stays `rounded-full` at
        // `--bbox-skin-stroke-width`'s fixed 2px, because a circle at a
        // measured anchor is what a Port IS.
        "font-[family-name:var(--bbox-skin-font,inherit)]",
        // `reveal: "onHover"` composes opacity, not colour, over whichever
        // resting state is in force — a visibility policy triggered by the
        // CONTAINER's view, kept deliberately apart from `dimmed`
        // (painted-but-faded, triggered by what the HOST is doing to this
        // port). Standing in for "the container is hovered" with
        // self-hover, since a standalone specimen has no outer container
        // to key off.
        REVEAL_CLASS[reveal],
        className,
      )}
      style={{ ...rootStyle, ...style }}
      {...props}
    >
      {/* The GEOMETRY, wrapped only when it has a secondary slot to carry.
          The wrapper is the dot's own box exactly (same width/height), so
          the slot's `right: 100%`-style offsets resolve against the same
          rectangle they did when `Port` still rendered the slot itself —
          the pixels do not move, only which component owns the concern.
          With no slot content there is no wrapper at all, so a bare
          LabeledPort's DOM is the dot and the label, nothing extra. */}
      {resolvedSecondarySlot != null ? (
        <span
          data-slot="port-geometry"
          className="relative inline-flex shrink-0"
          style={{ width: diameterPx, height: diameterPx }}
        >
          <Port
            state={state}
            tone={tone}
            diameter={diameterResolved}
            hidden={hidden}
            dimmed={dimmed}
            hinting={hinting}
          />
          <span
            data-slot="port-secondary-slot"
            className="pointer-events-none absolute"
            style={slotPlacementStyle(secondaryPlacement, { w: diameterPx, h: diameterPx }, PORT_SECONDARY_SLOT_GAP_PX)}
          >
            {resolvedSecondarySlot}
          </span>
        </span>
      ) : (
        <Port
          state={state}
          tone={tone}
          diameter={diameterResolved}
          hidden={hidden}
          dimmed={dimmed}
          hinting={hinting}
        />
      )}
      {labelSlot !== undefined ? (
        // A host-supplied label slot replaces the built-in CodeField
        // entirely, taking its position and its lift. Same
        // present-beats-absent rule as `secondarySlot` above, for the same
        // reason: an emptied label slot must stay empty.
        <span
          data-slot="port-label-slot"
          className={anchored ? "absolute" : undefined}
          style={labelSlotStyle}
        >
          {labelSlot}
        </span>
      ) : (
      <PortLabel
        direction={direction}
        textSize={textSizeResolved}
        hidden={hidden}
        className={anchored ? "absolute" : undefined}
        style={labelSlotStyle}
        disabled={disabled}
        onLabelWrite={onLabelWrite}
        placeholder={placeholder}
      >
        {children}
      </PortLabel>
      )}
    </div>
  );
}

/**
 * packages/bbox-ui/src/portEdge.fields.ts
 *
 * `PortEdge`'s controllable props as data — the declaration half of the
 * schema-driven loop (T0's pattern, generalized in T1). Every `id` below
 * is a REAL `PortEdgeProps` key (see `./portEdge.tsx`); `readFields`/
 * `toArgTypes` look subjects up by that key directly.
 *
 * No `APPEARANCE_FIELDS`, no presets: `PortEdge` paints nothing besides
 * its own `+N more` disclosure text (T1-SPEC.md §4.6) — `PORT_EDGE_PRESETS`
 * is the empty-array shape every consumer (the generic story generator,
 * the generic inspector) can still `.map()` over without a null check.
 */
import type { FieldOption, FieldSpec, PresetSpec } from "./schema";

import {
  BLOCK_SIDES,
  BLOCK_SIDE_LABELS,
  PORT_TEXT_LAYOUTS,
  PORT_TEXT_LAYOUT_LABELS,
} from "./port.layout";

/**
 * DEVIATION from T1-SPEC.md §4.6's own text ("BlockSide, from the frozen
 * layout.ts — unchanged, generic"): the real, landed `port.layout.ts`
 * re-declares `BlockSide` itself (`BLOCK_SIDES`/`BLOCK_SIDE_LABELS`
 * alongside it) — the same "one deliberate constant duplication" pattern
 * `port.layout.ts`'s own file banner already documents for
 * `BLOCK_BORDER_PX`. §0's master export-lifetime list also names
 * `BlockSide` as one of the exports that dies from `layout.ts` once
 * `port.layout.ts` lands. Importing the frozen `layout.ts` copy here
 * would therefore import an export Integration is going to delete out
 * from under this file; the source (and §0) wins over §4.6's own prose.
 */
const EDGE_OPTIONS: FieldOption[] = BLOCK_SIDES.map((side) => ({
  value: side,
  label: BLOCK_SIDE_LABELS[side],
}));

/** Not `PortEdgeLayout`-shared with anything else — this component's own
 * two distribution modes. */
export type PortEdgeLayout = "evenly" | "custom";

const LAYOUTS: PortEdgeLayout[] = ["evenly", "custom"];

const LAYOUT_LABELS: Record<PortEdgeLayout, string> = {
  evenly: "Evenly",
  custom: "Custom",
};

const LAYOUT_OPTIONS: FieldOption[] = LAYOUTS.map((layout) => ({
  value: layout,
  label: LAYOUT_LABELS[layout],
}));

const TEXT_LAYOUT_OPTIONS: FieldOption[] = PORT_TEXT_LAYOUTS.map((layout) => ({
  value: layout,
  label: PORT_TEXT_LAYOUT_LABELS[layout],
}));

/**
 * `PortEdge`'s four controllable props, in the order a panel should draw
 * them. Every `defaultValue` equals that prop's real default in
 * `portEdge.tsx` — `test/portEdge.fields.test.ts` pins this — with one
 * documented exception (`textLayout`, below).
 */
export const PORT_EDGE_FIELDS: FieldSpec[] = [
  {
    id: "edge",
    label: "Edge",
    kind: "segments",
    defaultValue: "left",
    options: EDGE_OPTIONS,
  },
  {
    id: "layout",
    label: "Layout",
    kind: "segments",
    defaultValue: "evenly",
    options: LAYOUT_OPTIONS,
    hint: "\"custom\" leaves per-port offsets to the host (inline style / dnd-kit transform) — PortEdge applies no distribution of its own.",
  },
  {
    id: "textLayout",
    label: "Text Layout",
    kind: "segments",
    // NOTE (deviation, see T1-SPEC.md §4.6): PortEdge's real default for
    // this field is not a static value — it's `inwardTextLayout(edge)`
    // (`./port.layout`), so it tracks whichever `edge` is actually in
    // force. "right" is only that function's value AT this table's own
    // default, `edge:"left"`. A child `<Port>` that sets its own
    // `textLayout` always wins over this cascade value; PortEdge only
    // fills the gap on children that didn't set one.
    defaultValue: "right",
    options: TEXT_LAYOUT_OPTIONS,
    hint: "Cascades to any child Port that didn't set its own textLayout. Real default is inwardTextLayout(edge), not a fixed value.",
  },
  {
    id: "hiddenCount",
    label: "Hidden Count",
    kind: "number",
    defaultValue: 0,
    min: 0,
    step: 1,
    hint: "Host/document-supplied — PortEdge cannot see which ports are hidden or why; it only renders the trailing \"+N more\" row.",
  },
];

/** `PortEdge` governs nothing through the preset layer — see this file's
 * own top comment. */
export const PORT_EDGE_PRESETS: PresetSpec[] = [];

import {
  Children,
  cloneElement,
  Fragment,
  isValidElement,
  type ComponentProps,
  type ReactElement,
  type ReactNode,
} from "react";

import { cn } from "./lib/utils";
// WHY imported from `./port.layout`, not the frozen `./layout`: the real,
// landed `port.layout.ts` re-declares `BlockSide` itself, and §0's master
// export-lifetime list names `BlockSide` as one of the exports Integration
// deletes from `layout.ts` once this file lands — see portEdge.fields.ts's
// own deviation note for the full reasoning.
import { inwardTextLayout, type BlockSide, type PortTextLayout } from "./port.layout";
import type { PortEdgeLayout } from "./portEdge.fields";

/**
 * Which way the lane runs along a given wall: a left/right wall is
 * vertical, so its ports stack top-to-bottom; a top/bottom wall is
 * horizontal, so its ports run left-to-right. Order within `children` is
 * render order along the edge (T1-SPEC.md §4.6) — this function only
 * decides the axis, never a reversal.
 */
function edgeFlexDirection(edge: BlockSide): "column" | "row" {
  return edge === "left" || edge === "right" ? "column" : "row";
}

/**
 * Hand `textLayout` down to every Port inside the lane, looking THROUGH
 * Fragments on the way.
 *
 * WHY the recursion: a Fragment satisfies `isValidElement`, so a flat
 * `Children.map` + `cloneElement` put the prop on the Fragment itself, where
 * React warns in dev and no Port ever saw it. Only `demos/inspector` wraps
 * its ports in a Fragment; the Storybook gallery wraps them in a real
 * `ThreePorts` component instead, which this function deliberately does NOT
 * look through (see that component's own comment) — a component boundary
 * stops the cascade there by design, a Fragment stops it by omission.
 *
 * A Port that sets its own `textLayout` still wins, because the cascade is
 * only applied when the child's own prop is undefined.
 *
 * `anchored`, when passed, is stamped the same way `textLayout` is (never
 * overriding a component's own explicit value) — the lane-drawn `PortCard`
 * (panel's `portEdges/contract.tsx`) passes `true` so the port it carries
 * renders with the dot as its own box, matching the wall-anchor geometry
 * the lane already centers on. `PortEdge`'s own internal call stays
 * two-argument; only a host that needs anchored ports reaches for the
 * third parameter.
 *
 * WHY hosts are looked THROUGH and never stamped (2026-09-12): on /create a
 * lane's children are `<span data-slot="port-group">` → `<DraggablePort>` →
 * `<Port>`, and the old rule stamped the span — React's "does not recognize
 * the `textLayout` prop on a DOM element" on every Block bench, while the
 * Port underneath never saw the lane's layout at all, so a port on the top
 * edge still wrote its label to the right and neighbours overlapped. A host
 * element cannot take the prop; a component can (a Port consumes it, the
 * gallery's `ThreePorts` forwards it, a wrapper simply ignores it), so
 * components are stamped AND recursed into by their `children`. Context
 * would pass through anything, but Port is deliberately callable as a plain
 * function so its tests can read real defaults off the returned tree, and a
 * hook would end that.
 */
export function cascadeInto(
  children: ReactNode,
  textLayout: PortTextLayout,
  anchored?: boolean,
): ReactNode {
  // Nothing to cascade INTO: hand the value back exactly as given.
  //
  // WHY this guard, and why here rather than at the consumer: the recursion
  // above cannot tell a WRAPPER's children (more elements, worth descending
  // into) from a LEAF's children (its own text). `Children.map` normalises
  // whatever it is handed into an ARRAY, so a bare `<Port>cfg</Port>` came
  // back out of `cloneElement` carrying `children: ["cfg"]` — a one-element
  // array where the component's contract says string. That was inert while
  // a label was only ever rendered, and became a hard crash the moment
  // `PortLabel` grew a real CodeField: `codeField.tsx` hands `value`
  // straight to CodeMirror's `EditorState.create`, which calls
  // `(config.doc || "").split(…)` and dies on an array. Whole /create page,
  // white screen, for every Block and PortEdges bench.
  //
  // Coercing in `PortLabel` instead would have hidden the real fact — that
  // EVERY component in a lane has its text children silently re-wrapped.
  // TextBox was already degrading quietly on the same bug (its
  // `typeof children === "string"` guards fail closed, losing inline
  // editing with no error); Pill and Glyph happen to render an array
  // identically and showed nothing at all.
  if (!Children.toArray(children).some(isValidElement)) return children;
  return Children.map(children, (child) => {
    if (!isValidElement(child)) return child;
    if (child.type === Fragment) {
      const fragment = child as ReactElement<{ children?: ReactNode }>;
      return cascadeInto(fragment.props.children, textLayout, anchored);
    }
    const element = child as ReactElement<{
      textLayout?: PortTextLayout;
      anchored?: boolean;
      children?: ReactNode;
    }>;
    const isHost = typeof element.type === "string";
    const hasChildren = element.props.children !== undefined && element.props.children !== null;
    const nextChildren = hasChildren
      ? cascadeInto(element.props.children, textLayout, anchored)
      : undefined;
    if (isHost) return hasChildren ? cloneElement(element, undefined, nextChildren) : element;
    const props = {
      textLayout: element.props.textLayout ?? textLayout,
      ...(anchored !== undefined ? { anchored: element.props.anchored ?? anchored } : {}),
    };
    return hasChildren ? cloneElement(element, props, nextChildren) : cloneElement(element, props);
  });
}

export interface PortEdgeProps extends ComponentProps<"div"> {
  edge?: BlockSide;
  layout?: PortEdgeLayout;
  /**
   * Cascades to any child that doesn't set its own `textLayout`. Omit it
   * and PortEdge derives a sensible one from `edge` itself
   * (`inwardTextLayout`) — see `portEdge.fields.ts`'s own `textLayout`
   * field comment for why the FieldSpec's static default can't express
   * that.
   */
  textLayout?: PortTextLayout;
  /**
   * Host/document-supplied. Never computed by PortEdge inspecting its own
   * `children` — which ports are hidden and why is document/data-model
   * state this component structurally cannot see (T1-SPEC.md §4.6).
   */
  hiddenCount?: number;
}

/**
 * A flex lane along one wall of a `Block`, holding real `<Port>` elements
 * as children. Answers which wall (`edge`) and how the lane distributes
 * its children (`layout`); cascades a default label placement to any
 * child that didn't set its own; can append a `+N more` disclosure row.
 *
 * WHY no `onReorder`: the reorder gesture belongs to the HOST (dnd-kit),
 * not to this component — PortEdge lays children out, it does not let
 * you drag them. See T1-SPEC.md §4.6's own "not a prop" list.
 */
export function PortEdge({
  edge = "left",
  layout = "evenly",
  textLayout,
  hiddenCount = 0,
  className,
  style,
  children,
  ...props
}: PortEdgeProps) {
  const cascadeTextLayout = textLayout ?? inwardTextLayout(edge);
  return (
    <div
      data-slot="port-edge"
      data-edge={edge}
      data-layout={layout}
      className={cn(
        "flex",
        edgeFlexDirection(edge) === "column" ? "flex-col" : "flex-row",
        layout === "evenly" && "justify-evenly",
        className,
      )}
      style={style}
      {...props}
    >
      {cascadeInto(children, cascadeTextLayout)}
      {hiddenCount > 0 && (
        <span
          data-slot="port-edge-more"
          className="whitespace-nowrap text-xs text-muted-foreground"
        >
          +{hiddenCount} more
        </span>
      )}
    </div>
  );
}

/**
 * packages/bbox-ui/src/portPlacement.ts
 *
 * The zero-dependency placement model for a Block's Ports, per Zach's
 * 2026-09-12 ruling: a Block owns its Ports; a Block has n Arrangements
 * (states, minimum one "default"); each Arrangement has a mode (auto |
 * custom), a set of live edges, and optionally one grouping set. Each Port
 * stores, PER ARRANGEMENT, a `Placement` — both `order` and `t` are always
 * stored (never only one), because which one is authoritative flips with
 * mode: in auto, `order` is the truth and `t` is refreshed from the
 * closed-form even-spacing formula on every change (so flipping to custom
 * never jumps a card); in custom, `t` is the truth and `order = rank(t)` is
 * refreshed on every drop (so flipping back to auto reflows to the order
 * you left).
 *
 * This module ports the math verified in `demos/dndkit-lab/src/layout.ts`
 * (`mainAxisPositions`) and `demos/dndkit-lab/src/grouping.ts`
 * (`computeSlots`/`resolveAssignment`) into that per-Port, per-arrangement
 * placement record — it does not reinvent that behaviour.
 *
 * Zero-dependency discipline, matching `packages/schema`: no React, no DOM,
 * no host (tldraw / React Flow / dnd-kit) imports. The one import is a
 * type-only pull of `BlockSide` from `./port.layout`, erased at compile
 * time under `isolatedModules` — it carries no runtime dependency.
 */
import type { BlockSide } from "./port.layout";

export type PortEdgeId = BlockSide;

export type ArrangementMode = "auto" | "custom";

/**
 * The three CSS-flexbox-shaped spacing schemes `evenT` reproduces as plain
 * fractions — named after what they mean here (a value 0..1 along one
 * edge), not after the lab's `space-between` / `space-evenly` /
 * `space-around` CSS keywords, since there is no flex container or card
 * size at this layer, only points on a line.
 */
export type SpacingScheme = "between" | "evenly" | "around";

/**
 * One assignment set a Block can apply to its Ports for one Arrangement.
 * A port missing from `assignments` is its own singleton group — Zach's
 * "if no id, then is X id" rule, carried over from
 * `demos/dndkit-lab/src/grouping.ts`'s `resolveAssignment`.
 */
export interface GroupingSet {
  id: string;
  label: string;
  collapsed: boolean;
  assignments: Record<string, { group: string; groupOrder?: number }>;
}

export type AlignAnchor = "start" | "end";

/**
 * A purely presentational override on top of `spacing`: pack cards from one
 * end of the lane with an explicit px gap, plus an extra px push-in from
 * that same anchor (`edgePaddingPx`) — the mechanism behind the Inline/
 * Offset port layouts (`PROJECT - Black Box UI.md`, 2026-09-12): give the
 * offset edge a non-zero `edgePaddingPx` and its pack starts further in than
 * the inline edge's.
 *
 * Deliberately read ONLY by the render layer (`packages/panel/src/
 * portEdges/contract.tsx`'s `LaneBox`) — never by `evenT`/`refresh` here,
 * which keep deriving `t` from `spacing` exactly as they did before `align`
 * existed. That is a considered trade-off, not an oversight: `t` is this
 * module's length-agnostic fraction (see this file's header), while a gap
 * or padding in real px only means something once a lane has an actual
 * rendered length — a fact this zero-dependency module never has and must
 * not acquire. The cost is that `t` isn't pixel-exact to what's on screen
 * while `align` is active; the only place that would show is switching this
 * arrangement to Custom mode, where a port lands close to (not exactly at)
 * its aligned position — a minor one-time cosmetic settle, not a bug this
 * module's existing continuity tests need to (or do) cover.
 */
export interface AlignConfig {
  anchor: AlignAnchor;
  gapPx: number;
  edgePaddingPx: number;
}

export interface Arrangement {
  id: string;
  label: string;
  mode: ArrangementMode;
  spacing: SpacingScheme;
  /** The live edges for THIS arrangement. Order is not meaningful — see
   * `ALL_EDGES` for the canonical clockwise order everything else walks. */
  edges: PortEdgeId[];
  grouping?: GroupingSet;
  /** Optional "aligned to edge" packing — see `AlignConfig`'s own doc. */
  align?: AlignConfig;
}

/**
 * One Port's placement within ONE Arrangement. `order` and `t` are BOTH
 * always populated (see this file's header) — which one is live truth
 * depends on the owning Arrangement's `mode`, not on which fields happen
 * to be set.
 */
export interface Placement {
  edge: PortEdgeId;
  order: number;
  t: number;
  group?: string;
  groupOrder?: number;
}

/** One Arrangement's placements, keyed by port id. The page keeps one of
 * these per Arrangement per Block — this module never holds more than one
 * at a time, so it never needs to know a Block's or a Port's identity. */
export type Placements = Record<string, Placement>;

/** Canonical clockwise order, starting at top — the order `drawnEdge`
 * walks to find where a parked port should render, and the order
 * `toggleEdge` normalizes `edges` into. */
export const ALL_EDGES: PortEdgeId[] = ["top", "right", "bottom", "left"];

export const DEFAULT_ARRANGEMENT: Arrangement = {
  id: "default",
  label: "Default",
  mode: "auto",
  spacing: "evenly",
  edges: ALL_EDGES,
};

function clampUnit(value: number): number {
  return Math.min(1, Math.max(0, value));
}

function clampIndex(index: number, length: number): number {
  return Math.min(length, Math.max(0, index));
}

/**
 * The lab's `mainAxisPositions` (see `demos/dndkit-lab/src/layout.ts`)
 * expressed as fractions 0..1 along an edge, with no card size (a port is
 * a point, not a box) — so `free` is always the whole edge and the three
 * schemes reduce to these closed forms. `count === 1` is a deliberate
 * override to 0.5 for every scheme (not just the two non-`between` ones,
 * as the lab special-cases it): a single port centered on its edge is
 * always the right call, and `i / (n - 1)` is undefined at n = 1 anyway.
 */
export function evenT(count: number, spacing: SpacingScheme): number[] {
  if (count <= 0) return [];
  if (count === 1) return [0.5];
  switch (spacing) {
    case "between":
      return Array.from({ length: count }, (_, i) => i / (count - 1));
    case "evenly":
      return Array.from({ length: count }, (_, i) => (i + 1) / (count + 1));
    case "around":
      return Array.from({ length: count }, (_, i) => (i + 0.5) / count);
  }
}

/**
 * The placement a newly created port gets: parked on the arrangement's
 * first live edge (in canonical clockwise order, not array-insertion
 * order — `edges` carries no ordering guarantee of its own), appended
 * after whatever is already stored on that edge. `t` starts at 0; auto
 * mode refreshes it to the real even-spacing value on the very next
 * `refresh()`, and custom mode leaves new ports stacked at the start
 * until dragged, which is the same "arrives at 0, gets moved" behaviour
 * every other custom-mode port has.
 */
export function defaultPlacement(
  portId: string,
  arrangement: Arrangement,
  existing: Placements,
): Placement {
  const edge = ALL_EDGES.find((e) => arrangement.edges.includes(e)) ?? arrangement.edges[0] ?? "top";
  const order = Object.values(existing).filter((p) => p.edge === edge).length;
  return { edge, order, t: 0 };
}

/**
 * Where a placement actually DRAWS: its stored edge if that edge is live
 * in this arrangement, else the nearest live edge walking clockwise
 * (top → right → bottom → left → top …) from the stored edge — never the
 * stored placement itself, which is untouched (an edge toggled back on
 * must find every port it lost exactly where it left them). If no edge
 * is live at all (a degenerate arrangement), the stored edge is returned
 * as the only thing left to draw.
 */
export function drawnEdge(placement: Placement, arrangement: Arrangement): PortEdgeId {
  if (arrangement.edges.includes(placement.edge)) return placement.edge;
  const startIndex = ALL_EDGES.indexOf(placement.edge);
  for (let step = 1; step <= ALL_EDGES.length; step++) {
    const candidate = ALL_EDGES[(startIndex + step) % ALL_EDGES.length];
    if (arrangement.edges.includes(candidate)) return candidate;
  }
  return placement.edge;
}

/**
 * Port ids drawn on `edge` (after parking), in the order they render:
 * auto mode trusts `order` as-is; custom mode trusts `t`, falling back to
 * `order` only to break an exact tie (two ports can share a `t` mid-drag
 * before the next `refresh()` fans them back out).
 */
export function laneOrder(placements: Placements, arrangement: Arrangement, edge: PortEdgeId): string[] {
  const ids = Object.keys(placements).filter((id) => drawnEdge(placements[id], arrangement) === edge);
  if (arrangement.mode === "auto") {
    return ids.sort((a, b) => placements[a].order - placements[b].order);
  }
  return ids.sort((a, b) => {
    const byT = placements[a].t - placements[b].t;
    return byT !== 0 ? byT : placements[a].order - placements[b].order;
  });
}

/**
 * Re-derives whichever field is NOT the current mode's truth, per lane
 * (a lane is every drawn edge, including one a degenerate arrangement
 * parks everyone onto). Pure and idempotent: running it twice in a row on
 * its own output changes nothing, because each mode's derived field is a
 * stable function of the field it trusts.
 *
 * A locked id (the function port, at most one per Block — see
 * `lockedPlacement`) is skipped entirely: it neither gets reassigned nor
 * consumes a rank slot other ports are counted against, matching "never
 * draggable" — its corner placement is not part of the lane's spacing
 * math at all.
 */
export function refresh(placements: Placements, arrangement: Arrangement, locked?: Set<string>): Placements {
  const isLocked = locked ?? new Set<string>();
  const next: Placements = { ...placements };
  const edges = new Set<PortEdgeId>();
  for (const id of Object.keys(placements)) edges.add(drawnEdge(placements[id], arrangement));

  for (const edge of edges) {
    const ids = laneOrder(placements, arrangement, edge).filter((id) => !isLocked.has(id));
    if (arrangement.mode === "auto") {
      const ts = evenT(ids.length, arrangement.spacing);
      ids.forEach((id, i) => {
        next[id] = { ...next[id], order: i, t: ts[i] };
      });
    } else {
      ids.forEach((id, i) => {
        next[id] = { ...next[id], order: i };
      });
    }
  }
  return next;
}

/**
 * Moves one port to `edge` at the given index (auto) or `t` (custom,
 * clamped 0..1), then `refresh()`es so the rest of the lane — on both the
 * edge the port left and the edge it landed on — re-evens or re-ranks
 * around it. A locked port is returned completely unchanged, placements
 * object included (never even shallow-copied), matching "never
 * draggable".
 */
export function movePort(
  placements: Placements,
  arrangement: Arrangement,
  portId: string,
  edge: PortEdgeId,
  target: { index: number } | { t: number },
  locked?: Set<string>,
): Placements {
  if (locked?.has(portId)) return placements;
  const current = placements[portId];
  if (!current) return placements;

  if (arrangement.mode === "auto") {
    // WHY: laneOrder has no locked-awareness (it just draws the lane), so
    // without this filter a locked sibling sharing `edge` gets folded into
    // `sequence` below and has its own stored `order` overwritten — refresh()
    // then can't undo it, since refresh deliberately skips locked ids when
    // re-ranking (see refresh's own doc). Locked ports never occupy a rank
    // slot; excluding them here keeps that true for the port being moved too.
    const others = laneOrder(placements, arrangement, edge).filter(
      (id) => id !== portId && !locked?.has(id),
    );
    const index = "index" in target ? clampIndex(target.index, others.length) : others.length;
    const sequence = [...others.slice(0, index), portId, ...others.slice(index)];
    const next: Placements = { ...placements };
    sequence.forEach((id, i) => {
      next[id] = id === portId ? { ...current, edge, order: i } : { ...next[id], order: i };
    });
    return refresh(next, arrangement, locked);
  }

  const t = "t" in target ? clampUnit(target.t) : current.t;
  const next: Placements = { ...placements, [portId]: { ...current, edge, t } };
  return refresh(next, arrangement, locked);
}

/**
 * Switches an Arrangement's mode. Entering custom keeps whatever `t` is
 * already stored (auto's own `refresh()` kept it current on every prior
 * change, so nothing moves). Leaving custom re-derives `order` from
 * `rank(t)` first — by running `refresh()` under a `"custom"` copy of the
 * arrangement regardless of what `order` currently holds, so a stale
 * `order` can never leak through — then `refresh()`es again under
 * `"auto"` so `order` becomes the lane's new truth and `t` reflows to the
 * even-spacing closed form. Nothing jumps either direction.
 *
 * `locked` is threaded into BOTH `refresh()` passes, same as every other
 * mutator in this module (`movePort`) — a locked port shares a lane's edge
 * without being counted in that lane's rank/spacing math (see `refresh`'s
 * own doc). Omitting it here was the bug: the function port would get
 * ranked alongside real ports on its edge, corrupting their order and t
 * the moment an arrangement flipped custom -> auto.
 */
export function setMode(
  placements: Placements,
  arrangement: Arrangement,
  mode: ArrangementMode,
  locked?: Set<string>,
): { placements: Placements; arrangement: Arrangement } {
  if (mode === "custom") {
    return { placements, arrangement: { ...arrangement, mode: "custom" } };
  }
  const rankedByT = refresh(placements, { ...arrangement, mode: "custom" }, locked);
  const auto: Arrangement = { ...arrangement, mode: "auto" };
  return { placements: refresh(rankedByT, auto, locked), arrangement: auto };
}

/** Never removes the last live edge — returns the arrangement unchanged
 * instead, so a Block can never end up with nowhere to draw its ports.
 * Ports on that edge simply stay stored there and keep drawing parked
 * elsewhere via `drawnEdge` until another edge is turned on. */
export function toggleEdge(arrangement: Arrangement, edge: PortEdgeId, on: boolean): Arrangement {
  const has = arrangement.edges.includes(edge);
  if (on === has) return arrangement;
  if (!on && arrangement.edges.length <= 1) return arrangement;
  const nextSet = new Set(on ? [...arrangement.edges, edge] : arrangement.edges.filter((e) => e !== edge));
  return { ...arrangement, edges: ALL_EDGES.filter((e) => nextSet.has(e)) };
}

/** Appends a new Arrangement cloned from an existing one (or
 * `DEFAULT_ARRANGEMENT` if `copyOf` doesn't resolve) under a new id/label
 * — never mutates the source, including its nested `grouping` set. */
export function addArrangement(
  arrangements: Arrangement[],
  copyOf: string,
  id: string,
  label: string,
): Arrangement[] {
  const source = arrangements.find((a) => a.id === copyOf) ?? DEFAULT_ARRANGEMENT;
  const next: Arrangement = {
    ...source,
    id,
    label,
    edges: [...source.edges],
    grouping: source.grouping
      ? { ...source.grouping, assignments: { ...source.grouping.assignments } }
      : undefined,
  };
  return [...arrangements, next];
}

/** A structural copy of one Arrangement's Placements — every `Placement`
 * object is its own copy too, so mutating the clone can never leak back
 * into the source (a new Arrangement starts from a clone of the one it
 * was copied from, per `addArrangement`'s caller). */
export function clonePlacements(placements: Placements): Placements {
  const next: Placements = {};
  for (const id of Object.keys(placements)) {
    next[id] = { ...placements[id] };
  }
  return next;
}

/**
 * The lab's `computeSlots` (see `demos/dndkit-lab/src/grouping.ts`) for
 * one lane: with no grouping set, or an expanded one, every drawn port is
 * its own slot. A collapsed set clusters every port that resolves to the
 * same group (default: singleton = the port's own id) into one slot at
 * the first member's position — `portIds` lists every member (so a
 * caller can render the rest as a stacked/faded pile), sorted by the
 * set's own `groupOrder`.
 */
export function groupSlots(
  placements: Placements,
  arrangement: Arrangement,
  edge: PortEdgeId,
): { group: string; portIds: string[]; t: number }[] {
  const ids = laneOrder(placements, arrangement, edge);
  const grouping = arrangement.grouping;
  if (!grouping || !grouping.collapsed) {
    return ids.map((id) => ({ group: id, portIds: [id], t: placements[id].t }));
  }

  const resolve = (id: string) => grouping.assignments[id]?.group ?? id;
  const seen = new Set<string>();
  const slots: { group: string; portIds: string[]; t: number }[] = [];
  for (const id of ids) {
    const group = resolve(id);
    if (seen.has(group)) continue;
    seen.add(group);
    const members = ids
      .filter((memberId) => resolve(memberId) === group)
      .sort((a, b) => (grouping.assignments[a]?.groupOrder ?? 0) - (grouping.assignments[b]?.groupOrder ?? 0));
    slots.push({ group, portIds: members, t: placements[id].t });
  }
  return slots;
}

/** The function port's fixed placement: header-left corner, order 0,
 * `t` 0. Never computed from a lane — it is the one placement in the
 * whole model that is never subject to `refresh()`. */
export function lockedPlacement(): Placement {
  return { edge: "top", order: 0, t: 0 };
}

/**
 * packages/bbox-ui/src/region.fields.ts
 *
 * `Region`'s controllable props as data. `kind` (For/While/If) is its only
 * closed-vocabulary field; `width`/`height`/`radius` are plain geometry,
 * the same shape as `block.fields.ts`'s own `WIDTH_FIELD`/`HEIGHT_FIELD`/
 * `RADIUS_FIELD`. See `region.presets.ts` for why a Region has no `view`
 * selector of its own.
 */
import type { FieldSpec } from "./schema";

export const REGION_KINDS = ["for", "while", "if"] as const;
export type RegionKind = (typeof REGION_KINDS)[number];
export const REGION_KIND_LABELS: Record<RegionKind, string> = {
  for: "For",
  while: "While",
  if: "If",
};

export const REGION_KIND_FIELD: FieldSpec = {
  id: "kind",
  label: "Kind",
  kind: "segments",
  defaultValue: "for",
  options: REGION_KINDS.map((k) => ({ value: k, label: REGION_KIND_LABELS[k] })),
};

// Paired on one row, same discipline as WIDTH_FIELD/HEIGHT_FIELD's shared
// `group: "size"` — these two are one value (the region's box), not two
// fields that merely happen to be adjacent (`FieldSpec.group`'s own WHY,
// packages/schema/src/field.ts).
export const REGION_WIDTH_FIELD: FieldSpec = {
  id: "width",
  label: "Width",
  kind: "number",
  defaultValue: 560,
  unit: "px",
  group: "layout",
};

export const REGION_HEIGHT_FIELD: FieldSpec = {
  id: "height",
  label: "Height",
  kind: "number",
  defaultValue: 360,
  unit: "px",
  group: "layout",
};

export const REGION_RADIUS_FIELD: FieldSpec = {
  id: "radius",
  label: "Radius",
  kind: "number",
  defaultValue: 8,
  min: 0,
  max: 32,
  unit: "px",
};

export const REGION_FIELDS: FieldSpec[] = [
  REGION_KIND_FIELD,
  REGION_WIDTH_FIELD,
  REGION_HEIGHT_FIELD,
  REGION_RADIUS_FIELD,
];

import type { ComponentProps, ReactNode } from "react";

import { cn } from "./lib/utils";
import { SketchOutline } from "./sketchOutline";
import type { RegionKind } from "./region.fields";

/**
 * packages/bbox-ui/src/region.tsx
 *
 * Region = For / While / If: a bordered container with a real `Block`
 * (composed by the caller, in Port view) riding its top-left corner — see
 * `region.presets.ts` for why this is composition, not a second Block
 * preset. Kept deliberately austere (a border, a radius, a padded body):
 * core draws no edges of any kind (T1-SPEC.md §10), and nothing here
 * decides layout, connection, or containment rules for what a host places
 * inside it.
 */

const REGION_DEFAULT_WIDTH = 560;
const REGION_DEFAULT_HEIGHT = 360;
/** Kept as the documented default and as `RADIUS_FIELD`'s declared value;
 * `Region` itself no longer applies it, deferring to `--bbox-skin-radius`
 * (whose fallback is this same 8px) when the prop is unset. */
const REGION_DEFAULT_RADIUS = 8;

/** Region's own border stroke width — mirrors `layout.ts`'s
 * `BLOCK_BORDER_PX`: the corner Block's border must land exactly ON this
 * line for the shared corner to read as one continuous stroke. */
export const REGION_BORDER_PX = 2;
// WHY this is NOT `var(--bbox-skin-stroke-width)`: it is read as a LENGTH
// three lines below (`left: -REGION_BORDER_PX`) to position the corner
// Block, and `port.layout.ts`'s own `BLOCK_BORDER_PX` is read the same way
// to compute every wall-mounted port's anchor. Border width is geometry in
// this codebase, not paint — a skin that changed it would move ports out
// from under the host's edges. All three shipped skins therefore stroke at
// 2px; making that variable is real layout work, not a token. See the
// proposal's open decision D1.

/**
 * The corner Block's real, unscaled footprint — the SAME 192×173 the old
 * `scale(0.5)` hack produced (384×346 at half), kept as the default so
 * every existing caller sees an unchanged corner size. Exported so a
 * caller building the corner itself (bench.tsx's `REGION_SLOTS`) can size
 * that Block to match, honestly, rather than the region silently shrinking
 * whatever full-size Block it is handed.
 */
export const REGION_CORNER_SIZE = { width: 192, height: 173 };

export interface RegionProps extends Omit<ComponentProps<"div">, "children"> {
  kind?: RegionKind;
  width?: number;
  height?: number;
  radius?: number;
  /** The corner Block — absolutely positioned so it visually rides the
   * region's top-left corner, the way the wireframe draws it. Expected to
   * already be built at `cornerSize` (see `REGION_SLOTS`) — Region no
   * longer scales it down itself. */
  corner?: ReactNode;
  /** The corner's real footprint, for body clearance and flush alignment.
   * Defaults to `REGION_CORNER_SIZE`, the historical `scale(0.5)` size. */
  cornerSize?: { width: number; height: number };
  children?: ReactNode;
