"use client";

import type {
  ChangeEvent,
  ComponentProps,
  CSSProperties,
  FocusEvent,
  KeyboardEvent,
  ReactNode,
} from "react";
import { useEffect, useRef, useState } from "react";

import { cn } from "./lib/utils";
import {
  TEXT_BOX_FONT_STACKS,
  textBoxAlignItems,
  textBoxFontPx,
  textBoxJustifyContent,
  type TextBoxFont,
  type TextBoxHorizontalAlign,
  type TextBoxSize,
  type TextBoxVerticalAlign,
} from "./textBox.layout";

// WHY `Omit<..., "onChange">`: `ComponentProps<"div">` types `onChange` as a
// generic `ChangeEventHandler<HTMLDivElement>` (React's DOMAttributes types
// it on every element, though a plain div never actually fires one) — the
// contract's `onChange` is a value-carrying write-through callback, an
// incompatible shape. A div was never going to receive a real `onChange`
// event handler anyway, so overriding it costs nothing real.
export interface TextBoxProps extends Omit<ComponentProps<"div">, "onChange"> {
  size?: TextBoxSize;
  /** Font-size in px when `size === "custom"`; ignored otherwise. */
  sizePx?: number;
  paddingTop?: number;
  paddingBot?: number;
  paddingLeft?: number;
  paddingRight?: number;
  font?: TextBoxFont;
  align?: TextBoxVerticalAlign;
  justify?: TextBoxHorizontalAlign;
  /** Single ellipsized run, or a wrapping block. See `textBox.layout.ts`. */
  lines?: "single" | "multi";
  /**
   * Controlled; the host owns it. When true and `children` is a string, the
   * box renders the editing control instead of the text. When `children` is
   * not a string, `editing` is ignored (renders rest) — there is nothing to
   * type into. See docs/TEXTBOX-EDITING-SPEC.md §1.
   */
  editing?: boolean;
  /** Fires on every keystroke — write-through, like SystemSketch's `writeField`. */
  onChange?: (value: string) => void;
  /** Fires on Enter (single), Ctrl/Cmd+Enter (multi), or blur. */
  onCommit?: (value: string) => void;
  /** Fires on Escape. The host decides what reverting means. */
  onCancel?: () => void;
  /** Shown on the control, and at rest (muted, `data-placeholder`) when the text is empty. */
  placeholder?: string;
  /** The host may still pass `editing` while `readOnly` — the control just refuses input. */
  readOnly?: boolean;
  maxLength?: number;
}

type ControlElement = HTMLInputElement | HTMLTextAreaElement;

// WHY the box's own typography is inherited onto the control rather than
// recomputed: the whole point of an in-flow editing control (as opposed to
// an overlay) is that the text must not move — §4's journey measures the
// control's bounding box against the resting text's within 1px. Recomputing
// font-size/line-height/color/text-align independently would only coincide
// with the box's own values by luck the day someone changes one of them.
const CONTROL_TYPOGRAPHY_STYLE: CSSProperties = {
  font: "inherit",
  fontSize: "inherit",
  lineHeight: "inherit",
  color: "inherit",
  textAlign: "inherit",
  background: "transparent",
  margin: 0,
  padding: 0,
  border: 0,
  borderRadius: 0,
  // `fieldSizing` (Chromium 123+) is not yet in React's/TS's CSSProperties —
  // the cast is deliberate, not a typo. `min-width: 4ch` on the input (below)
  // and `rows={1}` on the textarea are the declared fallback for engines
  // that don't support it yet.
  ...({ fieldSizing: "content" } as CSSProperties),
};

/**
 * The editing control — a real `<input>`/`<textarea>` living IN-FLOW inside
 * the same box the resting text occupies (never an overlay). A fresh mount
 * every time the host flips `editing` to `true` (the element TYPE changes
 * from a span of text to a form control, so React remounts it for us) is
 * what makes the on-mount focus/selection effect below correct with an
 * empty dependency array — it is "on mount", not a missed dependency.
 */
function TextBoxControl({
  lines,
  value,
  placeholder,
  readOnly,
  maxLength,
  onChange,
  onCommit,
  onCancel,
}: {
  lines: "single" | "multi";
  value: string;
  placeholder?: string;
  readOnly: boolean;
  maxLength?: number;
  onChange?: (value: string) => void;
  onCommit?: (value: string) => void;
  onCancel?: () => void;
}) {
  // Two typed refs rather than one `ControlElement` ref cast onto whichever
  // element actually renders: `<input ref>` and `<textarea ref>` each want
  // their OWN element type, and only one of these two ever mounts per
  // render (`lines` picks the branch below), so the other simply stays null.
  const inputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [focused, setFocused] = useState(false);

  useEffect(() => {
    const el = lines === "single" ? inputRef.current : textareaRef.current;
    if (!el) return;
    el.focus();
    // WHY select-all vs caret-end rather than one rule for both: a single
    // line is almost always a short label a person means to REPLACE (select
    // all is the shadcn/OS-native rename idiom); a multi-line body is almost
    // always something a person means to CONTINUE (caret-end matches
    // clicking into a text area you're already writing in).
    if (lines === "single") {
      el.select();
    } else {
      const end = el.value.length;
      el.setSelectionRange(end, end);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleChange = (event: ChangeEvent<ControlElement>) => onChange?.(event.target.value);

  // WHY Escape is handled in the CAPTURE phase, on its own, and calls
  // `stopPropagation()` — the one key this file stops natively rather than
  // just calling its own callback: tldraw attaches ITS OWN Escape handling
  // with a raw `container.addEventListener("keydown", ...)` on
  // `.tl-container` (installed @tldraw/editor 5.3.2
  // useDocumentEvents.mjs:117-118, :188) — an ANCESTOR of this control in
  // every tldraw render. React defers its OWN (bubble-phase) synthetic
  // dispatch until the native event reaches the root node it delegates
  // from, which is an ancestor of `.tl-container` too — so tldraw's
  // container-level listener ALWAYS runs before this control's bubble
  // `onKeyDown` ever would. tldraw's handler calls `editor.cancel();
  // container.focus()`, and that `focus()` synchronously blurs this
  // control — `handleBlur` below fires `onCommit(current)` — before this
  // control's own Escape branch gets a chance to run, so Escape silently
  // COMMITTED the typed value instead of reverting it
  // (docs/TEXTBOX-EDITING-SPEC.md DoD step 5: "Escape cancels"). A
  // capture-phase handler on THIS element runs during React's simulated
  // CAPTURE pass (root-to-target, dispatched synchronously from the SAME
  // native root listener) before the real DOM's native capture sweep ever
  // reaches `.tl-container`'s bubble-phase listener — calling
  // `stopPropagation()` here removes the keydown from the event loop
  // entirely before tldraw (or anything else upstream) ever sees it, in
  // every host, not only tldraw's.
  const handleEscapeCapture = (event: KeyboardEvent<ControlElement>) => {
    if (event.nativeEvent.isComposing) return;
    if (event.key !== "Escape") return;
    event.preventDefault();
    event.stopPropagation();
    onCancel?.();
  };

  const handleKeyDown = (event: KeyboardEvent<ControlElement>) => {
    if (event.nativeEvent.isComposing) return;
    const isCommitKey =
      lines === "single" ? event.key === "Enter" : event.key === "Enter" && (event.metaKey || event.ctrlKey);
    if (isCommitKey) {
      event.preventDefault();
      onCommit?.(event.currentTarget.value);
    }
    // Plain Enter on multi falls through untouched — the textarea's own
    // native newline, exactly as the contract asks. Escape is handled
    // entirely by `handleEscapeCapture`, above, and never reaches here.
  };

  const handleBlur = (event: FocusEvent<ControlElement>) => {
    setFocused(false);
    onCommit?.(event.currentTarget.value);
  };

  // WHY these four stop their OWN propagation rather than being gated by a
  // host listener: a right-click must still open the browser's native
  // cut/copy/paste menu (so contextmenu is stopped, never prevented), and a
  // caret click must not re-run whatever pointer-down selection logic the
  // page around this box owns. The control is refusing to be mistaken for
  // the box that contains it — the two-click-to-edit rule itself is host
  // wiring one layer up (docs/TEXTBOX-EDITING-SPEC.md §3), not this file's job.
  const stopPropagation = (event: { stopPropagation: () => void }) => event.stopPropagation();

  const style: CSSProperties = {
    ...CONTROL_TYPOGRAPHY_STYLE,
    // The shadcn focus-ring idiom: no chrome at all until focused, then a
    // ring — never a border/background sitting on the control at rest,
    // which is the whole point of an in-flow control that reads as the text
    // it replaces.
    outline: focused ? "2px solid var(--bbox-ring, currentColor)" : "none",
    outlineOffset: focused ? 2 : undefined,
    ...(focused ? { borderRadius: 4 } : {}),
  };

  // WHY the marker is BOTH a class and a data-attribute, and the core emits
  // both while owning neither's meaning: React Flow gates dragging/panning/
  // wheel by CLASS NAME (`noDragClassName` etc. take a single string), tldraw
  // gates its own gesture start by reading the DOM under the pointer, which
  // an attribute selector matches more cheaply than a class does against an
  // arbitrary host stylesheet. Emitting one host-neutral marker in each
  // vocabulary means this file never imports React Flow or tldraw, and a
  // third host can pick whichever it already gates by.
  const shared = {
    "data-slot": "text-box-input" as const,
    "data-bbox-interactive": "" as const,
    className: "bbox-interactive",
    placeholder,
    readOnly,
    maxLength,
    autoFocus: true,
    onChange: handleChange,
    onKeyDownCapture: handleEscapeCapture,
    onKeyDown: handleKeyDown,
    onFocus: () => setFocused(true),
    onBlur: handleBlur,
    onPointerDown: stopPropagation,
    onClick: stopPropagation,
    onDoubleClick: stopPropagation,
    onContextMenu: stopPropagation,
  };

  if (lines === "multi") {
    return <textarea ref={textareaRef} rows={1} value={value} style={style} {...shared} />;
  }
  return (
    <input
      ref={inputRef}
      type="text"
      value={value}
      style={{ ...style, minWidth: "4ch" }}
      {...shared}
    />
  );
}

/**
 * TextBox = one run of text, sized to its own content plus its own
 * padding. No `w`/`h` prop — a fixed box is whatever the consumer wraps
 * it in (docs/T1-SPEC.md §4.2's "Not a prop" list). `align`/`justify`
 * are real flex properties on this box's own container, so they only
 * become visible once a consumer gives the box an explicit width/height
 * (via `className`/`style`) — exactly the same "declared even though it
 * does nothing until the host opts in" shape as `Port`'s `textLayout`.
 *
 * `children` is intentionally destructured with NO default (see
 * `textBox.fields.ts`'s own comment): omitting it renders a truly empty
 * box, not the placeholder string a panel needs to stay demoable.
 *
 * At rest this is a plain box; when the host sets `editing` (and `children`
 * is a string) the SAME box swaps its text for a native control wearing the
 * same font — option B from the frozen contract, docs/TEXTBOX-EDITING-SPEC.md.
 * Nothing here is a new component.
 */
export function TextBox({
  size = "md",
  sizePx = 24,
  paddingTop = 0,
  paddingBot = 0,
  paddingLeft = 0,
  paddingRight = 0,
  font = "sans",
  align = "middle",
  justify = "middle",
  lines = "single",
  editing = false,
  onChange,
  onCommit,
  onCancel,
  placeholder = "",
  readOnly = false,
  maxLength,
  className,
  style,
  children,
  ...props
}: TextBoxProps) {
  // WHY this is checked here rather than left to the caller: "editing is
  // ignored when children is not a string" is the contract's own escape
  // hatch for a TextBox someone hands non-text `children` — there is no
  // control to type into a ReactNode, so the box just renders rest.
  const isEditingNow = editing && typeof children === "string";
  const isEmptyText = children === undefined || children === "";

  const boxStyle: CSSProperties = {
    fontSize: textBoxFontPx(size, sizePx),
    fontFamily: TEXT_BOX_FONT_STACKS[font],
    alignItems: textBoxAlignItems(align),
    justifyContent: textBoxJustifyContent(justify),
    paddingTop,
    paddingBottom: paddingBot,
    paddingLeft,
    paddingRight,
    // WHY the ROOT itself also needs `minWidth: 0` (verify-round-2 F1's own
    // sweep, found live in `apps/docs`'s real Header · left slot, not just
    // in a synthetic probe): `className` only sets `width: fit-content`
    // (`w-fit`) — it never touches `min-width`, so once THIS box is itself
    // a flex/grid item of a host that tries to squeeze it (a Block header
    // slot's Flex, in the real app), the browser's default automatic
    // minimum size for a flex/grid item is its OWN min-content size, not 0.
    // For a `white-space: nowrap` label that min-content size equals the
    // FULL, untruncated text width — measured live: a Header · left slot
    // held to exactly 107px by a real Block's header grid, the slot's own
    // `Flex` wrapper shrunk to that 107px correctly, and TextBox's ROOT
    // still rendered at 534px, silently overflowing its own 107px parent
    // (parent `overflow: visible`, so nothing even clipped it — the
    // ellipsis fix below had no box narrow enough to ever engage). This is
    // the identical bug class as the inner wrapper's own fix, one level
    // higher: a flex/grid item's min-width doesn't default to 0, `lines`'s
    // whole "single" contract is that this box CAN be squeezed by its host,
    // and nothing else in this file (or its host) is positioned to declare
    // "I am willing to shrink below my own text" on this box's behalf.
    minWidth: 0,
    // WHY the `lines` recipe does NOT live here any more (verify-round-2
    // F1): this root is `inline-flex` (needed so `align`/`justify` can
    // position content once a host gives the box explicit width/height —
    // see this file's own header comment), and CSS `text-overflow` only
    // applies to BLOCK containers, never to a flex container itself — a
    // flex formatting context, not a block one, per the CSS Overflow spec.
    // Chromium silently no-ops it there: measured, a flex root with
    // `justify-content: center` hard-clipped the text at BOTH ends with NO
    // ellipsis glyph at all (docs/TEXTBOX-EDITING-SPEC.md's own "truthful
    // truncation" broken exactly where it mattered most — the default
    // `justify: "middle"`). The recipe now lives on the inner
    // `text-box-content` span below, which is `display: "block"` — a real
    // block container, so `text-overflow` actually paints. Proven in the
    // browser, not just pinned as a style object: empirically confirmed
    // with a headless-Chrome CDP probe (three `justify` values × a 107px
    // container) that this exact shape ellipsizes correctly at every
    // `justify`, and that `justify` still positions the (untruncated) item
    // normally once it fits — see docs/TEXTBOX-EDITING-SPEC.md §4's
    // `assertTruthfulTruncation` journey step.
  };

  // Truthful truncation (docs/TEXTBOX-EDITING-SPEC.md §1, and Zach's own
  // rendering rule): a single-line box may ellipsize its text visually, but
  // the full, untruncated string stays one hover away rather than vanishing.
  // WHY `children !== ""` too, not just `typeof === "string"`: an empty
  // string IS a string, so without this an empty box got `title=""` — a
  // real (if invisible) attribute, not "no title", which is a different,
  // false claim ("hover here, there's truthfully nothing to see") for a box
  // that in fact has no text at all. Empty text has nothing to truncate, so
  // it earns no title, exactly like a box with no `children` prop at all.
  const title = !isEditingNow && lines === "single" && typeof children === "string" && children !== "" ? children : undefined;

  let content: ReactNode;
  if (isEditingNow) {
    content = (
      <TextBoxControl
        lines={lines}
        value={children as string}
        placeholder={placeholder}
        readOnly={readOnly}
        maxLength={maxLength}
        onChange={onChange}
        onCommit={onCommit}
        onCancel={onCancel}
      />
    );
  } else if (isEmptyText && !placeholder) {
    // Truly empty (no text, no placeholder): render nothing at all, not a
    // phantom wrapper span — the box stays exactly as empty as it was
    // before this file grew a truncation wrapper. `textBox.behavior.test.ts`
    // pins this ("no placeholder configured renders truly empty, not a
    // phantom node").
    content = children;
  } else {
    const rest = isEmptyText && placeholder ? (
      <span data-placeholder="" style={{ opacity: 0.5 }}>
        {placeholder}
      </span>
    ) : (
      children
    );
    // WHY this wrapper exists at all (verify-round-2 F1): it is the ONE
    // real block container in the tree, so the `lines` recipe (declared on
    // it, not on the `inline-flex` root above) actually has a block box to
    // clip/wrap against. `minWidth: 0` overrides the flex item's own
    // default `min-width: auto`, which otherwise refuses to shrink the
    // item below its content's intrinsic width no matter how narrow the
    // host's slot is — the OTHER half of why the root's flex children never
    // actually overflowed far enough to need clipping in the first place.
    // `maxWidth: "100%"` is what lets it shrink to fill exactly the root's
    // available width once content is wider than that, which is also what
    // makes `justify` (positioning the item on the root's main axis)
    // correctly become a no-op the instant truncation kicks in — an item
    // clamped to 100% of its container has no spare space left to be
    // positioned within, so it reads flush regardless of `justify`. Ellipsis
    // itself always lands at the text's trailing (end) edge, independent of
    // `justify` — verified empirically (headless-Chrome CDP probe): a real
    // block box with `text-align: left|center|right` painted the identical
    // truncated string in all three, because `text-overflow` clips/marks
    // the inline-end edge of the LINE BOX, not wherever `text-align`
    // happens to have centered the (already-overflowing) text within it.
    content = (
      <span
        data-slot="text-box-content"
        style={
          lines === "single"
            ? { display: "block", minWidth: 0, maxWidth: "100%", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }
            : { display: "block", minWidth: 0, maxWidth: "100%", whiteSpace: "pre-wrap", overflowWrap: "anywhere" }
        }
      >
        {rest}
      </span>
    );
  }

  return (
    <div
      data-slot="text-box"
      data-size={size}
      data-font={font}
      data-align={align}
      data-justify={justify}
      data-lines={lines}
      // WHY the raw `editing` prop and not `isEditingNow`: `data-editing` is
      // a truthful record of what the HOST asked for, not of what actually
      // rendered — the one case they diverge is `editing=true` with
      // non-string `children`, where the contract says "ignored" (no
      // control mounts) but the host's intent to edit this instance is
      // still real and still worth a probe/CSS hook being able to see.
      // Hiding that behind the derived, effective value would make this
      // attribute lie about what was actually passed in.
      data-editing={editing}
      title={title}
      className={cn("inline-flex w-fit leading-tight", className)}
      style={{ ...boxStyle, ...style }}
      {...props}
    >
      {content}
    </div>
  );
}

/**
 * packages/bbox-ui/src/trace.fields.ts
 *
 * `Trace`'s controllable props as data — mirrors `port.fields.ts` /
 * `pill.fields.ts`'s own pattern: a flat `FieldSpec[]`, real component prop
 * ids, no separate mapping table.
 *
 * DEVIATION from an earlier proposal draft
 * (`reports/trace-edge-primitive-proposal-2026-09-14.html`): that sketch
 * modelled `strokeColor` as governed by a `variant`-selected preset family
 * (mirroring Pill's `state` → `PILL_PRESETS`). Implementing it surfaced
 * that the preset had no real donor behind it — SystemSketch's own cable
 * colour comes from a connection's semantic role, a completely different
 * axis from its temporal kind (`data`/`async`/`delayed`), so a
 * variant-keyed colour preset would have been invented, not ported.
 * `variant` here governs dash MECHANICS only (`traceStrokeStyle`, in
 * `trace.tsx`); `strokeColor` is a plain, ungoverned field — same
 * footing as Pill's own `lineThickness`/`lineOpacity` — with `tone` as
 * the sole override escape hatch, exactly Pill's real mechanism minus the
 * preset layer neither has a motivated use for here.
 */
import type { FieldOption, FieldSpec } from "./schema";
import { LENS_FIELD, TONE_FIELD } from "./appearance.fields";
import { PAINT_TOKENS } from "./pill.fields";
import {
  LABEL_POSITION_DEFAULT,
  LABEL_POSITION_MAX,
  LABEL_POSITION_MIN,
  TRACE_VARIANT_LABELS,
  TRACE_VARIANTS,
} from "./trace.layout";

const VARIANT_OPTIONS: FieldOption[] = TRACE_VARIANTS.map((variant) => ({
  value: variant,
  label: TRACE_VARIANT_LABELS[variant],
}));

const STROKE_COLOR_OPTIONS: FieldOption[] = PAINT_TOKENS.map((token) => ({
  value: token,
  label: token,
}));

export const TRACE_MARKER_ENDS = ["arrow", "none"] as const;
export type TraceMarkerEnd = (typeof TRACE_MARKER_ENDS)[number];
const MARKER_END_OPTIONS: FieldOption[] = TRACE_MARKER_ENDS.map((value) => ({
  value,
  label: value === "arrow" ? "Arrow" : "None",
}));

export const VARIANT_FIELD: FieldSpec = {
  id: "variant",
  label: "Variant",
  kind: "segments",
  defaultValue: "data",
  options: VARIANT_OPTIONS,
  hint: "Dash mechanics only (traceStrokeStyle) — never colour. See this file's own deviation note.",
};

export const STROKE_COLOR_FIELD: FieldSpec = {
  id: "strokeColor",
  label: "Stroke Color",
  kind: "segments",
  defaultValue: "foreground",
  options: STROKE_COLOR_OPTIONS,
  hint: "Ungoverned — always freely editable, same footing as Pill's lineThickness/lineOpacity. `tone` overrides it when set.",
};

export const ANIMATED_FIELD: FieldSpec = {
  id: "animated",
  label: "Animated",
  kind: "toggle",
  defaultValue: false,
  hint: "Marching-ants, `variant:\"data\"` only. Opt-in — on-by-default proved too loud (2026-09-14 lesson).",
};

export const SPLIT_AT_LABEL_FIELD: FieldSpec = {
  id: "splitAtLabel",
  label: "Split At Label",
  kind: "toggle",
  defaultValue: false,
  hint: '`variant:"delayed"` only — dotted end-to-end (false, SystemSketch\'s own default) vs solid-before/dotted-after `labelPosition`.',
};

export const LABEL_POSITION_FIELD: FieldSpec = {
  id: "labelPosition",
  label: "Label Position",
  kind: "number",
  defaultValue: LABEL_POSITION_DEFAULT,
  min: LABEL_POSITION_MIN,
  max: LABEL_POSITION_MAX,
  step: 0.01,
  hint: "Clamped off the terminals (0.05..0.95, SystemSketch's own PILL_POSITION_MIN/MAX) — a label on top of a port reads as part of it.",
};

export const MARKER_END_FIELD: FieldSpec = {
  id: "markerEnd",
  label: "Marker End",
  kind: "segments",
  defaultValue: "arrow",
  options: MARKER_END_OPTIONS,
};

export const TRACE_FIELDS: FieldSpec[] = [
  VARIANT_FIELD,
  STROKE_COLOR_FIELD,
  TONE_FIELD,
  LENS_FIELD,
  ANIMATED_FIELD,
  SPLIT_AT_LABEL_FIELD,
  LABEL_POSITION_FIELD,
  MARKER_END_FIELD,
];

/**
 * packages/bbox-ui/src/trace.layout.ts
 *
 * `Trace`'s portable geometry — no React, no host engine, no DOM. A trace's
 * `path` and `length` are host-computed (React Flow's `getBezierPath`,
 * tldraw's own arrow info); everything here operates on the RESULT of that
 * math, never derives it.
 *
 * Ported from SystemSketch's `connectionPresentation.ts`, minus what
 * doesn't belong in a general primitive: the live `cablePresentation` atom
 * (a board-wide viewing preference, no equivalent concept in bbox-ui), its
 * localStorage read/write, and the `z⁻¹`/`mut` pill-glyph vocabulary
 * (SystemSketch's own dataflow semantics — see `trace.tsx`'s `TraceLabel`,
 * which takes arbitrary content instead).
 */

/**
 * A host's own trace/edge id (React Flow's edge `id`, a tldraw shape's
 * `id`) turned into a legal, GENUINELY COLLISION-FREE SVG element id.
 *
 * DEVIATION found by adversarial review, TWICE (2026-09-15) — first
 * against a strip-based version, then again against this function's own
 * first fix:
 *
 * v1 simply stripped every character outside `[a-zA-Z0-9_-]`, which is
 * LOSSY — `"edge.a"` and `"edgea"` both stripped down to the identical
 * `"edgea"`.
 *
 * v2 replaced that with a 32-bit FNV-1a hash, reasoning that hashing the
 * FULL id (rather than dropping characters) would "essentially never"
 * collide. That reasoning was wrong, and adversarial review found a real
 * counter-example in seconds: `"edge-e1e5ffef518ed9d7"` and
 * `"edge-e900fd5e0596d262"` both hash to the identical
 * `bbox-trace-head-1hghfsz`. A FIXED-SIZE hash is lossy by the pigeonhole
 * principle — 32 bits is only ~4.3 billion buckets, and the birthday bound
 * puts a 50% collision chance at ~77,000 random ids, not some safely
 * large number. "Essentially never" was an unverified guess, not a proof.
 *
 * v3 (this version) hex-encoded the id's UTF-8 bytes via `TextEncoder`,
 * reasoning that a bijective transform would GENUINELY never collide —
 * true for well-formed Unicode, but adversarial review found a THIRD
 * real counter-example: `TextEncoder` is only defined over well-formed
 * text, and per the WHATWG encoding spec it replaces any LONE (unpaired)
 * UTF-16 surrogate with U+FFFD before encoding to UTF-8 — a real, lossy
 * step this function's own doc comment had missed. `"\uD800"` (a lone
 * high surrogate), `"\uDC00"` (a lone low surrogate), and the literal
 * `"�"` character all encode to the identical UTF-8 bytes and
 * therefore the identical id. A JS string is technically a sequence of
 * UTF-16 CODE UNITS, not well-formed Unicode text — `"\uD800"` is a
 * perfectly legal (if unusual) JS string, so "well-formed Unicode" was
 * silently narrower than "any input."
 *
 * The actual fix: stop going through UTF-8 (or any text encoding) at
 * all. Encode each UTF-16 CODE UNIT directly — exactly what
 * `id.length`/`id.charCodeAt(i)` already read a JS string AS. This is a
 * bijection over the true, complete domain (every possible JS string,
 * lone surrogates included), not over "well-formed text," because it
 * never interprets the code units as anything — it just writes each one
 * down in hex.
 */
export function safeElementId(prefix: string, id: string): string {
  let hex = "";
  for (let i = 0; i < id.length; i += 1) {
    hex += id.charCodeAt(i).toString(16).padStart(4, "0");
  }
  return `${prefix}-${hex}`;
}

export const TRACE_VARIANTS = ["data", "async", "delayed"] as const;
export type TraceVariant = (typeof TRACE_VARIANTS)[number];
export const TRACE_VARIANT_LABELS: Record<TraceVariant, string> = {
  data: "Data",
  async: "Async",
  delayed: "Delayed",
};

/* ------------------------------- geometry -------------------------------- */

export function polylineLength(points: readonly { x: number; y: number }[]): number {
  let length = 0;
  for (let index = 1; index < points.length; index += 1) {
    length += Math.hypot(points[index].x - points[index - 1].x, points[index].y - points[index - 1].y);
  }
  return length;
}

/** The point a fraction `t` of the arc length along the polyline. */
export function pointAtFraction(
  points: readonly { x: number; y: number }[],
  t: number,
): { x: number; y: number } {
  if (points.length === 0) return { x: 0, y: 0 };
  if (points.length === 1) return { x: points[0].x, y: points[0].y };
  const total = polylineLength(points);
  let target = Math.min(1, Math.max(0, t)) * total;
  for (let index = 1; index < points.length; index += 1) {
    const a = points[index - 1];
    const b = points[index];
    const segment = Math.hypot(b.x - a.x, b.y - a.y);
    if (target <= segment || index === points.length - 1) {
      const u = segment === 0 ? 0 : Math.min(1, target / segment);
      return { x: a.x + (b.x - a.x) * u, y: a.y + (b.y - a.y) * u };
    }
    target -= segment;
  }
  const last = points[points.length - 1];
  return { x: last.x, y: last.y };
}

/**
 * The arc-length fraction of the polyline point nearest `p` — where a
 * dragged label lands. Host-owned drag math (`labelPosition` is the
 * number a host WRITES back after a drag), kept here because it is pure.
 */
export function fractionNearest(points: readonly { x: number; y: number }[], p: { x: number; y: number }): number {
  if (points.length < 2) return 0.5;
  const total = polylineLength(points);
  if (total === 0) return 0.5;
  let best = { distance: Number.POSITIVE_INFINITY, length: 0 };
  let walked = 0;
  for (let index = 1; index < points.length; index += 1) {
    const a = points[index - 1];
    const b = points[index];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const segment = Math.hypot(dx, dy);
    const u = segment === 0 ? 0 : Math.min(1, Math.max(0, ((p.x - a.x) * dx + (p.y - a.y) * dy) / (segment * segment)));
    const qx = a.x + dx * u;
    const qy = a.y + dy * u;
    const distance = Math.hypot(p.x - qx, p.y - qy);
    if (distance < best.distance) best = { distance, length: walked + segment * u };
    walked += segment;
  }
  return best.length / total;
}

/* ------------------------------ label position ---------------------------- */

/** Kept off the terminals — a label sitting exactly on a port reads as
 * part of it, not a fact about the trace. Same bounds as SystemSketch's
 * own `PILL_POSITION_MIN`/`MAX` (`connectionModel.ts`). */
export const LABEL_POSITION_MIN = 0.05;
export const LABEL_POSITION_MAX = 0.95;
export const LABEL_POSITION_DEFAULT = 0.5;

export function clampLabelPosition(t: number): number {
  return Math.min(LABEL_POSITION_MAX, Math.max(LABEL_POSITION_MIN, t));
}

/* ------------------------------ dash arrays ------------------------------ */

/**
 * `async`: equal rests between small packet marks. SVG alternates paint
 * and gaps, so this reads as a 56-unit carrier, 4-unit micro-gap, 10-unit
 * packet, then another 4-unit micro-gap before the cadence repeats. Butt
 * caps keep the tiny gaps legible instead of visually closing them with
 * round end caps. Numbers unchanged from SystemSketch's own
 * `ASYNC_PACKET_DASHARRAY` — this is the board's visual grammar, not a
 * library's, and porting it is a rename of ownership, not a rewrite.
 */
export const ASYNC_CARRIER_PX = 56;
export const ASYNC_PACKET_GAP_PX = 4;
export const ASYNC_PACKET_PX = 10;
export const ASYNC_PACKET_DASHARRAY = `${ASYNC_CARRIER_PX} ${ASYNC_PACKET_GAP_PX} ${ASYNC_PACKET_PX} ${ASYNC_PACKET_GAP_PX}`;
export const ASYNC_CADENCE_PX = ASYNC_CARRIER_PX + ASYNC_PACKET_GAP_PX * 2 + ASYNC_PACKET_PX;

/**
 * Below one full cadence there is not enough path to reach both
 * micro-gaps, so phase just that short run to centre one complete
 * gap–packet–gap mark. The cadence itself never changes.
 */
export function asyncDashOffsetForLength(lengthPx: number): number {
  if (!Number.isFinite(lengthPx) || lengthPx >= ASYNC_CADENCE_PX) return 0;
  const packetMark = ASYNC_PACKET_GAP_PX * 2 + ASYNC_PACKET_PX;
  const markStart = Math.max(0, (Math.max(0, lengthPx) - packetMark) / 2);
  return ASYNC_CARRIER_PX - markStart;
}

/**
 * `data`, opt-in `animated`: React Flow's own homepage marching-ants line
 * (`stroke-dasharray: 5px`). Opt-in, never a default — the 2026-09-14
 * lesson `connectionPresentation.ts` already recorded: on-by-default
 * proved too loud.
 */
export const DATA_MARCH_DASH_PX = 5;
export const DATA_MARCH_DASHARRAY = `${DATA_MARCH_DASH_PX}`;
/**
 * The keyframe's own from→to span. CSS can't reference this constant
 * directly — `theme.css`'s `.bbox-trace-march` keyframes hardcode the
 * same `10`/`0` literally — so this exists as the pinned value a test
 * checks the CSS file's text against, catching drift if `DATA_MARCH_DASH_PX`
 * ever changes without the keyframes changing to match.
 */
export const DATA_MARCH_DASHOFFSET_PX = DATA_MARCH_DASH_PX * 2;

/** The dot: a zero-length dash with a round cap paints a disc of the
 * stroke width. */
export const DELAY_DOT_PX = 0.1;
export const DELAY_DOT_GAP_PX = 6;

/** `pathLength` the split paths are normalised to, so dashes are set in
 * path units rather than pixels — the split stays correct at any zoom. */
export const PATH_LENGTH_UNITS = 1000;

export interface SplitDashArrays {
  /** Solid up to the label, then a gap that outlasts the path. */
  before: string;
  /** A gap up to the label, then dotted to the end, then a gap that outlasts the path. */
  after: string;
}

/**
 * Hard ceiling on how many dot/gap pairs `splitDashArrays` ever builds.
 *
 * DEVIATION found by adversarial review (2026-09-15): the first version
 * of this function filled the dotted run with an open-ended
 * `while (covered < PATH_LENGTH_UNITS) { ...; covered += dot + dotGap }`
 * loop. For an ordinary `lengthPx` (tens to thousands of real pixels)
 * that terminates in well under 200 iterations — but nothing validated
 * `lengthPx`, and a pathologically large value (`Infinity`,
 * `Number.MAX_VALUE`, or anything astronomically large) drives `unit`
 * toward 0, so `dot`/`dotGap` underflow toward 0 and `covered` stops
 * advancing at all — a genuine infinite loop that crashed with
 * `RangeError: Invalid array length` once the array hit JS's engine
 * limit, found live by running exactly that input. A closed-form dot
 * COUNT, computed once and capped, replaces the loop outright: no input,
 * however degenerate, can make this function run unbounded work again.
 * The cap itself is generous for anything real — a normal `delayed`
 * trace's dotted run is under 200 dots even at large pixel lengths.
 */
const MAX_DELAY_DOTS = 2000;

/**
 * Two dash arrays that, drawn on the same path with `pathLength=1000`,
 * paint solid before the split point and dots after it. Each pattern ends
 * with a gap of a full path so SVG's repeating never spills one style
 * into the other's run.
 */
export function splitDashArrays(lengthPx: number, t: number): SplitDashArrays {
  const fraction = clampLabelPosition(t);
  const unit = Number.isFinite(lengthPx) && lengthPx > 0 ? PATH_LENGTH_UNITS / lengthPx : 1;
  const dot = DELAY_DOT_PX * unit;
  const dotGap = DELAY_DOT_GAP_PX * unit;
  const splitAt = fraction * PATH_LENGTH_UNITS;

  const before: number[] = [splitAt, PATH_LENGTH_UNITS];

  const pairSpan = dot + dotGap;
  const remaining = PATH_LENGTH_UNITS - splitAt;
  const dotCount = pairSpan > 0 && Number.isFinite(pairSpan)
    ? Math.min(MAX_DELAY_DOTS, Math.ceil(remaining / pairSpan))
    : 0;

  const after: number[] = [0, splitAt];
  for (let i = 0; i < dotCount; i += 1) after.push(dot, dotGap);
  after.push(0, PATH_LENGTH_UNITS);

  const round = (value: number) => Number(value.toFixed(3));
  return {
    before: before.map(round).join(" "),
    after: after.map(round).join(" "),
  };
}

import type { ComponentProps, ReactNode } from "react";
import { toneOverride, type Tone } from "./appearance";
import { sketchPathData } from "./sketchPath";
import { paintColor, Pill, type PillProps } from "./pill";
import type { PaintToken } from "./pill.fields";
import type { TraceMarkerEnd } from "./trace.fields";
import {
  ASYNC_PACKET_DASHARRAY,
  DATA_MARCH_DASHARRAY,
  DELAY_DOT_GAP_PX,
  DELAY_DOT_PX,
  LABEL_POSITION_DEFAULT,
  PATH_LENGTH_UNITS,
  asyncDashOffsetForLength,
  clampLabelPosition,
  safeElementId,
  splitDashArrays,
  type TraceVariant,
} from "./trace.layout";

/**
 * packages/bbox-ui/src/trace.tsx
 *
 * Trace = the paint for a two-ended shape whose PATH a host computes
 * (React Flow's `getBezierPath`, tldraw's own arrow info) and whose ROUTE
 * a host owns interaction for. Trace never derives a point, never binds a
 * terminal, never listens for a pointer — same promise `ARCHITECTURE.md`
 * makes for `Port`/`Block`. See the proposal this implements:
 * `reports/trace-edge-primitive-proposal-2026-09-14.html`.
 */

export interface TraceProps extends Omit<ComponentProps<"g">, "className" | "style" | "id"> {
  /**
   * The host's own id for this trace (React Flow's edge `id`, a tldraw
   * shape's `id`) — hex-encoded into the marker's DOM id
   * (`safeElementId("bbox-trace-head", id)`, `trace.layout.ts`) so
   * multiple Trace instances on one page never collide. See that
   * function's own doc comment for two rounds of adversarial review this
   * genuinely needed: a strip-based v1 was lossy, and a hash-based v2
   * "essentially never" collided until a real counter-example was found
   * in seconds — hex-encoding is BIJECTIVE, not probabilistic, which is
   * why it's what ships. Deliberately NOT generated internally (no
   * `useId()`):
   * an id `TraceBody` invents itself would be identity this component
   * doesn't own, and it would make `TraceBody` uncallable as the plain
   * function this repo's own tests rely on (`pill.fields.test.ts`'s
   * documented pattern) — hooks require a real render. Matches
   * SystemSketch's own precedent: its marker id is
   * `systemsketch-slanted-arrowhead-${shape.id}`, derived from the real
   * shape, never generated.
   */
  id: string;
  /** The finished path — a host computes this. Trace never derives its own points. */
  path: string;
  /**
   * Arc length of `path`, for dash-phase math (async centering, the
   * delayed split). NOT the straight endpoint distance — a curve is
   * longer than its chord. Neither host hands this over uniformly (RF's
   * path helpers return no length at all; tldraw has one only for some
   * arrow types) — the host-agnostic way to get it is
   * `SVGPathElement.getTotalLength()` on the mounted path, which is
   * adapter work this core package does not perform itself.
   */
  length: number;
  variant?: TraceVariant;
  /** Ungoverned — always freely editable. `tone` overrides it when set. */
  strokeColor?: PaintToken;
  tone?: Tone;
  /** Marching-ants, `variant:"data"` only, opt-in. */
  animated?: boolean;
  /** `variant:"delayed"` only — see `trace.fields.ts`'s own doc. */
  splitAtLabel?: boolean;
  /** Where 0..1 along the path the delayed split lands — clamped to
   * 0.05..0.95 regardless of what's passed (`clampLabelPosition`). */
  labelPosition?: number;
  markerEnd?: TraceMarkerEnd;
  strokeWidth?: number;
  vectorEffect?: "non-scaling-stroke";
}

/**
 * The resolved stroke colour — `strokeColor` (or its "foreground"
 * default), reached past by `tone` when set. Deliberately NOT a
 * preset/`resolveField` cascade: see `trace.fields.ts`'s own deviation
 * note for why `variant` never governs colour here. Exported so an
 * adapter's marker colour and stroke colour are always the SAME call,
 * never two independently-derived values.
 */
export function resolveTraceStrokeColor(tone: Tone, strokeColor: PaintToken = "foreground"): string {
  const subject: Record<string, unknown> = { strokeColor, ...toneOverride(tone, ["strokeColor"]) };
  const token = (subject.strokeColor as PaintToken | undefined) ?? "foreground";
  return paintColor(token, 1);
}

export interface TraceStrokeStyle {
  strokeDasharray?: string;
  strokeDashoffset?: number;
  strokeLinecap: "round" | "butt";
  /** Marching-ants class — DATA ONLY, never applied as a side effect by
   * this function. The caller puts it on the rendered element's
   * `className`, never inside `style`. */
  className?: string;
}

/**
 * Pure — no DOM. Dash MECHANICS only (pattern, phase/offset, the
 * marching-ants class NAME), never colour — see `resolveTraceStrokeColor`
 * for that separate resolution. An adapter calls this directly when
 * assembling React Flow's own `BaseEdge` `style` prop for the
 * single-stroke variants (`data`/`async`).
 */
export function traceStrokeStyle(
  variant: TraceVariant,
  length: number,
  animated = false,
): TraceStrokeStyle {
  if (variant === "async") {
    return {
      strokeDasharray: ASYNC_PACKET_DASHARRAY,
      strokeDashoffset: asyncDashOffsetForLength(length),
      strokeLinecap: "butt",
    };
  }
  if (variant === "delayed") {
    return {
      strokeDasharray: `${DELAY_DOT_PX} ${DELAY_DOT_GAP_PX}`,
      strokeLinecap: "round",
    };
  }
  const marching = animated;
  return {
    strokeDasharray: marching ? DATA_MARCH_DASHARRAY : undefined,
    strokeLinecap: marching ? "butt" : "round",
    className: marching ? "bbox-trace-march" : undefined,
  };
}

/** Marker geometry lives once, referenced by every variant that draws a
 * head — the open two-stroke chevron `SlantedArrowBody` established,
 * `context-stroke` (a real SVG2 paint keyword, confirmed via
 * `CSS.supports("stroke", "context-stroke")` in this session's own
 * Chromium; broad Chromium/Firefox support per MDN, NOT YET Safari —
 * there the marker falls back to its own unspecified default stroke
 * rather than erroring, a degraded look, not a broken one) makes it
 * inherit whatever stroke paints the line beside it, so it never needs a
 * second colour derivation or a duplicate
 * marker per colour. */
/**
 * `style` for the crisp path and for its hand-drawn twin.
 *
 * WHY both are rendered and CSS picks, rather than the component choosing:
 * it cannot know the active skin. Everywhere else a skin blanks the crisp
 * version by recolouring it (`--bbox-skin-stroke: transparent`), which
 * works because a border can be transparent and still occupy its space. An
 * SVG path has no equivalent — and a Trace's geometry belongs to the HOST
 * (React Flow's `getBezierPath`, tldraw's arrow info), so there is nothing
 * here to re-derive. Paths do not affect layout, so the hidden twin costs
 * only the memoised math.
 *
 * WHY the twin is written out at each call site instead of behind a
 * `<TraceSegment>` component: `trace.test.ts` reads this component's
 * returned tree directly and asserts on real `<path>` elements. A
 * component boundary would have replaced every one of them with an
 * unrendered function and forced a rewrite of assertions that are about
 * the DOM contract, not about the internals. Flat stays testable.
 *
 * Zach, 2026-09-17: "it would be great of course if even the traces can
 * support a more sketchy appearance... perhaps thats just like another
 * styling thing for them. just like async, or animated" — so it is exactly
 * that: orthogonal to `variant`, to `animated` and to the dash cadence. A
 * sketched trace can still be an animated async one.
 */
const CRISP_STYLE = { display: "var(--bbox-skin-crisp, inline)" } as const;
const SKETCH_STYLE = { display: "var(--bbox-skin-outline, none)" } as const;

/** Wobble for a cable. Lower than a Block's: the same absolute wander read
 * across a long curve is a wave, not a drawn line. */
const TRACE_WOBBLE_PX = 1.4;

/**
 * Sketched paths, cached by the geometry that produced them.
 *
 * WHY a module-level Map and NOT `useMemo`: `TraceBody` is called
 * plain-function style, with no renderer at all — `trace.test.ts` does
 * exactly that, and its own describe block says so ("called plain-function
 * style (no DOM/jsdom)"). A hook there throws on a null dispatcher. That
 * property is worth keeping: it is what lets the paint be tested without
 * jsdom, and a cache keyed on the input is strictly better than a hook
 * here anyway — it is shared across instances and survives remounts.
 *
 * Bounded because a live drag produces a NEW `d` every frame, so an
 * unbounded cache would be a leak that looks like a memo. Insertion order
 * is eviction order, which is all this needs: the entries worth keeping
 * are the ones for edges sitting still, and those get re-inserted on their
 * next hit.
 */
const SKETCH_CACHE = new Map<string, string>();
const SKETCH_CACHE_MAX = 512;

function sketchedTracePath(d: string): string {
  const hit = SKETCH_CACHE.get(d);
  if (hit !== undefined) return hit;
  const out = sketchPathData(d, { seed: d, wobble: TRACE_WOBBLE_PX });
  if (SKETCH_CACHE.size >= SKETCH_CACHE_MAX) {
    const oldest = SKETCH_CACHE.keys().next().value;
    if (oldest !== undefined) SKETCH_CACHE.delete(oldest);
  }
  SKETCH_CACHE.set(d, out);
  return out;
}

export function TraceMarkerDef({ id }: { id: string }) {
  return (
    <marker
      id={id}
      viewBox="0 0 10 10"
      refX="8.5"
      refY="5"
      markerWidth="7"
      markerHeight="7"
      orient="auto"
      overflow="visible"
    >
      <path
        d="M 1 1 L 9 5 L 1 9"
        fill="none"
        stroke="context-stroke"
        strokeWidth={2}
        strokeLinejoin="round"
        strokeLinecap="round"
      />
    </marker>
  );
}

/**
 * The paint — one `<path>` for `data`/`async`, two for a `delayed` trace
 * with `splitAtLabel`. Zero imports of either canvas engine.
 */
export function TraceBody({
  id,
  path,
  length,
  variant = "data",
  strokeColor = "foreground",
  tone = "neutral",
  animated = false,
  splitAtLabel = false,
  labelPosition = LABEL_POSITION_DEFAULT,
  markerEnd = "arrow",
  strokeWidth = 2,
  vectorEffect,
  ...props
}: TraceProps) {
  const markerId = safeElementId("bbox-trace-head", id);
  const stroke = resolveTraceStrokeColor(tone, strokeColor);
  // Seeded from the geometry itself, so a cable keeps its own wander while
  // it sits still and re-draws honestly when it moves.
  const sketched = sketchedTracePath(path);
  const hasMarker = markerEnd !== "none";
  const markerAttr = hasMarker ? `url(#${markerId})` : undefined;

  if (variant === "delayed" && splitAtLabel) {
    const dash = splitDashArrays(length, clampLabelPosition(labelPosition));
    const splitSegment = {
      pathLength: PATH_LENGTH_UNITS,
      fill: "none",
      stroke,
      strokeLinecap: "round" as const,
      strokeLinejoin: "round" as const,
      strokeWidth,
      vectorEffect,
    };
    return (
      <g data-slot="trace" data-variant={variant} {...props}>
        {hasMarker && (
          <defs>
            <TraceMarkerDef id={markerId} />
          </defs>
        )}
        <path {...splitSegment} d={path} strokeDasharray={dash.before} data-trace-segment="before" style={CRISP_STYLE} />
        <path {...splitSegment} d={sketched} strokeDasharray={dash.before} data-trace-segment="before" data-sketch="true" style={SKETCH_STYLE} />
        <path {...splitSegment} d={path} strokeDasharray={dash.after} markerEnd={markerAttr} data-trace-segment="after" style={CRISP_STYLE} />
        <path {...splitSegment} d={sketched} strokeDasharray={dash.after} markerEnd={markerAttr} data-trace-segment="after" data-sketch="true" style={SKETCH_STYLE} />
      </g>
    );
  }

  const dashStyle = traceStrokeStyle(variant, length, animated);
  const segment = {
    fill: "none",
    stroke,
    strokeWidth,
    strokeLinecap: dashStyle.strokeLinecap,
    strokeLinejoin: "round" as const,
    strokeDasharray: dashStyle.strokeDasharray,
    strokeDashoffset: dashStyle.strokeDashoffset,
    vectorEffect,
    className: dashStyle.className,
    markerEnd: markerAttr,
  };
  return (
    <g data-slot="trace" data-variant={variant} {...props}>
      {hasMarker && (
        <defs>
          <TraceMarkerDef id={markerId} />
        </defs>
      )}
      <path {...segment} d={path} style={CRISP_STYLE} />
      <path {...segment} d={sketched} data-sketch="true" style={SKETCH_STYLE} />
    </g>
  );
}

/**
 * The label chip. Reuses `Pill` rather than inventing a twin — stays DOM
 * like every other bbox-ui text slot. `TraceBody` never renders this: a
 * label's PIXEL position needs the host's own point-at-fraction over a
 * REAL point array, which an opaque SVG `path` string doesn't carry
 * (`trace.layout.ts`'s `pointAtFraction` is exactly that math, for a host
 * that has the points). Positioning is entirely host-owned — React Flow's
 * `EdgeLabelRenderer`, tldraw's own `HTMLContainer`/absolute div — so this
 * component only ever renders the chip itself, never a transform. `tone`
 * is NOT automatic from a sibling `TraceBody`: pass it explicitly to
 * both, same as `PortEdge`'s `cascadeInto` never auto-cascades `tone`
 * either.
 */
export function TraceLabel({ children, ...pillProps }: PillProps): ReactNode {
  return (
    <Pill data-slot="trace-label" {...pillProps}>
      {children}
    </Pill>
  );
}
